INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('be169506-3bfb-5643-9c32-f3c41af98620','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YKS LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'c1a577e6-67ec-5a05-9bc9-7b11013e0a42'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-04-29','Yüksel Çalıkdor - Halil Çalıkdor','YKS Firması son 2 yılda Eskişehirde Özkan otomotiv in bölgede Ticari lastik operasyon boşluğundan faydalanarak var olmuş  . Bu yıl başında Michelin bayiliği almış durumdalar. Benim bir önceki dönem sonunda tanıştığım ve Hüseyine devir ettiğim firmadır.Firma 15 Adet tırlarını satarak babadan nakliyeci olan firma  lastik sektörüne girmiş durumdalar. En son toplatıda konuştuğumuz gibi sonradan sektör değiştirmiş ve şu anda gözde olarak görünen fakat bence risk taşıyan durumdalar. Kontrollü Ticaret gerekli olduğunu düşünüyorum. Eskşehir de sağlam olarak bilinen Sarp Nakliyat- Can nakliyat - Beycan lojistik  gibi 20 ye yakın filoyla çalışıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d9e7e241-7521-585f-b83e-63562a6ce657','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AND LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ab397ae5-ec14-5e3f-9dc1-8097f3166289'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-04-29','Ünal Ateş','Sizlerinde iyi tanıdğı Eski Yayla . Eski Brisa bayisi kendilerinin bayiliğinden sonra Brisaın bölgede bayi bulmak için çok uğraştığını uzun süre bölgede sıkıntı yaşandığını iletti. AND lastik olarak Kamyon Brisa  grubu lastiklerin satış adetinin bölge bayisi Özkan otomotiv den fazla olduğunu idda etti. Ünal bey Eskişehir ve bölgesinde son yıllarda Pazarda ya alt seviye Çin malı lastikler yada üst seviye lastiklerin satıldığı. Ara kalite Kumho tarzı lastiklerin satışının zorlaştığını belirtiyorlar.  B2B Lastik Ara Portalı açıldı Brisa ürünleri dışındaki ticareti takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('778e0387-51ff-5239-b99d-0600d7050785','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NEMLİ TAŞIMACILIK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'e1f69dcd-0cb1-579a-a85f-c4f672ac3491'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-04-29','Ahmet Toy','Eskişehir Magnesit A.ş.nin en büyük taşerönü konumundalar. Petlas ile direk fabrika dan çalışıyorlar. Magnesit sahası içerisinde 80 adet civarında hafriyat kamyonları mevcut . Petlas çalışma şekilleri itibariyle görüşme  İş makinası ,kamyon yenileme ve kauçuk markaları  üzerinden gerçekleşti. Firamnın başka alanlarda çalıştığı projeler olduğu Magnesitin Taşerönlüğüne bağlı kalmanın bir yere kadar kendilerini taşıdığını büyümek için başka sektörlerdede var olmak gerektiğini düşünüyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('da36b316-bd62-5a52-adea-47fea913ddfd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAGNESİT A.Ş.' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8ca82b4d-5017-52bc-b85e-35bb35f5b074'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-04-29','İshak Özcan','Magnesit A.Ş. İle İş makinası yenileme üzerine çalışmalrımız geçmiş dönemde oluyordu. Fakat şu dönemde Atlı ile çalıştıkları bilgisini aldım. Veilen hizmetten çok büyük sorunları olmadığını fakat. Bİlgidarlığımız ve Turgay EFEnin kadmede olan kiilerle kurmuş olduğu diyaloğu aradıklarını ilettiler. Magnesitin saha şartlarında bir çok test ve deneme yaparak iyileştirme yapmak için çabalarımız olmuştu. Eski dönemde çalışmaya kademe sorumlusu karar veriyordu. Yeni düzenlerinde işi Satın alma departmanları üstlenmiş. Yapılacak çalışma ile Manesitin KRB ye geri kazandırılması için gerekli stratejiler oluşturulacaktır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a9a3a30d-38a2-5344-a18d-e4deb3037fc5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e6c4c63a-1a2c-5a2e-9e1e-6399d789e3a0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-04-29','Mehmet Ünaldı','Ünaldı maden firması Kütahya Kümaşın Taşerölüğü nü yapan Mutaş maden nin ayrılması sonrası İhaleyi alan yeni Firma .Tavşanlı merkezli firmaya Komatsu marka  İş makinalarını satan kişi Volvo birlikte çalıştığım arkaşım olması sebebi ile sağ olsun bizim için randu aldı ve firma Sahibi emhmet Ünaldı ile görüşme şansımız oldu. Proje Mart ayında başlamış ve daha onlarda yeni apate olmaya çalışıyorlar. Firma nın yapısı Mutaş gibi kurumsal ve kuvvetli değil. Firamnın önemli ama bir süre temkinli gidilmesinin faydalı oalcağını düşünüyorum . Proje 3 yıllık ve Sadece işi kısmi almışlar. Kümaş fabrika çerisindeki loder destekli taşıma işini başka bir firmaya vereceklerini öğrendim. O tarafın ihalesi henüz sonuçlanmamış.takip edeceğim. Ziyaret esnasında Atlı ekibide firmaya ziyarete geldiği gördüm. Atlı bölgede İş makinası Yeni ve yenileme konusunda yakın geçmiş de  bir hayli etkin olmaya gayret etmiş ve etmekte olduğu bilgisi ni edindim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('34928261-50af-54dc-9733-7a4bd9f33839','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZAN OTOMOTİV' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'3fed2db3-0f76-57b5-a171-12174836b523'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-04-29','İbrahim Sertepe','Eskişehir Brisa bayisi İş makinası yenileme işinde  geçmiş dönemde ticaret yaptığımız ve irtibatta olduğumuz firma  sahibinin yeğeni ibrahim Serteye İş makinası yenileme ile ilgili yeni gelişmeleri iletmek için uğradım . İbrahim dahil ekibin tamamı aldıkları talimat gereği binek ağırlıklı ticarete yönelmişler. Piyasaki rekabet ve Brisa ürünü dışında ticari marka  bulunmaması sebebi ile böyle bir karar aldıklarını ilettiler.  Görüşme esnasında lastik değişim dönemi olması sebebi ile  İbrahim beye Binek konusunda çok fazla telefon ve talep geldiği ni bende gözlemledim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('436a8f43-caff-59f8-b55d-03e11567bd37','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VARLAS LASTİK - DURAK ŞAHİN LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'16abc169-c620-5ea4-ab42-eaf08792cfb4'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-04-29',NULL,'Eskişehir Petlas bayisi Varlas lastik 3 yıl önce Tarım işlerine ek olarak çocuklarına iş kolu olması için lastik işine petlas bayiliği alarak girdiler.  Bende önceki dönemimde lastik ticarti yapmıştım. İstenilen ticari gelişmeleri sağlayamamaı sebebi ile Firmasını Eskişehirde sektörde olan Durak Şahin firmasına  devir ciddi zarar ile devir etmişler  . Sizinle en son konuştuğumuz Başka sektördeki kazanımlarını Lastik sektörüne taşıyan firmalar için yaptığınız yorum aynen bu gelişmede yaşanmış durumda  .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('97df38c2-8d0c-5ba6-acf8-07313245d083','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ECAN LOJİSİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'843e4c66-d576-5fee-a989-03f82a942067'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-04','EKREM CAN','ECAN Lojistik Eskişehirin Köklü Lojistik firmalarıdan .Geçmiş dönemde İş makiası taşınması konsunda çok kez iş birliği yapmıştık. 50 adet çekici 62 Dorse ye sahipler ağırlıklı olarak yurtdışı çalışıyorlar. Geçmiş dönemde Continental Bridgestone kullanımları mevcuttu. Fakat 2026 Şubat ayında  aldıkları dorse lastikleri ilk kez 20 adet  ling long marka olarak Bursadan almışlar.Yurtdışı yol sebebi ile lastik yenileme yaptırmadıklarını belirttiler. Maliyetlerin kendilerini mecut duruma yönelttiğini belirti. Midilli araçalarında  315/60 385/55 ebat kullandıklarını belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7a4e1227-a19c-5eeb-ac3c-3701f162afb5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CAN VİNÇLOJİSTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'093903bc-9a6b-55ca-a42e-a19f2dc0c927'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-04','İSKENDER CAN','Can Vinç sahibi İskender bey Kamyon Vinçlerinde 315/80 ağırlıklı olduğunu ve son dönemde Petlasın fiyat performansından memnun oldukları için tercih ettiklerini belirttiler. Şehir içi hizmetlerinde şantiyelerde çalıştıkları için çoğu lastiği hasarlı olarak atmak zorunda kaldıklarını belirttiler. Bu tür durumlarda Eskişerde çalıştıkları lastikçilerden yol yardım hizmeti aldıkları için az sayıda oluşan lastik ihtiyaçlarınıda yerel firmadan karşıladıklarını belirttiler. Aynı zamanda Nemli taşımacılık ile sık çalışıyor. Nemli taşımacılık bizim de takibimizde olduğu için İskender bey Nemlinin 20 adet Renault araç sipariş verildiğini ve yurtdışı lojistik işine girme aşamalarında  olduklarını belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4f74ae99-624c-5718-8888-ff1f016d178a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SELKA BETON' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'0b4896da-4676-5a66-9692-e43d0e5d02f2'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-04','SERDAR KAYA - ŞAMİL BALKIZ','Selka Beton Serdar bey uzun yıllardır lastik ölçüm , takip ve deneme yaptıklarını artık belli bir tecrübeye sahip oldukları için artık yapmadıklarını ilettiler. Son yaptıkları alımda prelli tercih ettiklerini belirterek adet ve fiyat konusunda bilgi vermek istemediler. Geçmiş dönemde Lassa Tercihleri mevcuttu.  60 adet mikser ve 12 adet pompa ile hizmet vermekteler. Kademe ziyaretimde İş makinası kademsinde eskiden tanığım Kademe yetkilisi Şamil bey Kütahya santiralinde iş makinası yenileme ihtiyacı olacağını kontrol edip beni bilgilendireceğini iletti. Kamyon yenileme konsundada ilk ihtiyaçda teklif vermek üzere işe dahil olacağız','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5eaef49d-ab06-5dcd-83dd-431145006d32','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÜPELİLER BETON' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'d54792c0-6f00-5174-9744-d9c52c5668b3'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-04','VEDAT YILDIRIM','Küpeliler Beton 30 adet mikser ve 10 adet pompa ile çalışmakta .Uzun süredir Petlas tercihleri mevcut . Kademe yetkilisi Vedat Yenileme konusunda ihtiyaç duyulması durumunda kullanılan desen marka  ve  kauçıklar konusunda bilgi verildi.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b294cde8-9268-595d-912b-b9b6d4faa43a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜMÜŞLÜ LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'6ea39814-252c-52bc-8623-64687bd3bff5'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-04','ÜMİT GÜMÜŞLÜ','Her gün en az bir lastikçi ziyereti planlamamda Gümüşlü lastik sahibi Ümit gümüşlünün  Ataser lastikleiş makinası sökme takma konusunda sıkı bir diyaloğu mevcuttu. Ataser lastik Serkan bey İşi 6 ay önce ortak olarak aldığı Naci beye işi devtettiğini eski potansiyellerinin kalmadığı nı Ataser lastikde müdür olarak çalışan Kenan beyin Recap ile İş makşnası kaplama işine girme girişiminde bulunduğunu fakat işin olmadığını belirtt. Ümit ile iş makşnası konusunda Bölgede bende geçmiş dönemde çalışmıştım. Piyasa ve İş makinası lastik biligisi ve oldukça iyi. Bölgede ihtiyaç durumunda çalışmaya devam edeceğiz','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('54a151d5-5ede-50c7-a2d4-b8d982a617fb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='RECAP MAKİNA' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'99efc010-068e-5e1a-8552-612a9e636522'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-04','METİN İLERİ','Recap ortaklarından Metin bey İş mamkşnası lastik yenileme talebi için bana ulaştı. Yapılan ziyarette İş makinası yenileme işine girmek için girişimde bulunduklarını fakat piyasa ve bazı aksaklıklardan dolayı girmekten vaz geçtiklerini ilettiler. Kendileri için yaptıkları otoklav ve İtalmatic tarzı kauçuk sarma ve diş açma makinesi yaptıklarını fakat vazgeçtikleri için makineleri satışa çıkardıklaını belirttiler. Bu süreçde görüştükleri firmadan 4 adet 23.5 R25 müşterilerini sıkıntıya sokmamk için lastikleri kaplatıp teslim edeceklerini ilettiler. 45 MM diş derinliği için 90 gün ödeme yenilem fiyat teklifini ilettim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cdeb0b6b-ca63-57c2-acd2-62c23ca0ff15','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ZAGUTOĞLU İNŞAAT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8c67c0f8-d04c-5bd4-97bc-bfe953bdae47'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-05','BURAK ATICI','Zagutoğlu inşaat ortaklarından Burak Atıcı ile İş makinası döneminden tanışıklık ve çalışmamız mevcur . Firmanın bünyesinde 315/80 ve 13R  hafriyat tipi kullanan Damperli 10 adet kamyon ve lastikli 4 adet  iş makinaları mevcut . Geçmiş Brisa döneminde firmaya kamyon grubunda Lassa ve iş makinası lastiği satışım olmuştu. Firma tüm lastiklerini Lassa olarak tedarik ediyor. Bugün ziyaretmde çalıştıkları ebtlar için teklif talep ettiler. Brisa Memduh beyden Zagutoğluna ait tüm ebatlar için %6 destek alındı . Stoklarımızda LASSA  13R22.5  600D  ve 295/80 ön ve çeker İnşaat hafriyat grubu lastiklerin bulunmadığı için Kumho ve stokda olan Sailun lastiklerden tamamlayarak teklifi ileteceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('74c8b7e5-4834-536e-8a09-c3d8f8f479c5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ARTMAR MERMER' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'e97dc382-6fe9-531b-90b6-ca36443bed87'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-05','AYDIN KAPLAN','Artmar mermer yetkilisi adın Bey Bursa ve Eskişehir seyitgazi ocakalrının açık olduğunu üretimlerinin ayrı kapasitede ilerlediğini belirtti. Mermer sektörü Çin pazarından kaybettiği potansiyeli Hindistan ile tamamlamaya gayret ediyor ama o konuda istenilen ticareti uzun zamandır gerçekleştiemiyorlar. Bursa ziyaretimde ocağa uğrayarak loderin lastiklerini inceleyip Aydın beye intiyaç durumunu raparlayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9ffa7877-ec0e-501c-a0f0-e36226a24eb9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SARP LOJİSTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'60ac06bf-b5e0-557c-85de-b86566b5b973'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-05',NULL,'Sarp lojistik firması Eskişehir en büyük filolarından . Eti nin yönetiminde . Firma ile yeni tanışacağımız için mail üzerinde randevu talebini iletmemizi istediler. Maile cevap bekliyorum .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8cbd4240-8bba-52aa-8de6-119658b64b9c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATG LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ce6c8f09-e0a2-594e-917e-042be990ed69'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-05','MEHMET GÜLLÜ','ATG Lastik Eskişehir Teksan sanayide TBR grubunda hizmet veriyor. Değişik bir pazarlama yönetimi var . İnstagram da mehmetgullu286 adıyla  280 bin takipçisi olduğunu belirtti. Bende teyit ettim . Ekişehir dışına daha çok hizmet verdiğini Afyon Kütahya bölgesinde çok müşterisi olduğu belirtiyor. Tüm ticaretinde alışlarınında peşin kart   satışlarınında  peşin olduğunu açık hesap ticaretinin hiç olmadığını belirtiyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9907c904-7092-5c52-87fe-7f7b0e5cf7fc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EYİGÜN ESKİŞEHİR CONTİNENTAL BAYİİ' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'a449e71b-c563-513b-9871-2e07defe4ebf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-05','HÜSEYİN EYİGÜN','EYİGÜN lastik Eskişehir Continental bayii. Ticari grupda Hubtrac ve Kumho ile ilgili 315/80 çalışma koşulları bilgileri verildi. Bazı ziyaretler de ihtiyacın üzerine tesadüf etmesi etkili oluyor. Bu hafta başı firma TBR yenile grubunda Eskişehir Ataser ile çalıştıklarını fakat firma sahibinin değişmesi ile ilişkilerin sıkıntıya girdiği bu konuda arayış içerisinde oldukları bilgisi aldım. Tbr yenile grubunda kullandığımız markalar hakında çalışma koşulları hakkında bilgi verdim. Yıllık ortlama 1000  adet civarında TBR  lastik yenileme potansiyeli olduğu bilgisini aldım','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('93128737-83a8-56c5-adc7-d244561c5a24','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNMERSAN MERMER' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'b53bb089-7e2b-5a58-ac12-468511df3aa5'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-05','KASIM NUMAN','Ünmersan Mermer Kasım bey İle geçmiş dönemde Bridgestone marka satışımız ve  loaderleri için yenileme hizmetlerimiz olmuştu. Bu yıl Sezon başında Eskişehir süpren ocaklarında bulunan loaderleri için 2 adet 29.5R25  wastlake marka lastik aldıklarını belirttiler. İş makinaları Lastik yeni ve yenileme ihtiyaçlarında irtibatta olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e31297c4-6668-5343-9b19-2453378dd979','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HOŞCAN LOJİSTİK-  MOVUS LOJİSTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ad37c9b5-00e7-5493-b271-c97e1a5e6925'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-05','MUSTAFA BEY','Eski adıyla Hoşcan Lojistik Movus lojistik olarak sektörde hizmet veriyorlar. Lojistik firmalarının çalışma şekilleri farklılık gösteriyor. Bunuda lojistik firma ziyaretleri sayesinde tecrübe etme şansım oluyor.  Movus lojistiğin çalıştığı tüm araçlar kiralık olduğu belirttiler. . Kendilerine ait 2 adet araç olduğunu bilgisini aldım .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2ec1fb06-dac2-5307-89fe-4b12ddd39da6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞİRİN NAKLİYAT' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'8136c305-0a8e-5cac-8f0b-a0839012b6bf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-06','MESUT KAYA','Şirin Nakliyat Kademe sorumlusu Mesut bey  95 yakın araçlarının Bulunduğunu Kümaşın tüm nakliye işlerini yaptıklarını genelde  315/70 - 315/80   385/65 kullanıyorlar . Lastik yenileme işini Dirpa ile çalıştıklarını . Şu an dirpadan ayrılan SE BA lastik Serkan ile çalıştıklarını belirttiler.Son alımlarını Konyadan  Matador marka olarak aldıklarını fakat genelde Goodyear kullandıklarını belirttiler. Krb marka ve çalışma koşulları hakkıdna bilgi verildi. Takip edilmesi gerek bir firma olduğu için sık ziyaret programına alacağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fc17a14c-a038-530d-90cf-81bdb0b752b9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLTEKİN NAKLİYAT' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'848bd7bc-284c-549d-9b66-9862adb03865'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-06','KADİR GÜLTEKİN','Kütahya OSB de bulunan Naklyeciler sitesinin tek büyük firması Gültekin Nakliyatın Sahibi Kadir Gültekin ile görüşüldü.Firma bünyesinde 2 çekici 8 kayon bulunduğu Latik markası olarak son iki yıldır. Hankook tercih ettiklerini ebatlarının 315/7022.5 ve 285/70R19.5 ağırlıklı olduğunu Kütahya da Fatih Oto lastik Kasım Çanak ile çalıştıkları bilgisi alındı.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9d743c18-7264-5319-8f96-7fc4d4c45d74','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HÜROK MERMER' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'8d4bf266-1b21-5e34-b23a-4760711fb154'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-06','NURULLAH AKSOY','Satın alma sorumlusu Nurullah Aksoy bölgede 2 ocakda yarı kapasite ile çalıştıklarını belirtti. Geçen yıl lastiklerini yenilediklerini bu sebeple bu yıl içinde İş makinası tarafında yeni ve yenileme ile ilgili i arıza yaşanmadığı sürece ihtiyaçlarının olmayacağı bilgisi alındı. Firma nın mermeri işlenmiş olarak Amerikada depoların da satabilmeleri sebebi ile 2 ocak çalıştırdıklarını. İç piyasaya bağlı kalmış olasalar  ocaklara ihtiyaç olmayacağını düşünüyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('54106bbb-bdda-5d93-886c-903fb1cb457f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PRİZMA LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'f8c1ac41-ab06-5654-9c53-b17b34f7013d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-06','MUSTAFA YÖNGÜL','Prizma Lastik  Kütahya da TBR ağırlıklı çalışıyor. Michelin bayisi fakat Son aylarda Continental satışının ağırlıkda olduğunu Kumho nunda belli bir adette satılabileceğini belirtti. Avantajlı olduğunu düşündüğümüz populer ebatların fiyatlarını paylaştım .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ee2f9dfd-16fd-5b7d-99cf-9cc6c099a9fd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SE-BA LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'618790e1-8a2b-5587-b15e-8d507ab26ddf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-06','SERKAN BAŞER','Serkan Başer Dirpa da  10 yıl çalışmış. 10 ay önce ayrılmış. Kütahya bölgesinde TBR kaplama org oldukça çevresi geniş. Bizim tanışmamız. Mutaş madenciliğin yerine gelen Ünaldı maden  Mehmet bey uzun yıllardır  Serkan ile çalıştığını Tüm lastik işlerini Serkanın org ettiğini belirtti.  Serkan Krb olarak bizleri tanıdığını Mutaşlada çalıştığımızı bildiği için Ünaldı madeninde İş Makinası yenileme işlerini bizimle çalışmak istediğini iletti. SE BA   lastiğe çalışma koşullarımızdan bahsettim . Ünaldı maden değil kendi üzerinden çalışma olacağı için vade ve ödeme hassasiyetimiz ve çalışma koşullarımız izah edildi.  Bu konu yu size telefondada izah etmiştim. Yapacağımız iç İstişare sonucunda dönüş yapacağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e0ccde95-9812-5f64-bfc8-a7281714f3bb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FATİH OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'7fedcc35-c33f-5763-8a22-20b9e67a0a60'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-06','KASIM ÇANAK','Fatih lastik Sahibi Kasım bey bölde TBR ağırlığı mevcut .Herhangi bir marka bayiliği yok. Bölede Conti ve Ling long  satış ağırlığının yoğun olduğunu Kumho ve Hubtrac içinde ihityaç durumunda fiyat talep edeceğini iletti.Ling long satış ekibinin yan tarada fotoğrafını paylaştığım görseli verdiklerini ve onun sayesinde müşterileri çok bilinmeyen markalara güvenle bakmalarını sağladıklarını . Satış yapmalarını kolaylaştırdığını belirtti.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9ed46378-8d8c-50df-89d8-53567be47104','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NEMLİ TAŞIMACILIK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'e1f69dcd-0cb1-579a-a85f-c4f672ac3491'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-06','ERDEM KÖYLÜ','Kütahya ziyaretim esnasında gelen bir habere istinaden dönüşde Nemli taşımacılığa uğradım.Bölge bayisi Özkan otomotivin Brisa ile Nemli taşımacılık için çalışma başlattığını 72 adet bedelsiz lastik  ile  sahada test yapılacağı bilgisini aldım. Lastik atölye sorumlusu deneme ne çıkarsa çıksın kullandıkları petlasdan fiyat yukarıda olacağı için çalışmanın sonuç vermeyeceğini görüşünü iletti Çalıştıkları sahada lastikler bitmeden taş sıkışması sonucu çok lastik attıklarını lastiğin şantiye sahasında  kullanım perfoması ölçmenin zaman kaybı olacağını düşünüyor.Kamyon yenilemede Bursa Doruklar ile Özka kauçuğu ile kendilerine yaptığı çok özel fiyattan çalıştıklarını bilgisini aldım. Bursa da şu anda Doruklar ve Dirpa arasında TBR yeniemede çok ciddi rekabet olduğu ve her iki firmanında TBR Özka ürününü 4.000 ler seviyesinde pazarlamak için ciddi bir rekabet halindeler. Nemli Taşımacılığın İş makinası yenileme tarafında benim takibin devam ediyor. Biraz süre alsada sonuç alabileceği olduğunu düşünüyorum .  Nemli yönetim kurulu üyesi Latif Barika İş makinası yenileme konusunu görüşmek üzere randevu verdi.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dc90bab3-6c18-5cc3-affd-e57ca2a0d23f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UÇAR LASTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ec9eb7ab-b448-50aa-a4ee-1b3698d1471d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-07','BİROL UÇAR','Bursa İnegöl Continental bayii Uçar lastik TBR- OTR ağırlıklı çalışyor. Geçmiş dönemde ticaretimiz mevcuttu . Tekrar çalılılabilecek markalar konusunda bilgi verildi. Aynı  zamanda bölgede  yine OTR yenileme ve tamir işleri mevcut. Bu dönemde bizden sonra ovakent ile çalışmaya başladıklaını iletti. Yapılan görüşme neticesinde tekrar bize OTR tamir ve yenileme işini yönlendirmesi konusunda ikna edildi. Araçlarımız bölgeden geçerken uğraması konusunda bilgi vereceğim. Güncel yenileme ve tamir fiyat listesi 20.5 -23.5 ve 26.5 ebatları için paylaşıldı.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4c828d67-3565-5f82-9d84-2c6d450a7c79','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇİFTYILDIZ MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'660e0aea-ea95-5378-a1c7-8c28f203f30b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-07','MUHAMMET ŞAHİN','Satın alma sorumlusu Muhammet bey Ocaklarından sadece Bursa Kemalpaşa Devecikonağı nın çalıştığını belirtti. Bu yıl sezona hazırlanırken 2 adet iş makinası yenileme yaptırdıklarını şu an için İş makinası gerubunda bir ihtiyaç olmadığını iletti. geçmişdede diğer Kamyon ve Ticari araçlar konusundada sürekli irtiatta olduğum Muhammet yeni iletişim bilgileri ve lassa brigestone org. bilgileri güncelledik.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ca02c0e1-d127-5bf0-9d15-9ca949d909ff','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EDK MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'2a1aa519-e299-5f6f-9452-876bd6b17597'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-07','OSMAN EREN','EDK mermer Osman bey Mermer her geçen seneyi aradıklarını bu yılda ilk 4 ayda 2025 aradıklaını belirtti. Ocakların çalıştığını bir miktar stok yaprıklarını ilk 6 aydaki potansiyele bakarak stoklar tamamlandığında üretimi durdurabileceklerini belirttiler. Mermer sektöründeki  sorun diğer sektörlere göre çok daha ciddi boyutlarda . Isparta Burdur Bölgesindeki ottaman denilen taşın kısmen müşterisi olduğu onun dışında diğer bölgelerden bu yıl çok ocak kapanacağını düşünüyorlar','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1ce096c1-b846-5476-b5a2-1fda1eafec22','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURSA BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'508014a9-495c-58a1-b288-ab581752d478'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-07','ÜSTÜN TAYAR','Bursa Beton ilişkiler biraz gevşek kalmış. Satın alma yöneticisi Üstün beye yeni org. ve ileşim bilgilerinin güzncellenmesi sağlandı. Tbr ve OTR yenileme konusunda tekrar tüm ihtiyaçlarda eskiden olduğu gibi ilişkileri sıkılaştıracağız. Brisa Memduh firmaının Birsa bayisine kayıt olduğunu belirtmesi üzerine Tbr OTR yenileme ve Otr yeni lastik . Tbr yenide çalışbileceğimiz markalar izah edildi. Bizden 2024 yılında aldıkalrı Continentlin çalışma performansında çok memnun kaldıklarını fakat şu an için fiyatların çok yüksek seyretmenizi devamlılıklarını etkilediğini ilettiler. Mayıs ayında Beton taleplerinde çok ciddi %50 ler oranınad daralmaya başlaması ile 107 araçtan 50 aracı tesislerde parka çektiklerini 190 beyaz yakandan %20 seviyesinde azaltılma yaşadıklarını ilettiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('472a2200-4a51-597c-b50c-3ae84445f055','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAFA İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8c43afaf-5ef4-58ce-b3f9-59126920505e'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-07','YILDIRAY KAYA','Yafa inşaat şu anda Eskişehir Bursa ve Kütahya Bursa yoolarında yol yenileme çalışması yapmakta. Geçmiş dönemden tanışıklığım olan Satın alma müdürü Yıldıray bey ile tekrar tüm yeni ve yenileme konularında çalışma ortamına hız katılması konusunda neler yapılabileceğini konuştuk. Tesadüf lastik teklif hazırlığında olduğunu iletti. Teklifi paylaştı.  Teklif düzenlenerek iletildi.315/80 - 13R - 245/70R17.5 - 235765R16C Ebatlarından oluşan teklifi Kumho -Sailun-Lassa- Bridgestone markalarından stok bulunurluğuna göre fiyatlandırdım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('54c88e80-c206-5da1-8125-ac5607efdb7a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KUZEY YILDIZI MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'fcbd9c45-35a4-569f-b633-e6b695067258'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-07','BİROL YÜCE','Kuzey Yıldızı mermer görüşemediğimiz dönemde Balıkesir Balya ocağını kapatııkalrını Bursa da buldukları siyah taş üzerinden ilerlediklerini fakat sadece iç piyasa çalışabildikleri için sıkıntıların büyük olduğunu durumun uzun sürmermesine tahammüllerinin azaldığını belirttiler. Memmer sektörü haricinde ne yapabileceklerini konuşmaya başlamışlar.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('550e5a1b-07df-5a15-aed2-309323ecc101','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PİŞKİNDEMİRLER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'890d3539-2c0c-5303-b53a-ae9028027d8b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-07','SERKAN PİŞKİNDEMİR','Serkan beylerin Taş ocakları mevcut bölgede asfalt çimento üretmi yapan firmalara agrega desteği veriyorlar. Geçmi dönemde TBR kaplama be yeni lastik satışımız olmuştu. Beni geçen alımda aradıklarını fakat numarama ulaşamadıklarını ilettiler. Yeni şirket hattım ve Brisa süreçleri konusunda bilgier verdim. İş potansiyeli olan firma olma durumlarında dolayı yakın takipte olunması gerekn bir firmadır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('efe9548d-825b-53fc-9094-565c96ac9a90','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇINARLAR MADEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'d047587d-44c2-505d-8dd7-6c2914ed0a74'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-08','MEHMET ÇINAR','Bölgede Seramik fabrikalarına ham madde üretimi yapan Çınarlar maden bu yıl sermik fabrikalarında ürtimin azalmasıdnan dolayı doğru oratılı olarak kendilerine yansıdığını belitti. Bölgede bir tek Kütahya Seramik grubunun seramik sektöründe işinin iyi olduğunu kendisininde o firma ile çalışmadığını belirtti. Hammadde sektörüde yeterli karlılığın kalmaması sebebi ile inşaat sektörünede girdiklerini ağırlığı oraya vereceklerni belirttiler. Firma bünyesinde 3 adet loder ve 8 adet damperli kaya kamyonu mevcut.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('89bd0076-de5a-581a-a552-9046b8780f18','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PAKSOY BETON' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'250ae453-509c-5ce0-a5e5-602cc98c75f6'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-08','NECDET GÜVEN','Paksoy beton Eskişehir ilginç bir şekilde geçen yıl betonsektöüne giriş yaptılar. Eskişehir de Selka Küpelilier ,Çimsa ,Atıcı Bilgin gibi beton firmaları varken böyle bir dönemde beton sektörüne girişleri enteresan bulndu. Lastik ihtiyaçlarında tek marka Petlas ile çalıştıkalrını belirttiler.Lassa nında gündemlerinde olduğunu belgisi alındı.   Dünkü ziyaretimde Bursa beton kapasitesinde firmanın ekipmanlaını yarısını parka çektiği dönemde sektöre yeni giriş yapılması ilgi çekmekte takip edeceğim  Frma sahibi Semih Paksoy toplantı oldukları için bu gün görüşemeceğimiz bilgisi alınca . Tekrar uğramak üzere notlar arasına alındı','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('427e540b-d5e0-5e73-b117-454b0f0dcdf4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜBRETAŞ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'7cc89b1c-d37b-5a60-9bed-ec79bc2170c7'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-08','AYHAN UYANIK','Söğüt altın madeni Satın alma sorumlusu Ayhan Uyanık ile firma nizamiyesinden telefon ile görüştüm . Randevu ve tanıtım için mail adresi ilettiler. Mail gönderilerek verilecek randevu bekliyorum','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a39e82b8-6f69-5fda-a252-fb6b73057180','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TERMAL SERAMİK' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'a0ad7013-6371-57ff-8403-0a3089724a33'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-08','HAZEL ASLANOĞLU','Termal seramik fabrikasında 2 adet loder ve 15 adet forklift mevcut . Tüm iş makine grupları için verilecek ürün ve hizmetlerimiz konusunda bilgi verildi. termalden sonra ziyaret ettiğim Çınarlar Maden Mehmet bey den alına bilgide belli bir süre ödeme problemi yaşadığı firmaya ham madde satışını durdurduğu bilgisini aldım . Mehmet Çınar beyin ticaret yapış şekilini bildiğim için görüşmeye istinaden Termalden gelecek teklif veya talepler için ödeme koşullarında netleşme olmadan mal veya hizmet yönlendirmesi yapılmayacak .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('30dda872-a6ac-5809-8c90-0defd7fe1b96','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAPI YAPI' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'e5fbd3af-ffab-5b46-b0b6-bc7022254836'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-08',NULL,'Yapı Yapı firması Döğüt gübretaş madenciliğin taşerönlüğünü yapmakta. Geçmiş dönemde Yapı Yapı ya Yılmazlar lastik aracılığı ie yenilem hizmetini organize etmiştim. Güncel durumda firmanın lastik işlerini organize eden kişinin bu gün izinli olduğu bilgisini aldım . Güncel çalışma koşulları öğrenilerek neler yapıalieceğini takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c8c6d0bd-746d-5487-81ce-dbf611962517','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATIŞKAN ALÇI' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8f80781e-8afe-5b08-93fc-327732dd6975'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-11','ADEM KAYA','Atışkan alçı bünyesinde 3 adet Volvo loder mevcut. Eski müşterimden olan firma Mart ayında  Tatkoya 2 adet yenileme yaptırılmış . 2 adet Micelin 23.5R25 lastik alımı olmuş. 3 adet loder içinde bu yıl ihtiyaçlarının karşılandığını arıza olmadığı sürece sezonu bu şekilde kapatacakalrını belirttiler. İlişkimin çok  iyi olduğu firmada yapılan alım  bize nasip değilmiş. Garanti satışım olabilecek bir işlem olması dolayısı yaptıkları alım  ile beni üzsede en azından sonraki ihtiyaçlar için devreye girmiş olduk.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b3f8b4be-ebff-5b4a-a1c0-873328e305f9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞAHİN MİNERAL' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'80465797-28cb-54f4-a9c5-c44fe33329bf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-11','BURAK ŞAHİN','Seramik gabrikalarına hammadde sağlayan Şahin mineral bünyesinde 3 adetlastikli loder 10 adet kamyonları emvcut .315 /80  385/65 ebatları ağırlıkta . Son alımlarını Petlasdan yapılmış. Daha önce çalışma oratamı olmamıştı. Bu gün yapılan ziyarette ürün ve hizmetlerimiz sunumu sonrasında pozitif ilişki yakalandı. İlişkinin ilerlemesi sık ziyaret ve şantiyelerinde yapacağımız saha çalışması ile dahada yukarı taşınacaktır. Ziyaretler sıklaştırılacak.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('48234171-cab2-5174-8afc-df64ab4d63b5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KOZA ALTIN' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'c4026be0-b0e6-5d3b-a704-d5f173696a77'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-11','EVREN ŞENTORUN','Koza altın Kaymaz işletmesi satın alma sorumlusu Evren Şentorun ile geçmiş dönemde kaymaz işletme için yenileme ve 29.5 l5 satşlarım olmuştu. Evren bey lastik grubu  Satın alma işlerinin merkeze geçtiği tüm grup için Ankara merkezden yönetildiği bilgisin aldım. Ankara irtibat bilgileri alındı. Randevu için mail ile Krb tanıtım ve randevu talep mailimiz iletildiç Takip edecğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('14b77444-c4cb-593d-8d05-4636416c78e7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DEMİRDAĞ LASTİK' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'20a8e2b9-b288-511e-a600-e4471bf7e5c6'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-11','HİCABİ DEMİRDAĞ','Fatih beyin  bu gün grupdan paylaştığı Hubtrac kampanya fiyatlarının bu grupta çok müşterisi olan Demirdağ lastiğin ilgisini çekeceğini düşündüm. Paylaşılan kampanya bilgileri sonrasında Demirdağ lastilde  Balıkesir Bölgesindeki müşterilerine  ulaştı ve toplamda 68 adet  Hubtrac  315/70 çeker lastik siparişi girildi.Lasikler sevk edildiğinde aynı araçla  2 adet 23.5 R25 iş makinası lastiğide yenileme üretime alınacak .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('290fbc6c-1d89-591b-82b5-c2c9b2e15e0f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e6c4c63a-1a2c-5a2e-9e1e-6399d789e3a0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-11','SE-BA LASTİK SERKAN BAŞER','Kümaşın yeni taşerönü Ünaldı maden iş makinaları yenileme işini aracı SE-BA  lastik ile birlikte yönetmeye başlıyoruz. İlk etapta bekleyen 4 adet 26.5 yenilemeye alınacak arada bulunan SE-BA  lastik ile sürecin işyeyişinin KRB çalışma şartları içerisinde kaldığı sürece devam edilecek. Şartlar dışına çıkılması durumunda direk Ünaldı maden ile ileşim durumu devreye alınacak .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b4736fb8-2937-50ba-bf76-52b056af8606','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İKİESENLER İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'6a5f4752-6044-59c0-9a44-8777bd6e921a'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-12','CEMİL ESEN','ikiesenler firmas AKP döneminde  Bursa Büyükşehir belediyesinin işlerini yoğun bir şekilde yapmaktaydı. 2 yıl kadar ara verilmişti sadece Orman işletmeyele bu dönemi geçirmişti. Şimdi tekrar Belediyenin el değiştirmesi ile 3 ay sonra ihale yapılacağ ve işi tekrar alacağını düşünüyor. Firmada iş makina sayısı 60 adet civarında . Yaptıkalrı iş icabı kamyona ihtiyaçları çok. yok. Kışın karla mücadele ve Orman yollarının açma ağırlı işleri var. Acil ihtiyacı olan 10 adet 17.5R25Ahmet Zengin tarafından tedaik edildi ve firmaya sevk edildi. 4 adet 17.5R25 greyder lastiği  için şantiyelerine gittim. Latiklerin yenileme ihtiyacı tespit edildi. Yenileme fiyatını Firma sahibi Cemil beye ilettim. Şantiyelerinde lastik sökümünü kendileri yapacaklar hazır olduğunda bilgi verecekler. Bölgeye giden araçla yenilemeye alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('254d3956-fef4-5393-915e-07c2b5d8ddcd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YÜNER İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'87cf31d1-0017-55d1-a9ac-bae06420d442'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-12','ERDEM AYAZ','Yüner inşaat Bursa bölgesinde Buskinin önemli taşerönlerinden . 315/80 ve 13R İnşaat hafriyat grubu ağırlığı ile çalışıyorlar . 35 adet kamyona ve 7 adet lastik li işmakinasına sahipler. Lassa kullanıcısı olduklarını biliyordum. Fakat ihtiyaçları olup dönüş yaptıkalarında tüm markalar için alternatifli olarak teklif verilmesini talep ettiler.  Artık farklı markalarıda gündeme aldıklarını ilettiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('52b95dfa-abd3-5f14-9f5d-b6a5bcde65c2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKSOYLAR MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'6743c5e7-2070-54cc-ba7e-94ab09a06a7c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-12','İBRAHİM BABEKLİ','Aksoylar mermer Şantiye sorumlusu İbrahim bey İşlerin sakin olduğunu fakat ocakda temizlik ve fabrikaları besleyecek kadar blok ürtimi yaptıklarını belirtti.Haziran ayında 2 adet 29.5R25 ihtiyacı olacağını patronlarını alıma ikna etme aşamasıdna olduklarını ilettier. Bridgestone tercih ediyorlar. Geçmiş dönemde Maxam ı sadece kaya kamyonlarına almışlardı. Takip edeceğim','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0985c790-3b96-5f46-970b-538913769f9c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAŞÇI OTOMOTİV LASTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'9a5df329-57cd-540e-be38-91996b33b61f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-12','ATİLLA TAŞÇI','Bursa da TBR ağarlıklı lastik satışı mevcut. B2B açıldı.Atilla Taşçı  Bölgede TBR pazarında tecrübe sahibi . Müşteri portföyü geniş. Toptan olarak çalışılabilecek ürün ve hizmetler konusunda bilgileri aktardım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8f807f3a-b574-5b2c-a922-5178e044132b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİMGE MAD MADENCİLİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8a63aad1-a72e-566c-996f-01a0966d0a94'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-12','SATIN ALMA ÇETİN BEY','Simge mad başköydeki şantiyelerinde geçmiş dönemden iyi diyaloğum olan kademe sorumlusu Hasan bey ile güncel gelişmeleri ve marka ve hizmetlerimizn eskisi gibi devrede olacağı nı belirttim. Yunuseli merkezde bulunan Satın almalarını arayarak beni yönlendirdi. Firma merkezinde Satın alma Yetkilisi Çetin bey  tekrar geçmiş dönemde olduğu gibi yeni ve yenileme konusunda teklifleri bizlerlede paylaşacaklar.Simge geçtiğimiz yıl taşocağı işletmeciliğinde kullandığı İş makinası ve kamyonların bir kısmını sattıklarını . Piyasadaki daralma ve rekabetten dolayı  Asfalt üreten makina imalatına yöneldiklerini ilettiler. Satın alma yetklisi Çetin bey şu an alıma çıktıkları 8 adet kamyon lastiği talebini ilettiler. Teklif stokalrımızda bulunan markalardan alternatifli olarak cevaplandı. Simge ile ilişkiler kısa zamanda potansilli olarak artacağına inannıyorum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f43b2aa1-448c-5d70-b659-bba5b9921230','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OSMAN DEMİR  İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'e95cd808-6226-5078-9176-bd16e3aba96c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-12','UĞUR DEMİR','Osman Demir İnşaat Simge mad  firmasının Ocak taşerönlüğünü yapıyor. Simge mat firmasının referansı ve telefonla görüşmesi sonucu firma ile görüştüm. Simge mad firması ile ilişkileri iyi olduğu için alımlarda alternatif olarak dikkate alınmayı sağlayacakları ön bilgisi alınarak Yaklaşık 80 adet kamyonları mevcut . En son alımlarını Lassa dan yaptıklarını ve bölge bayisine  bağlı olduklarını ilettiler. Brisa grubu haricinde ürün  ve hizmetlerimiz konuzunda bilgiler paylaşıldı.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('07e4a625-880c-512e-9108-bbba19c73f27','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VOLKANLAR VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ff403d93-60a9-56cd-bc2c-098827a0d7d7'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-12','MURAT TURAL','Volkanlar Vinç Satın alma yöneticisi Murat Tural a ürün ve hizmetlerimiz konsununda bilgier verdim Geçmiş dönemdede ziyaretlerimiz olmuştu fakat çok yol kat edememiştik. Firmanın sahip olduğu ekipmanlar açısından daha yakın durarak ısrarcı tavrın ben sonuç vereceğine inanıyorum. Bursa ziyaretlerimde sık uğrayacağım firmala arasına kayıt ettim.Bir kaç ziyaret ten sonra farklı bir ilişki oluşacağına inanıyorum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b0d4cd63-395a-5bca-800c-41ae4f9b3d9e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NEMLİ TAŞIMACILIK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'e1f69dcd-0cb1-579a-a85f-c4f672ac3491'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-13','LATİF BARİKA','Nemli Taşımacılık  uzun süredir takip ettiğim geçmiş dönemde de bir çok kez görüşme yapılmış ve küçük işler alınabilmişti.Latif bey ile geçen hafta randevulaşmıştık. Şantiyeye sabah kahvaltıya davet etti. Sahanın gezilmesi lastik depoları ve Petlas dan yaptıkları alım süreçleri konusunda bilgi verdi. Şu an Bridgestone marka talep ettikleri 315/70 ve 385/65 ebatlarının yeni kurdukları nakliye filosu için alım planladıklarını belirtti. 17 adet Renault ve Scania dan araç alımları oldu. Bu araçlar için Bridgestone kullanacakları nı belirttiler. Mehmuh beyden firmanın vergi numarası kontrolü ve iskonto talebi sonrası verdiğiniz %37 isk iletildi. Bölge Brisa bayisi bizden lastik başı 350 daha yüksek vermiş . Kocaeliden yapacağımız nakliye maliyetinide  hesaplayan Latif bey Bölge bayi den işi daha çok istediğimizn kanıtı olarak değerlendirdi. Kooperatif olması durumu itibariyle teklifimiz için yönetim kurulu onayı alacak .Teklif sonucu nu bekliyorum . Aynı zamanda 2 ayrı Lastik tekerlekli lodere  Onların bandag bizim Cut cure tabirimiz ile Cut cure  ve rekor olarak yenileme yapılmasını ve  sahalarında çalışma performansını ölçerek hangi marka nın saha özellerinde fiyat perfomans olarak firmaları lehine olacağını tespit edecekler. Geçen hafta Cut cure olarakfarkı bir firmadan  fiyat aldıklarını belirtti. Bizim 51.000 t + kdv rakamımız için 50.000TL + kdv fiyat aldığı iletti. Aynı fiyata yapılası konusunda görüşme esnasında inisiyatif alarak bizimde aynı fiyatı uygulayaileceğimizi ilettim. İletilen bilgi ve teklifleri sıkı bir şekilde takip ediyorum . İnşallah olumlu sonuçları sizinle paylaşacağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2ae9bd8a-93cc-53dc-8c03-0f281d2ecffd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SELKA BETON' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'0b4896da-4676-5a66-9692-e43d0e5d02f2'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-13','SERDAR KAYA','Selka betonda ilk ziyaretim sonrasında uğramamı talep etti. Firmanın Son aldığı mikserler üzerinde orj ekipman Pirelli gelmiş ve son alımlarınıda Prelliden yaptıklarını konuşmuştuk. Bizim Brisa gruba fiyatlarımız dışında Hubtrac ve Kumho fiyat ve stok bulunabilirliği konusunda bilgiler talep ettiler. Bu hafta yaptıkları iç toplantıda etraflarında alternatif lastik kullanımını araştırmışlar. Ling Long  ön plana çıkmış . Bizim ürünümüz Hubrac hakkında bilgiler verildi. Selka gibi firmanın alt kalite lastik araştırmasına girmeleride oldukça dikkatimi çekti.Firmanın Eskişehirde Beton dışında başka işkerinin olması ve güncel işlerinin hzılı olması durumunda bile yönelmek istedikleri marka ilgimi çekti. Amaç piyasa kullanımında artan markaların performansını anlamak mı  ?  Yoksa yoğun görünen  iş potansiyellernin altında azalan karlılık mı ? Onu zaman içerisinde netleştireceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9e12df06-023c-5ae4-93b7-930f8b88eff3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KOLİN İNŞAAT' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'3cf50f6b-6e91-5259-bfb8-e4bb370d98b3'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-13','HÜSEYİN CEM DURMAZ','Kolin inşaat Bozüyükde 2 yıl sürecek TCDD lojistik merkezi inşaatına başladı. 7 adet Damperli kamyon ve 6 adet lastikli loaderleri mevcut. Diğer ihtiyaç olacak kamyonların taşerön olarak geleceğini belirttiler. Lastik ihtiyaçlarının büyük kısmını bildiğimiz gibi Kolpaş üzerinden karşılıyorlar. Büyük bir proje olması sebebi ile gelecek taşerönler geldiğinde projeye ziyaretler sıklaştırılacaktır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('efc58a2f-6709-5816-94a2-47cc78e7a474','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TÜRE VİNÇ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'3b80f7c1-adc5-5c3f-a7eb-7348bfdaaac9'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-13','VEYSEL TÜRE','Türe vinç sahibi veysel bey ilk ziyaretim sonrasında 315/80 Ling long talebi ile dönüş yaptı. Hubtrac olarak Sırbistan üretim süreçleri ve markaların farklarının olmadığı konusunda bilgileri aktardım. 6 adet için fiyatımız iletildi. Ling long ile kıyaslamada Hubtrac 15.000 TL ye aynı şartlarda olursa deneyecekleri bilgisi alındı. Sizden aldığım son fiyat iletildi.Veysel  Yarın dönüş yaparak sonuçlandıracağını iletti.  . Ziyaretler sonuçlarını vermeye başladı. İnşallah suya  atılan taşın  dalgası gibi hergün büyüyerek devam edecek. Böyle bir dönemde tahsilataına kadar sorunsuz ticaret  süreci yürütebilecek müşterin bulunması için çok fazla ziyaret gerekecek. Bu ziyaretler mevcut bölge müşteri istihbaraıtının sağlıklı ve güncel olmasını da sağlamaktadır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6663448d-d9bf-5144-804c-cecd93c7ec5e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UÇAR LASTİK' AND il IS NOT DISTINCT FROM 'İNEGÖL' LIMIT 1),'59561f39-2f70-58af-8e6d-e49c1a7710bb'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-13','ABDULLAH UÇAR','Geçen hafta Uçar lastiğe yapmış olduğum ziyaret sonucunda 2 adet 23.5 lastiğin amir ve kaplamaya alınması için geri dönüş yaptılar. Geçmiş dönemdede İş makinası yenileme işlermiz olmuştu. Bölgeye aracımız geldiğinde lastiklerin alınmasını sağlayacağım.Nemliden çıkacak 4 adet 26.5R25 lastiklerin alınma süresinde gecikme olmaz ise işleri  birleştirmeyi planlıyorum','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e5830a0f-8818-5db4-8395-76c2b42cf104','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATG LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ce6c8f09-e0a2-594e-917e-042be990ed69'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-13',NULL,'ATG lasti le yeni tanışılmış ve B2B portalı kurulmuştu. Portaldan tespit ettiği LTC-1127 kodlu Sailun 315/70R22.5 ebat için dönüş yaptı. Lastiklerin tamamına talip olmak istediğini fakat B2B de lastiğin Üretimin yılını göremediği iletti. Depoda alınan 2024 38 . hafta bilgisi iletildi.  Dot biraz eski olduğu için düşüneceğini iletti.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6862b492-3c7e-5f60-887f-a47e625afb66','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MATEL HAMMADDE' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'30406f87-5cd1-59cc-ab62-16899aac4813'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-14','GÖKHAN ENGİN','Matel in Bileck tesisinde 5 adet L120 volvo loder mevcut . Geçmiş dönemde firmaya yeni lastik ve yenileme hizmetimiz olmuştu. Son dönemde Tatko ile çalıştıklarını ilettiler. Satın alma müdürü Gökhan bey ilede geçmiş dönemden iyi bir ilişkimiz mevcut. Oluşacak  İş makinası yeni ve yenileme ihtiyaçlarında geçmiş dönemde olduğu gibi bizlerden teklif alacaklar. Matel A.ş. yi geri kazanmak Bilecik bölgesi için oldukça önemli . Sıkı takip edeceğim','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1c5c84ff-fbb3-5fdf-b1dc-fc8638200be6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKRO MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'7b24dfd7-a44c-50bd-a81e-4ee4f772035a'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-14','SADULLAH ÜNAL','Bilecik Pazaryeri bölgesinde iyi potansiyelde çalışan tek ocak . Taşın özelliği ve kullanıldığı proje devamlılığı işlerini Stabil tutuyor. Ocak 3 Adet 29.5R25 Lastik kullanan Volvo loderler mevcut . Sıkıntılı olan 2 adet 29.5  lastiği sezon başında Ankaradan Bridgestone marka olarak aldıkalrını Sezon sonuna kadar Arıza olmadığı sürece lastik yeni veya yenilemeye ihtiyaçlarının olmayacağını ilettir. Firmanın 2024 yılına aldığı en son Brisgestone lastikleri Krb olarak biz vermiştik . Ama ihtiyaç olduğunda artık bizde devrede olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5a331f62-d7df-550d-833c-e21acdd441da','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FEDERAL MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5aef9238-6308-5cb6-9856-94a5aacf7cc9'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-14','SELÇUK ÇOKAL','Federal Mermerin Yeni pazarda bulunan Ocağı çalışıyor.Geçen yıl 2025  sonunda 4 adet BKT 29.5 lastik almışlar . İşleri azalsada 2 ocakda toplam 3 makine üzerindeki 12 adet lastik her gün belli bir saatte dönüyor. Yan ocakları Makro mermer kadar ileri iyi olmasda bu yıl ocakları açık tutarak üretime devam edeceklerini belirttiler. Yıl içerisinde lastikle ilgili ihtiyaçları olması durumunda eski dönemde olduğu gibi bizler den de teklif alacaklar. Son yaptırdıkları yenilemeyi 2024 yılında Krb olarak yapmıştık','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('86b95a86-6429-5bb6-a2f7-5ce1d7e943a1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DURAK ŞAHİN LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'29d14c18-98b4-5a6e-ac3e-c6d4274834d8'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-18','VOLKAN AY','Durak Şahin lastik Ekişehirde TBR ağrlıklı çalışıyor . Bu yıl Binek grubunada başladılar. İhtiyaçlarının büyük bir bölümünü Günmarlasdan karşılıyor. Fakat Bu yıl TBR de grubunda  Günmarlas ile aralarında oluşan anlaşmazlıkdan dolayı Lassa satmama kararı vermiş. Tüm markalar ile çalıştıklarını Continental müştrilerininde oldukça arttığını ve bu konuda Eskişehir ATS lastiğe bizim tarfımızdan satıldığını bildiğini iletti. Continental ve Kumho ihtiyaçlarında irtibatta olacağız. Alt marka da müşterilerini leao ya alıştırdıklarını. Bu grup lastikte kim müşterisini hangi marka Sırbistan üretimine alıştırırsa o markadan devam etme eğilimindeler. Hubtrac- Ling-long Leoao gibi alt segmen üretimin aynı ortamda yapıldığı izahati yapılasada   şu dönem değişiklik için yerel satıcılar  fazla çaba sarf etmek istemiyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('38f5fc71-6322-5314-a550-fb7066ec79e3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAKARYA MADENCİLİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'e6fd1b1b-6d9a-5ce8-b70d-32a7422288ce'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-18','MUSTAFA ÇİRKİN','Sakarya madencilik Eskişehir OSB de ev kedileri için kullanılan kedi kumu üretimi yapıyor. Alpu bölgsinde çıkan sıvı emici bir madeni fabrikada torbalayarak tüm dünyaya satış yapıyorlar. Firmanın Maden ocağında 2 adet  L120 Volvo loder mevut . 23.25 kullanıyorlar Mustafa beye daha önce hizmetlerimiz olmuştu. Yetkliye ürün ve hizmetlerimiz konusun da bilgileri verdim. iribatta olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3984ec70-1ded-58da-8423-095c631e3ab5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATASER LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'71f6d84c-80d8-5f29-a807-9c26b5490815'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-18','NACİ ÇELİK','Ataser lastik Naci bey Serkan bey ile ortaklığını bu yıl bitirmiş. Tesisinde TBR yeileme  yapmakda. OTR yenileme talebi geldiğinde AKO ile çalıştığını TBR kauçuğun bir bölümünüde AKO dan temin ettiğini iletti. Aynı zaman da TBR yenilemede Özka ürünüde  kullanmaklar. Bu yıl ortaklarının bitmesi ile TBR ve OTR yeni satışınada başlamak için hazırlık içindeler. Geçmiş dönemde aldıkları taleplere cevap vermek için düşük miktada yaptıkları yeni lastik işini büyütmek için bu yıl çalışacakları bilgisi alındı. Bölgede bizim müşterimizde  Acil ihtiyaç olacak OTR tamir için destek olabileceklerini belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('63f3d7cd-ce3a-555f-8e90-dff86eab15ff','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BEHEM İŞ MAKİNALARI' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'73093767-f126-554e-ab46-9100903d6c9e'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-18','OSMAN ÜNSAL','Eskişehir de genelde Bekoloder iş makinalarına tamir hizmeti veren Behem in müşterilerine geçmiş dönemde ORS satışlarımız olmuştu. Güncel durumumuz ve ORS stoklarımız konusunda bilgileri ilettim. Tiron ve Lassa ağırlık stoklarımızdan Lassa nın tüm ebatları için iletişimde olacağız. Eski dönemde olduğu gibi ORS satışlarımızıda ağırlık vereceğim . Behem firmasının müşteri yelpazesinden daha fazla yararlanmak için  ziyaret sıklığını arttıracağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('58beb862-5305-5478-b1a1-4c9e8a341a83','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ZAGUTOĞLU İNŞAAT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8c67c0f8-d04c-5bd4-97bc-bfe953bdae47'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-18','BURAK ATICI','Zagutoğlu inşaat Eskişehirde 6 adet kamyonların 13R22.5 600D  -315/80R22.5  EG7500- 520S  Lassa teklifi vermiştim. Artan fiyatlardan dolayı teklifler beklettiklerini bayram dan sonra değerlendireceklerini ilettiler. Bayram dan sonra Brisa grubuna gelecek zam bilgisinide ilettim. Müşterilerin erteleme isteklerinin  son ziyaretlerimde artışla olduğunu gözlemliyorum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1a943850-7cdc-5209-b073-faf85dc99983','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYDINTAŞ VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a8e68155-73d4-589b-881b-1cd8e6b845fd'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-21','DAVUT YILDIZ','Aydıntaş vinç daha çok Kafes boru paletli vinç konusunda Türkiyede söz sahibiler. Tabi bu grup makine paletli olduğu için lastik tedariçi olarak bizim hedefimiz dışında kalıyor. Firma bünyesinede 16.00R 25 lastik kullanımı olan vinçler de mevcut .  Stokalarımzıda bulunan Maxam vinç lastiklerimiz hakkında bilfileri ilettim. Satınalmaya yeni geçen Davut bey Görevi Fatih İslam dan devir almış. Fatih bey ile çok fazla çalışma ortamı yaratamamıştık. Davut bey daha ilgidar diyalağu mevcut. Ziyaret sıklığının arttırılması nın sonuç verme ihtimal, yükseldiği için Bursa rutlarında muhakkak uğrayacağım. .Tüm Üürn ve Hizmetlerimiz konusunu detaylandırdık.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4df8b426-2424-55e3-8060-8378b4d415b2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZÜAYDIN VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ec510dd9-4a27-598b-8697-b6e516288f90'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-21','FEVZİ KILIÇ','Özü aydın vinç in odak noktası Liman hizmetleri. Firmaların hepsinin adı Vinç olasada bu sektörde de çalışma çeşitliliği mevcut. Özü aydın gibi Yurtdışında  gelen konteyner veya yük hizmeti veren makinalara sahip olan firmaların işleri kabul edilebilir düzede olmasına karşın . Bağlar Vinç gibi kamyon üzeri düşük tonajlı tamamen küçük sanayi sektörüne hizmet veren frimalar karlılık ve iş potansiyeli sıkıntısı yaşıyıorlar. Fevzi beye stokalarımzıda bulunan 16.00R25 Maxam vinç lastiklerimiz hakkında bilgileri ilettim ve belirtilen lastiği kullanan araçları bulunmadığı bilgisi aldım. Tüm lastik ihtiyaçlarında iletişimde olma talebimizi ilettim. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ef326c1c-865c-524d-9212-e0db1181bae1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VOLKANLAR VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ff403d93-60a9-56cd-bc2c-098827a0d7d7'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-21','MURAT TURAL','Volkanlar Vinç de makine çeşitliliği bir hayli fazla Bursa Bölgesinde Vinç firmaları içersinde Çeşitliliğe en fazla sahip firma diyebiliriz. Bu çeşitlilikde doğal olarak lastik tedariklerinede yansıyor. Murat beye Yeni Yenileme tüm ürün ve hizmetlerimiz konusunda bilgileri aktardım. Stokalarımzıda bulunan Maxam 16.00R25  vinç lastiklerimiz hakkında bilgileri ilettim.  Geçmiş dönemde iş makinası taşınması amaçlı bende firma ile irtibattaydım. Fakat benim tanışıklığım olan yöneticileri ayrılmış. Bu sebeple yeniden ilşkiyi olgunlaştırma aşamasındayım . Ziyaret sıklığınıj arttırılması iel sonuç alacağıma inanıyorum .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5956affa-5a97-55c9-8948-c6c763689961','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAĞLAR VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a65589b0-d784-5d53-bd80-c1b396e40622'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-21','YILMAZ BAĞLAR','Bursa Yılmaz Bağlar İnşaat Hafriyat işinden çıkarak Vinç işine geçiş yaptılar. Benimde geçmiş dönmede Hafriyat sektöründe firmaya ticatim olmuştu.  Her sektörde olduğu gibi Vinç sektöründede karlılıkların düşmesi rekabetin artmasıından dolayı sıkıntı yaşadıkalarını belirtti.Vinçler kullandıkları kamyonlarda 315/80 ağırlıklı lastik kullanıyorlar. Ürün çeşitlerimiz ve Hizmetlerimiz konusunda bilgileri ilettim. İlk ihtiyaçlarından bizden de teklif alacaklarından eminim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6d101e0d-1ba3-5aa1-9208-d2408c47a406','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','61142a4f-0b15-47e0-a6af-575d0bf7aea3'::uuid,'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-21','KURTULUŞ YİĞİT','Dirpa lastik Bursa da kamyon lastiği yenileme ve kısmi yeni lastik satışı yapmakta.  Sahibi Kurtuluş bey ortağından ayrılmış. 47 kişilik ekibi 14 kişiye düşürmüşler. Özka kauçuğu ile TBR yenilemede  4.000 + kdv peşin ve ön  ödemeli kampanya başlatmışlar. İş makinasını AKO ya  Kripto kauçuğu ile yenileme yaptırıyorlar. 23.5R25 45 mm kaplamayı AKO ya 37.000 tl ye yaptırdıkları nı belirtiler. İş makinası yenilemede Ürün/ fiyat yapımız onların müşteri portföyüne uzak.  Kumho -Hubtrac  İnşaat Hafriyat tipi fiyatlarımız paylaşıldı. Talep oluştuğunda irtibatta olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7d715664-9bf6-5bdc-8db4-5e1c441fbd7f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YEŞİL BURSA VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'53fc091d-a01f-59ce-ab72-b3ed9223f27b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-05-21',NULL,'Yeşil Bura vinç firması Bursa merkezde Aydıntaş vincin boşattığı alanı kiralamış. Yeni kurulan firma makine parkları henüz başlangıç seviesinde Firma yetklisi ile görüşme şansım olmadı . Sonraki Bursa ziyaretimde ziyareti tekrarlayacağım. Bu arada firma hakkında bilgide edieceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('10681eac-eb55-590f-83cc-6247e4357ff5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HÜROK MERMER' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'8d4bf266-1b21-5e34-b23a-4760711fb154'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-01','NURULLAH AKSOY','İlk Kütahya ziyaretimde görüştüğümüz Hürok satın alma yetkilsi Nurullah bey İş makinası yeni konusunda iletişimde olacaklarını fakat  yenileme işlerini Kütahya Merkezli bir firma üzerinden  çalıştıkları bilgisini vermişti. Firmanın Bölgede çalışmaya başladığımız SE-BA lastik olduğu öğrenmmiştim. Hürok mermerin yenileme işini direk alamasakda dolaylı yoldan yenilemeye almış olduk .Aynı dolaylı yöntem  Mutaş madencilik yerine gelen Ünaldı maden içinde uygulanmıştı.Mutaş maden gibi firmalar Kütahya merkezi olmadığı için Kütahya yerel tedarikçiler ile çok işi olmuyordu. Fakat Ünaldı , Hürok gibi yerel firmaların bölge tedarikçileri ile aidiyet ilişkisi kuvvetli. Şirketimiz için faydalı olacak en uygun strateji ile  potansiyel yönetilecek ..','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('47cc0786-3e36-5a9e-bc44-0df9ad82846d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TARHAN MADENCİLİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'24d056a3-6b35-5604-9c1e-bdd4b2aca804'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-01','ALİ TUNÇBİLEK','Kütahya Tavşanlı Deve kayası bölgesinde Kömür madenciliği yapan Tarhan madencilik Kütahyanın Eski bildiğimizi Büyük işler alan Tarhan madencilikten farklı olduklarını Kendileri nin İstanbul merkeli bir firma olduklarını ilettiler. Geçmiş dönemde son bölge ziyartimde şantiyeye yeni açılma aşamasındaydı . Şu an potansiyeli bir hayli arttırmışlar. Şantiyede 3 adet Lastikli yükleyici ve 6 adet hafriyat tipi lastik kullanan damperli hafriyat kamyonları mevcut. Yetkliye ürün ve hizmetlerimiz konusunda bilgiler iletildi. Kütahya ziyaretlerinde iletişim kuvvetlenmesi için  uğranılması gereken firmalar arasında olacak.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a3cfc6a9-2d1d-572e-9910-addfa0232f35','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EGE TAŞKÖMÜRÜ KÜTAHYA' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'7632f4c2-1bd1-530b-a3fb-9a15680a2947'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-01','MESUT SAĞIROĞLU','Mesut bey Ege Taşkömütü firmasının satın alma yetklisi geçmiş dönemde yeni TBR lastik satışımız olmuştu. Mesut beyden çalışmalarının aynı rutinde devam ettiği bilgisi alındı. Tüm lastik alımlarında bizlerden teklif alınması için tedarikçi kaydımız güncellendi .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ea602a6b-c160-50d3-b621-32b773fc9e2e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SE-BA' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'0263cb89-61db-5e43-afad-e64030db29b2'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-01','SERKAN BAŞAR','SE-BA Lastik ile önümüzdeki hafta Kütahya bölgesinde İş makinası Yenileme çalışması yaptığı firmalara birlikte ziyaret planı yaptık. Bölgede yaşaması ve firmalarla güvene dayalı iyi bir iletişimi mevcut.  SE-BA lastiğin bölgede TBR yenileme ağırlığıda bir hayli fazla bu konuda alt segment genelde Dirpa ve Doruklara alt kalite yenilemeler yaptırıyor. Bu konuda neler yapılabileceğinide birikte ziyaret planı içerisinde değerlendireceğiz . Çalışma sistemi içerisinde anaşılan vade ödemelerine sağdık kalındığı sürece firmayı bölgede bir süre kullanmak bizler için faydalı olacağı kanaatindeyim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c799af9e-8ce4-5e2a-be2a-6b4a7d3a5a25','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SER NAK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'d9512385-5416-5b17-a5b6-c0a647eebdf2'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-01','GÜRHAN SALİM','Kütahya Seramik fabrikasının nakliye işini organize eden SER NAK firmasına Yine Kütahya Nakliye firmaların dan Gülteki nakliyat referansı ile ziyart ettim. Firma nakliye organizasyonun büyük br kısmını kiralık araçlarla yönetiyor.  Nakliye kantininde araç sahipleri ile yaptığım görüşmede Kütahya seramiğe çalışan 3-4 aracı olan firmala ile de görüştüm. 315/70  385/65 385/55 ağırlığı mevcut . Kullandıkları markaların  eskisi gibi aynı markadan değil araştırarak o an uygun olan markalardan ihtiyaçlarını karşıladıkları bilgisini aldım. Ürün ve Marka bilgileri iletildi.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('856408d0-5e18-59b1-b434-acdf30ee23b0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NEMLİ TAŞIMACILIK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'e1f69dcd-0cb1-579a-a85f-c4f672ac3491'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-02','LATİF BARİKA','Nemli taşımacılığa bayramdan önce 32 adet bridgestone TBR için fiyat vermiştik. Brisa ürünlerine zam geleceği için Latif beyi bilgilndirdim. Zamdan etkilenmemek için ihtiyaçlarını bu hafta netleştirilmesi gerektiğini ilettim. Bölge bayisi Özkan oto Nemli için bedelsiz vereceği 72 adet Lassa lastiği sonuçlandıramamışlar. Birazda o süreci beklediklerini belirtiler.Kademe de latik sorumlusu Erdem ile yaptığımız sohbette en son denemek için aldıkları Dayton 13R22.5   D800M lastikleri 1 kaplama bile yaptırmadan iade olduklarını . Petlas 13R22.5 SY800 Lastiklerin bir çoğunu 3. yenileme işlemi yapıldığını belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('20c14712-8564-5e84-bef7-d0d61f2e7b29','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EYLAS CONTİNENTAL BÖLGE BAYİİ' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'bec83200-bbd8-51ae-95fd-1987043abc7e'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-02','LEVENT SIRTALAN','Bölge Brisa bayisinden ayrılan Levent Sırtalan Eylas firmasına geçtiği bilgisi üzerine yaptığım ziyarette Continental bayisi Eylas  ın Sadece yoldan geçen uzun yol tipi lastiklerle hizmet verebildiğini kendisinden beklentilerinin inşaat grubu lastik satışlarının arttırılması yönünde olduğunu iletti. Fakat Continental markası ile hafriyat tipi satışları  yapamayacaklarını Eylas sahibine  iletmiş. Bizim ürün grupları içerisinde olan Kumhoyu önerdim. Hafriyat grubunda olan gruplara ait fiyat ve desen bilgilerini ilettim. Takip edeceğim .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ec412ddc-385b-5f04-8491-2c92dae37e37','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BEYAZ MADEN' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'3273659b-7305-56a2-87f4-6bd510a63a96'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-02','EMRE KAYSIN','Beyaz maden şantiyesinde Seramik fabrikaları için ham madde işi yapmıyor.  lastikli gruta 23.5R25 ebat kullanan  2 adet loderi mevcut .2 adet de saha içerisinde kulladıkları damperli kamyonları var . Geçmiş dönemde loderleri için yenileme işini biz yamıştık. Loderlerin tekrar yenileme ihtiyacı oluşmaya başladığı tespit edildi. Seramik fabrikalarında üretimin %50 alması işlerine ciddi oranda etkilediği için yenileme işlemini şu an yaptırmayı planlmadıkalrını ilettiler . Yenilemeye karar verildiğinde iletişimde olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1b558e9e-9605-5473-a653-03cda82b1b48','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAGNESİT A.Ş.' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8ca82b4d-5017-52bc-b85e-35bb35f5b074'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-02','İSHAK ÖZCAN','Magnesite ilk ziyaretimde İş makinası yenileme işini Atlı ya verdikleri bilgisini almştım. Kademe yetkilsi İshak Özcan yenileme işlerinin eski dönemde olduğu gibi tekrar bize verecek. Magnesit Üretiminin %50 oranın azalması ile yenileme işleride doğru orantılı olarak azalmış ve süreleri uzamış . Şu an Atlı ile konuştukları yenileme sürecinde bekleyen işlerin toplarlanmasını sağlayacaklar.Sonrasında devreye gireceğiz','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6b70c0fc-d251-5ad6-9946-fe0f18ff5ac3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AND LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ab397ae5-ec14-5e3f-9dc1-8097f3166289'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-02','ÜNAL ATEŞ','AND lastik Ünal bey Eskişehirde geçmiş dönemde uzun yıllar Brisa bayiliği yapmış bir firma . KRB yi  iyi tanıyor. Yaşadıkaları mali ve yönetimsel sıkıntıları atlatmaya başladıklarını gözlemliyorum. Çalışma şekli son kullanıcılara nakliye sahiplerine günlük montaj hizmeti ile lastik satışı yapıyor. Toplu satışı yok denecek kadar az.Uzun yıllardır sektörde olan Ünal bey Türkiyede  tabelalı bayilik yapılacak tek markanın Lassa Bridgestone olduğunu düşündüğünü belirtti. Kendisine bu konuda bayilik konusunda imkan olsa tekrar düşünür müsün şeklinde sorduğumda düşenebileceğini iletti.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('22c8a68e-284f-52c5-8a8e-95087e46e8b8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TECHTO MADENCİLİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'48472f3d-aaf1-52b2-9778-8af2dbcc6432'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-03','METEHAN KOÇYİĞİT','Techto Maden Bursa merkezli Maden ve enerji firması . Kümaş A.ş. Beşçam Ocaklarındaki tüm dekapaj işini alan firma. Çalıştığımız Ünaldı madencilik Techto madene taşerönlük yapıyor.Metahan bey Şantiyede kendilerine ait ekipman şu an için bulunmadığı fakat süreç içerisinde Beşçam şantiyesinde kendileine ait İş makinaarı olacağını belirtti. olacağını kamyon grubunu yine taşerönlerle yönetcekleri bilgisi alındı. Kümaş A.ş. nin Fabrika içi taşerönü henüz belli olmadı. Mutaş madencilik fabrika içi hammadde sevkiyat işini devam ettirmekte. Kütahya bölgesinde magnesit , Kömür madenciliğinde bir miktar hareketlilik mevcut . Bölge de daha fazla zaman geçireceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('29d5c245-a1a2-507b-bb25-303176d825a1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAMBOVA MADEN' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'a7f2ac36-3f72-5904-abc5-4e5b607ea442'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-03',NULL,'Tambova Maden Magnesit sektörün bölgede en eski firmalarından Magnesit A.ş. nin çok eski taşerönü . Magnesit A.ş. de üretimin çok düşmesi ve uzun sürmesi sebebi ile faaliyetlerini durdurmuşlar. Şantiyeyi boşaltmışlar. Firma bünyesinde bulunan iş makinalarını satılığa çıkarmışlar. Tambova maden Nemli taşımacılık ve Koçhan maden yokken Magnesit .A.Ş. nin en büyük ve tek taşerönüydü.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('19867ab0-3c1a-5349-8c9a-39bcfc420731','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KOÇHAN MADEN' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'a22ffcb0-cc9c-5d1e-9c7f-a5002a1489ac'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-03','YALÇIN KOÇHAN','Tambova madenin faaliyeetini durdurması sonucunda  Koçhan maden ana firmanın üretimi azaltması ile sıkıntıda olduklarını fakat Nemli ile birlikte faaliterlerine şimdilik devam ettiklerini belittiler. Koçhan madende iki adet lastikli 26.5R 25 lastik kullanan L150 volvo ve XCMG  loder mevcut . Magnesit sektörünü ilk kez bu kadar sorunlu ve sıkıntıda olarak gözlemliyorum. Uzun yıllar bölgeye istihdam ve ekonomik katkı veren sektörün bu yıl güçlü görünümünden uzak izlenimler veriyor. Madenin yurtdışı ihracat durumu olması da firmalara gerekli katkıyı vermiyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f543eb1d-a31c-5eb1-8931-5afa26a732cf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DENİZ GRANİT SÖĞÜT' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'234afe01-48ec-5950-8cca-1fcb92c21e63'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-03','ÖMER KELES','Deniz Granit Söğüt Dudaş köyünde mermer ocağı işletmesi mevcut . Bölgede  Gökyar Mermer ile birlikte çalışan nadir  mermer ocağı durumundalar .Önümüzdeki hafta Afyonda yapılacak blok mermer fuarına katılacakların ürettikleri taş için umutlu olduklarını belirttiler.Fuarda alacakalrı siparişe göre çalışma şekillerini belirleyeceklerini tedariklerini oan göre yapacaklarını ilettiler. Firmanın Ocağında 2 adet lastikli loder 1 adet kaya kamyonu mevcut .Göksutaş mermer ile bu yıl ortak lık kurmuşlar. Bende 17-20 haziranda yapılacak Afyon blok mermer furarını sektörün son durumu gözlemlemek adına günü birlik ziyaret edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b1242ba3-d943-5a62-b411-8e297c52657b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TÜRE VİNÇ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'3b80f7c1-adc5-5c3f-a7eb-7348bfdaaac9'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-03','VEYSEL TÜRE','Veysel beye bayramdan önce 315/80R22.5 Hubrac asfalt çeker lastik teklifi vermiştim. Sonucu öğrenmek için ziyaret ettim. Aracın lastiğe acil ihtiyacı gündeme geldiği için bölgeden Linglong olarak bizim verdiğimiz fiyata yakın  montaj dahil olarak alımı yapmışlar. Stok olarakda alımları olan firmanın sonraki takeplerinde devrede olacağız geçmiş önemde firmaya stok satışları yapılmıştı.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b21c84c6-076b-5a75-9752-7a74f898f304','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NOMAD MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e6e9ad7a-7930-5794-808d-40e8500e564e'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-04','ULAŞ GÜNAÇAR','Nomad Maden Faaliyetlerni sonladıran Mutaş madenin diğer firması dır. Kümaş Ana yüklenicilik işlerinin bitmesi ile makinaları Nomad üzerinden satılağa çıkarmış durumdalar. Satılığa çıkarmadan önce 4 adet L120 Volvo loderin 16 adet lastiğin yenilenmesi talebi mevcut. Verilen fiyatlar dan  danlaşma sağlandı. 4 lü adetler şeklinde 3 turda lastiklerin yenileme işlemini tamamlamayı planıyoruz.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e851b8c7-8177-5391-af87-ca58739e54d3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İLHAN VİNÇ' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'4c9b7c99-fc9b-563c-8a04-223bb2146ccb'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-04','GÜRKAN İLHAN','İlhan Vinç bünyesinde Forklfden Mobil vince 32 adet araç parkı mevcut.Kullanılan ebat çeşitlililiği bir hayli fazla,  Ürün ve hizmetlerimiz konusunda bilgiler iletildi. Lastik talepleri oluştuğunda irtibatta olacağız. Bölgenin en kapsamlı araç parkına sahip firma ile ilişkilerşn olgunlaşması için bir kaç ziyaret daha iletişimi kalıcı şekle getirecektir.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('78a397e2-ff25-52b7-a775-9c437d1ed5c0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PRİZMA LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'f8c1ac41-ab06-5654-9c53-b17b34f7013d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-04','MUSTAFA YÖNGÜL','Prizma Lastik  Kütahya da TBR ağırlıklı çalışan toptan firmasına 2. ziyareti gerçekleştirdi. Bölgede Fatih lastik ile birlikte TBR satış ağırlığı bulunan yetkili Musafa bey e ürün ve hizmetlerimiz konusunda 2. hatıratma yapıldı. Bu şekilde gelip geciçi bir irtibattan çok kalıcı ve güvenilir ilişkiyi sağlamaya çabasında olduğunu kanıtlamaya gayret ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d7a9e72b-267b-543c-b535-fd85b5d7cad7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FATİH OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'7fedcc35-c33f-5763-8a22-20b9e67a0a60'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-04','KASIM ÇANAK','Fatih lastik Sahibi Kasım bey bölgede TBR ağırlığı en yüksek olan grupta yer alıyor. .Herhangi bir marka bayiliği yok. Bölgede Conti ve Ling long  satış ağırlığının yoğun olduğunu Kumho ve Hubtrac içinde ihityaç durumunda rekabetçi şartlar oluşturulacağını  iletmiştim. Bilgilerin tekrar üzerinde geçmek ve ilişkileri daha çok geliştirmek için bu firmaya ziyaret sıklığını arttıracağım. Bölgede yaptığı ticaret ve güvenilirlik konusunda iyi ismi olan bir firma.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c41ff905-c41e-5a4d-9317-1ff848e8c008','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ECAN LOJİSTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'f1afcdea-0faa-5960-88d1-2455a39c5cfc'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-05','GÖKTUĞ CAN','Ekrem Can lojistik Göktuğ bey geçen ay yaptığımız ik görüşmeden sonra herhengi bir ihtiyaç oluşmadığı için alım yapmadıklaını belirttiler. İhtiyaç oluşması durumunda bizlerden de teklif almadan alım yapmayacaklarını bilgisini teyit ettim. Geçmiş dönemde premium grupta dan başka alım yapmakıklaını fakat son alımlarını Ling long markadan yana denemek amacı ile kullanmışlar. Bizim Hubtrac markamız ve üretim koşulları hakkında ilk ziyarette verdiğim bilgiyi tekrar üzerinden geçtik.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1be1fcb2-edbd-5e6e-a6f1-db377b360715','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YKS LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'c1a577e6-67ec-5a05-9bc9-7b11013e0a42'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-05','HALİL ÇALIKDOR','YKS lastik 1 aydır tüm lastik alımlarını durdurmuş . Stokları eritme ve nakite çevirme hedefine odaklanmışlar . Bir süre YKS  ile ticareti kontrollü yapmak faydalı olacaktır. Aldıkları Michelin bayiliği taahüdü zorunlu adetlerin geldiği ve stok şişkinlinliği arttırdığı bilgisi alındı.  YKS lastiğe ait güncel  durumunu öğrendiğim için kampanya bilglendrmesi yapmadım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d6b246c5-0e11-53e7-8613-26476dd79be5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DURAK ŞAHİN LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'29d14c18-98b4-5a6e-ac3e-c6d4274834d8'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-05','VOLKAN AY','Bu gün yayınlanan kampanya bilgileri paylaşıldı. Lastik sektöründe haziran başında uygulanacak zam sonrasında kampanya ürünlerinin daha değerli duruma geleceği izah edildi. Kampamyaya koşullarına ilginin ebat ve segment kaynaklı çok yüksek olmadığını gözlemledim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('32289573-831e-5935-b8a5-83d42fdf9524','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EYLAS LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'af1b30b9-6956-5e3b-9428-6c2f2cea1c0f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-05','LEVENT SIRTALAN','Bayiliklerini yaptıkları Continental markasınına alt kalite ürün arayışları olduğu bilgim vardı. Bu gün yayınlanan kampanya bilgileri paylaşıldı. Lastik sektöründe haziran başında uygulanacak zam sonrasında kampanya ürünlerinin daha değerli duruma geleceği izah edildi.  İç değerlendirmelerini yaparak 12 Haziran kampanya süresi içerisinde bilgi verecekler.Farklı ebatlarda stok oluşturma isteklerinide hitap edeceğini düşündüm.  Kumho marka nın elimizdeki kampanya dışı ebatları ile de ilgilide bilgiler iletildi.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f20a01ac-41eb-548c-b6bb-889bd346b7d6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATG LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ce6c8f09-e0a2-594e-917e-042be990ed69'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-05','MEHMET GÜLLÜ','Bu gün yayınlanan kampanya bilgileri paylaşıldı. Lastik sektöründe haziran başında uygulanacak zam sonrasında kampanya ürünlerinin daha değerli duruma geleceği izah edildi. Kampamyaya koşullarına ilginin çok yüksek olmadığını gözlemledim. Bölgesel Popüler ebatlar için kampanyalar olduğunda haber verilmesi talebi alındı','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('359d79e0-1142-5c0e-9207-d9ebae1a6f98','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SÜMER BETON' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'df6a90fc-50fb-53ef-b61e-85e401a14e65'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-09','ORAL MUTAY.','Sümer beton yetkilisi OAL BEY Sümer beton olarak tüm tesislerde 315/70 ve 295/80 ebatlarını kullandıklarını . Yeni lastik olarak alımlarını Ankara merkezden yaptıklarını belirttiler. Uzun yıllar Lassa markası kullandıklarını ve memnun olduklarını fakat merkez satın almaları bu yıl alımlarını Petlas markasına çeirdiklerini, ilettiler. Yenileme kabiliyetini onlarda merak ediyorlar. Henüz yenileme ihtiyacı oluşmamış. .Yenileme tarafında satın alma yetkilerinin tesisilerde olduğunu yenileme için vermiş olduğu mail adresine detaylı bir sunum göndereceğim . Karlılıkların düşmesi sebebi ile belirttikleri 2 ebat için rekabetçi ve alternatifli  fiyat gönderilmesini istediler..','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9e1983da-bde2-5300-a6de-726d6961bac2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ARI BETON' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'f5bdd09c-9fdd-56b3-ab4e-ab0d52eae61f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-09','VURAL SİPAHİOĞLU','Bozüyük Arı beton sahibi Vural bey i ziyaretim esnasında dorse  lastik fiyat alınması yönünde araştırma yaptığı ana denk geldiğini belirtti. . Herhalde senin nasibin şeklinde yorumladı. 4 adet Dorse lastiği için lastik başına yük taşıma kapasitesi en yüksek olanından alım yapmak istediğini iletti.164 K dorse lastikleri işini göreceği iletilerek  Lassa dahil Continental ve Kumho ve Hubtrac alternatifli teklifimiz iletildi. Netleştirdiğinde bilgi vereceğini iletti.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('84c1e779-0f00-557f-9424-e7b5ce5c9f46','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAL LASTİK' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5ce1faed-2083-5b76-8789-2c9ededb6453'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-09','ÖZGÜR AYAZ','Bozüyük Prelli bayi Özgür bey Prelli ağırlıklı çalıştıklarını Continental ve Ling Long stoklarınında bulunduğunu belirtti. Continental , Hubtrac ve Kumho markaları için ihtiyaç durumlarında bizdende teklif alacaklarını fakat işlerinin bu dönem sakin olduğunu stoklarının şu an için yeterli olduğunu belirttiler.Firmaya B2B açıldı. Tüm ürünlerimizi sisitemden inceleyecekler','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dea4da44-5538-5781-9cb6-77e6148dc228','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İŞ PAR OTOMOTİV' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5fa0c007-29f4-5c3a-bc77-66d055e21690'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-09','KAAN YÜKSEL','Bozüyük Continental bayi Kaan bey Conti harici Ling Long stoklarında bulunduğunu belirtti. Ling long bozüyükde her ana markanın ürün yelpazesinde mevut. Üretim durumu olarak Hubrac ile üretim benzerliğinden bahsedildi. Firmaya B2B açıldı. Tüm ürünlerimizi sisitemden inceleyecekler','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('644c5093-003c-5fda-a1a8-f80fb8cacb72','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERGÜNLER YOL YAPI' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a22ff996-3c03-5d2f-b4ca-9743f9f38bf4'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-10','BÜNYAMİN AKBAYIR','Bursa Ergünler yol yapıda Satın alma yetkilisi Kemal beyin yerine Bünyamin bey devam başlamış. Şirketin eski çalışanı saha operansyon yönetiminden satın almaya geçiş olmuş teknik detaylara hakim. Kamyon yenilemede Bursa Doruklar ile çalıştıklarını ve memnun olduklarını belirttiler .Kamyon grubunda başka firmadan teklif almıyolar. İş makinası yenilemede fiyat alabileceklerni belirttiler.   Lassa Bridgestone yeni kamyon lastiği  alımlarında  Sevtar ile çalıştıklarını fakat bizlerden  de bu konuda teklif alacakalarını ilettiler. Brisa grubu talepleri için Memduh beye aldığım Vergi numarasını ileterek sorgulamasını yaptıracağım . Bu yıl ilk defa Ling long ve Çin lastiği alımı yaptıklarını ve denediklerin belirttiler. Çin lastiğinden yakın zamanda Dorklara yenilemeye gönderdiklerini ve sonucu beklediklerini ilettiler. Ekskavatör için 2 adet 12.00 - 20 havalı set ihtiyaçları olduğunu ilettiler Teklifimiz iletildi. Dönüş bekliyorum. Konular eskiden olduğu gibi hızlı bir şekilde sonuçlanmıyor. İşlerin sakinleşmesi tedarik sonuçlanma hızlarıda yansıyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3d3a0aea-f09f-5259-bebb-4a3d573e5daf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İKİESENLER İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'6a5f4752-6044-59c0-9a44-8777bd6e921a'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-10','CEMİL ESEN','İkiesenler sahibi Cemil beye İlk ziyaretimde 17.5R25 Greyder lastiği için verdiğim yenileme  teklifin son durumu öğrenmek için ziyaret ettim. Yenilime işlemini beklettiklerini . Bursa büyüşehir belediyesine yoğun bir şekilde iş makinası kiralama işleride belediyedeki değişiklik ve belirsizlikten dolayı makinaların şu an için belediye hizmetine gönderilmediğini belirtti. İlk ziyaretide satışı yapılan 10 adet iç lastik ödemesinide 20 haziran da alacakları hak ediş ile nakit havale olarak kapatacakları bilgisi aldım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('87c0d50c-dda6-5aa8-ae0d-4c7b6f63dcb9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KCS KOÇASLANLAR BURSA' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8da1e915-2960-56dd-a004-d5a15b85de1c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-10','MEHMET AYDIN','Koç aslanlar Bursa Ovaakça satın alma sorumlusu Mehmet bey ie geçmiş dönemde çalışmıştık. İhtiyaçlarının bizim tarafımızdan eskisi gibi tekliflendirilmesi için cari kartımızı tekrar aktif duruma aldı. Artık eski dönemdeki gibi tüm lastik alımları bana mail olarak gelecek ..','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d26e586f-bf6c-5133-8d09-0b71c34ad048','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TURANLAR HAFRİYAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'27cdfd98-367d-574a-9701-937f74d4ae54'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-10','VOLKAN TURA','Bursa hariyat firması Turanalar da  7 adet kamyon ve 4 lastik lastikli iş makinası mevcut. 315/80 315/70  ve 385/65 ebat ağırlığı mevcut . Son alımlarını 12 adet Prometeon tercih etmişler. Yıl başında aldıkalrı lastikleri Lassa olarak almışlar Değişikliğin nedeni sorduğumda alım yaptıkları muhattabın firmaları için Fiyat performans olarak  daha kazaçlı olacağı yönnünde izahatını test etmek istemişler.Firma Bursa bölgesinde bir hayli hafriyat işi almış Yıl sonuna kadar işlernin olduğunu belirttiler. Bu sebeple bende firmaya sık uğraılacaklar grubuna aldım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c2e7a94c-84ad-5a13-bb8a-b23f2a4b4944','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURSA BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'508014a9-495c-58a1-b288-ab581752d478'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-10','ÜSTÜN TAYAR','Bursa Beton firmasına son ziyaretimde Beton satrallerinde araçların Yarısına yakınını tesislerde yatar duruma aldıkaalrı bilgisi mevcuttu. Durumda pozitif yönde değişiklik olmadığı belirtildi. Tabiki tüm personel potansiyelin bu şekilde olması sebebi ile tedirginleri mevcut . Taşerön olarak çalışan firmalara ait mikserlerin çalışacağı kendilerine ait olanların azalmaya devam edeceği planlanıyor. Taş ocakları Beton santrali haricinde besleme yaptıkları için Ocakalarda çalışan 13R22.5 kullanan kamyonlarda ve İş makinası yeni veya yenilemede taleplerinin sezon içinde oluşacağı o grupta çalışacağımızı belirttiler. TBR grubunda kullandıkları Lassa markası için Brisanın başka bir bayisine bağlılar. Başka marka alımıda yapmıyorlar. Bizden son aldıkları Continentalden Başiskele tesisinde çok memnun kaldıklaını fakat fiyat yüksekliğinden dolayı tesislere yayamadıkalarını  Lassa dan devam ettiklerini belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6cc14edc-4992-5d54-863b-b2d3f2f11d02','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UÇAR LASTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ec9eb7ab-b448-50aa-a4ee-1b3698d1471d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-10','ABDULLAH UÇAR','Uçar lastik İş makinası tarafına bakan Abdullah bey den geçen hafta 2 adet 23.5r25 yenilemeye almıştık. Onları bıraktığımızda 4 adet de yenilemeye 23.5R25 alındı. İnegöl bölgesinde OTR grubunda müşteri portföyleri oldukça geniş. Ovakent ile çalışıyorlardı. Frma sahipleri Eskişehirli oldukları için tanışıklığımız mevcut. ve eski dönemde olduğu gibi iş makinası Tamir ve yenileme işleini bize çevirdiler. Yeni İş makinası konusunda kendileri girmiyorlar fakat talepler geldiğinde bana yönledirecekler. Görüşme ve ziyaretleri ben yöneteceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('704d1367-6260-5353-98b5-69df308f9ab9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HÜROK MERMER' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'8d4bf266-1b21-5e34-b23a-4760711fb154'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-11','KEMAL OLCAR.','Hürok mermerin Sivrihisar ocağındaki L220 volvoya ait 2adet 29.5 R25 bayramdan önce Seba lastik araclığı ile alınmıştı. Se ba lastik sahibi Serkan Hürok mermer Kütahyada lastik yenileme işi yaparken Hüsnü beyin yanında yetişmiş . Bu yüzden tüm lastik işlerin ona veriyor. Bizde işi  Se ba lastiğe yapıyoruz .Hüsnü beyin oğlu Kemal bey ile tüm marka ve hizmetlerimiz açıklanırken Kumho lastik ilgisini çekti. Lastik yenileme işi yaptıkları 2007 li yıllarda Kumho lastiği Türkiyeye getiren firmadan alarak bölgelerinde çok sayıda sattıklarını ve bölgede çok memenuniyet yarattığını belirtti. Aynı performası bu gün de de devam ettirip ettirmediği sorusuda olumlu olarak yanıtlandı.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c82f8f40-4506-50ed-8284-c303f6358237','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'87f63dd0-0f29-589c-9ec4-645ac9f7e9f1'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-11','YUNUS AKBAŞ','Mutaş maden Kümaş beş çam ocakalrını boşalttıktan sonra Tüm ekipmanlarını Kütahya yolu üzerindeki Petrolistasyonalrının arkasındai alana aldıklar. Mutaş madenciliğin tüm iş makineleri bu alanda . 8 adet lastik tekerlekli loderi satışa çıkarmışlar . Lastiklerinin yenileme yapılarak satmak istedikleri makinalaa ekspertiz yapılarak müdehale gerektiren lastikler tespit edildi. 16 adet lastik fiyatımız iletildi. Merkez ile görüşerek alınacak onaya istianden makinalar askıya alınarak lastikler yenileme işlemine alınacak .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('af398a85-2911-50aa-b1ca-2f5e841bd496','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALKERSAN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'dd3e6d0a-6363-5a7b-acb5-9f503ab4b53b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-11','MUHARREM YILMAZ','Kütahya Eskişehir yolunda alker üretimi yapan firma da 2 adet  26.5R25 kullanan lastik tekerlekli loder  7adet 315/70 ve 385/65 kulanan araçları mevcut . Latik yenilemeyi Bursa Dirpa ile çalıştıklarını en son aldıkları lastikleri Ling Long tercih ettilerini belirttiler.Ürün ve hizmetlerimiz konusunda bilgiler verildi . Daha sık ziyarelerle ticaretin başlama ihtimali oldukça fazla oduğunu tespit ettim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f9bc2992-b08f-5b49-917e-aa4b2c63973a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ARI BETON HAFRİYAT' AND il IS NOT DISTINCT FROM 'BOZÜYÜK' LIMIT 1),'8264342e-4671-5833-91cc-0fb0a6de82c9'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-11','VURAL SİPAHİ','Ziyaretlerde dönüşler olmaya başladı. İnşallah artarak devam eder .Son  yapılan ziyarete isinaden firma sahibi  Vural bey dönüş yaptı İhtiyaçları olan 8 adet dorse lastiği verilen fiyata istinaden satış gerçekleşti. Lastikler firmanın bozüyük fatura adresine  sevk edilecek .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2422d230-aef6-5d3b-8746-158778938cdc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EGÜNLER ASFALT yol yapı' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'3fd3a008-0ca0-5762-970e-1a30c41e30d6'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-11',NULL,'Erünler yol yapı firması dün yapmış olduğum ziyarete isitnaden Bu gün 6 adet 245/70R17.5 10 adet 385/65R22.5 için dönüş yaptılar . Stoklarımızda bulunan Kumho Hubtrac Matador markalarından teklif alternatifli olarak gönderildi. Lassa da fiyat  vermek istedim. Memduh beye firmanın vergi numrasını ve talep edilen bilgileri gönderdim . Alınan ilave özel fiyat müşterimize iletildi. Teklif onayı bekleniyor .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f3558ee3-006c-51c1-8191-6ee59dfbac8d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SE-BA ALSTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'d76a9ded-74e9-52cb-8061-93bb918dbddd'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','SERKAN BAŞAR','Seba lastik ile İş makinası yenileme konusunda Çlaışmaya başladık. Çalışmaya başlama konusunda sizinlede süreci takip ederiz ona göre devamı için karar veririz bir başlayım  şeklinde konuşmuştuk. 15 Günlük süreçte 500.000 TL ciro oluştu. Bu gün Kütahya programımda Tutara karşılık anlaşılan 90 günlük çek alındı ve Finans departmanına kargolandı. Verilen taahütler karşılıklı olarak ilk işlemde yerine getirilmiş oldu. Ünaldı maden işlerinin beş çam magnesit ocağında artması ve tüm tedarikçileri den yoğun ziyaret alması sebebi ile iş makinaı yenileme de Atlı dahil bir çok firma devrede ama ilk işi biz aldığımız için süreç bizim üzerimizden ilerlemekte.Bu sebeple SE BA  lastik Ünadı madene direk KRB direk ve rekabetçi fiyat vermek için bizim devrede olmamızın daha doğru olacağını Ünaldı maden sahibine iletmiş. Ünaldı maden ile 16 haziran Salı günü bu konuyu netleştirmek için randevu aldım. 90 gün vade yerine Atlı 120 gün vade yapılabileceğini iletmiş.  Görüşme için sizlerden 120 gün için vade ve fiyat konusunda onay ve bilgilerinizi rica edeceğim. SE BA  lastikler bölgede Ünaldı harici diğer müşterilerde İş makinası yenileme işleri devam edeceği için Seba lastik de Ünaldı madenin bizde kalması için desteğini verecek .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f8f96c9e-2b01-5e3b-a987-d86be2aff047','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KURTNAK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'c1cb6e81-8fa8-5053-b381-5bd8ed7ab9ef'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','MUHARREM KURT','Kurtnak firması Kğtahya merkezli 40 adet aracı olan  Düzce camın nakliye işini yapan firma 315/70 - 315/80  385/65 385/55 ebatlarını kullanmakta. Uygun fiyatlı tüm amarkaları kulanıyor. Marka bağımlılığı yok. Uygun fiyatlı bulduğunda lastikleri ihtyacı dışında da alarak Kütahya piyasasıdna pazarlıyor. Tekliflerini 90 gün olarak talep ediyor. Son yaptıkları alımı 70 adet petlasdan yapmışlar. Bir önceki alımlarında uygun fiyatlı buldukları Ling Long tercih edimiş .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a5ce9a42-951f-51d7-930d-d35728480775','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FATİH OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'7fedcc35-c33f-5763-8a22-20b9e67a0a60'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','KASIM ÇANAK','Kütahya TBR lastik konusunda bölgede tanınan ve potansiyeli en yüksek firma . Daha önce ben bu durumu tespit etmiştim  İlk ziyaretimide yapıştım. Fakat çok fazla etki bırakılmadığı için dönüşler başlamamıştı. İkinci ziyaretim daha verimli geçti ilk ziyaretimde tedarikçileri konusunda bilgi vermezken bu ziyaretimde Continental ve Ling long ağırlığında çalıştıkalrını Continentali Eskişehir Aksoy Otodan para kazabilecekleri uygun koşullarda aldıklarını belirttiler. İkinci ziyaretin bir sonraki tedarik sürecinde bizlerinde devrede olmasının sağlandığını düşünüyorum. Taleplere verilecek koşullar ilişkinin potansiyeli konusunda belirleyici olacak .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c9c4592d-6c28-5893-a01e-8a9f5f372d46','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PRİZMA LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'f8c1ac41-ab06-5654-9c53-b17b34f7013d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','MUSTAFA YÖNGÜL','Prizma Lastik  Kütahya da TBR ağırlıklı çalışıyor. Michelin bayisi fakat fiyat yüksekliğinde dolayı talebasını taşıkları markanın satış adetleri diğer sattıkları adetin altında . İkinci ziyartler daha kalıcı ve etkili  olduğu ısrarın ve Kütahya bölgesinde TBR grubunda  ziyart sıklığının artmasının daha fazla sonuçlar vereceğini düşünüyorum . Bölgenin dinamikleri ve potansiyeli daha anlaşılır hale geliyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4aea392e-9560-5f01-90d7-09ccc4caa4a6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ARI BETON HAFRİYAT' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'743d1ece-ab70-5007-b4f1-3ee559c5b350'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-15','VURAL SİPAHİOĞLU','Geçen hafta Satışı Kredi kartı çekimi olarak anlaşılan satışınc kredi kart çekim işlemi tamamlandı .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('24004e4e-8250-55b8-9db5-f15f0ecb2a2d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UÇAR LASTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ec9eb7ab-b448-50aa-a4ee-1b3698d1471d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','ABDULLAH UÇAR','Uçar Lastikden iş makinası yenileme işini bizden sonra Ovakent ile çalışmaya başladığını iletmişti. Ziyaretim neticesinde  4 adet 23.5R25 lastik alımı için anlaştık.  Turgayın programına göre İnegöl den alınması için ruta  ilave edilmişti. Fakat Kemal beyin Bursa bölgede acil bir işlemi çıkması ve bu işlemin işçilik gerektimemesi sebebi ile o hafta rutun yetişmesi  amaçlı  nakliye ile müşteriden alımı yaptırıldı. .Üretime gelen lastikler için Ahmet Atay beni aradı. lastiklerin üzerinde çok sayıda çivi olmaması sebebi ile raspa işlemi yapılmadığını belirtti.  Temizlenmesi için eleman ve zaman soruNu bulunduğundan dolayı raspa yapılamayacağını raspanın bıçaklarına zarar verdiğini belirtti. Müşteriye dönerek durumu izah ettim. Uçar lastik  metal işinde çalışan müşterisinden bu şekilde çok lastik çıktığını ve Ovakente sürekli bu şekilde göndererek temizleyerek  yenileme yaptırdığını belirtti. Aldığım bilgileri  tekrar Üretim yetkililerine ilettim. Bu arada lastiklerden 1 adeti yarı raspa işlemine yapılmış.. Raspa zarar görmesin diye işe yarıda kesilmiş. Müşterimize Üretimden aldığım lastiklerin yenileme yapılamayacağı bilgisini ilettim. Müşterimiz Sadece yarı raspa yapılan lastiğin  temizlenerek Yenileme yapılmasını diğerlerinin ade edilmesini talep etti. Üretim 1 adet için yenlieme işlemi uygunlamaya çalışacak . Diğer 3 adet lastik iadesi için Turgayın Bursa rutuna ilave edilecek .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('26f2d639-124e-582c-ae4b-3efb2218d397','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERGÜNLER YOL YAPI' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a22ff996-3c03-5d2f-b4ca-9743f9f38bf4'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','BÜNYAMİN AKBAYIR','Ergünler yol yapı firmasına sizde fiyat alarak ilettiğim  %37 iskontolu 245/70R17.5 ve 385/65R22.5 Lassa 310T lastikler için Bünyamin beyi aradım . Sabah toplantıda Adnan nın Atlı için bahsettiği 245/70R17.5 ebat stok bilgisine istinaden sonucu öğrenmek istedim. Bünyamin bey Lassa olarak alımı Atlı dan yaptıklarını belirtti.   Fiyat konusunda her hangi bir bilgi vermek istemedi.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c28053f3-3874-5a9b-afe7-b0bd32f7115a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EYLAS LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'af1b30b9-6956-5e3b-9428-6c2f2cea1c0f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','HÜSEYİN EYİGÜN','Eskişehir Continental bayi Eylas firması Continentale alternatif olarak alt markalar yapılandırmaya çalışıyor. Kumho ve Hubtrac için bir süredir görüşüuoruz. Bölgede Continental TBR ile müşteri kazanamadıklarını  TBR müşteri portföyü oluşturmak adına daha uygun markalara  ihtiyaçları olduğunu tespit etmişler. Elimizde bulunan Talep ettikler 315/80 ve 315/70 hafriyat ve asfalt grupları paylaşıldı. 90 günlük 1 miyon TL tutarında  müşteri  çeki beklediklerini onunla 50 adet ciavrında altrnatif marka alacaklarını belirttiler. Takip ediyorum .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1e395b5e-73a8-5dac-871c-c48f719e7011','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SÜMER BETON' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'df6a90fc-50fb-53ef-b61e-85e401a14e65'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-12','ORAL MUTAY','Sümer Betona geçen hafta yapmış olduğum ziyaret esnasında Oral bey  Kamyon Yenileme konusunda çalışılabileceği ve kendisine mevcut ürnlerle ilgili  teklif iletilmesini istemişti. Alternatifli kamyon yenileme teklifi iletmişti. Teklifimizin durumu Henüz inceleyemediğini ilk çıkacak talepde alternatif olarak bizede sorulacağını ona göre karar vereceklerini ilettiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9b2f81c3-afea-55af-bb1f-0110bf6f9c0f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EGE TAŞKÖMÜR' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'597b674b-2283-56a4-b8b3-f5a2719eb032'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-16','MESUT SARIOĞLU','Kütahya da Kömür üretimi yapan Ege taş kömürü firması nın satın alma Yetklisi Msut beyle geçmiş dönemdede çalışmıştık. İşlerin bu yıl biraz daha sakinlediği kömür ün doğalgaz karşısında her yıl ihtiyacın azaldığı iletildi. İhtiyaçlar drumunda tekrar talepleri ileteceklerini belirtitiler. Ziyaret sonrasında bölge de tanıdıklardan Egetaşın güncel ödeme  durumu hakkında yaptığım araştırmada ödemelerinde gecikmeler ve ertelemelerin arttığı bilgisini aldım . Talep gelme durumunda gerekli tedbiri alacağım. Bölgede Tarhan , Yılmazlar maden , Ünaldı maden Ayka maden , Kayasu amaden dışındaki firmalarda sıkıntı olduğu ,Özasil madenin faaliyetlerini durdurduğu bilgisi alındı . Bölgede ziyaretler tespit edilen sorunsuz firmalar üzerinden ilerleteceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e1ce44bd-2e66-5379-b412-077e6ecb9b47','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e6c4c63a-1a2c-5a2e-9e1e-6399d789e3a0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-16','MEHMET ÜNALDI','Ünaldı maden SahiBi Mehmet bey Lastik yenileme konusunu görüşmek üzere bu gün beni davet etti.Kamyon grubunu SE BA lastik ile uzun yılllardır çalıştıklarını başlangıçda  İş makinasının kontrolününde onda olması nı istediklerini iletti. Fakat ilk işlemler sonucunda bizleri de iyi tanıdığını ve aynı sahada uzun dönemdir Mutaş madenciliğe hizmet veriyor olmamızın önemli olduğunu  makina sektöründen son aldıkları Komatsu makina satış müdürünün eski çalışma arkadaşım olması ve referansı vesilesi ile ilişki güven ortamına evrildi. .Mehmet bey İş makinası konusuda tüm yenileme işlerimizin yine KRB tarafından yapılarak direk Ünaldı madene fatura kesilmesini istedi. Vadelerinin 120 gün olduğunu belirtmesi üzerine vadede 90 günü aşamadığımız bu vadenin üzerinde çalışma vademiz olmadığını ilettim.Hazırlamış olduğum teklifi 90 gün olarak kabul ettiler. Yine İş makinasında yenileme  yapılacak lastikleri ve stok durumunu SE BA lastik yönetecek. Şu an üretime Seba lastik ismiyle gelmiş olan 2 adet 26.5 lastik Ünaldı maden olarak üretilerek ilk işlem başlamış olacak .  Mehmet bey makina sektöründen benim de tanıdığım misafirleri olunca birlikte öğlen  yemek   orgazizasyonu yapınca Kütahya bölgesinde kısııtlı ziyaret yapabildim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a1f43404-607d-5a52-86a5-3f0c31ed21cf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FATİH OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAYA' LIMIT 1),'b52b566e-6bde-59ee-bb02-ea8ccb0a466b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-16','KASIM ÇANAK','Kütahya ziyaretlerimde ilişkiyi oldunlaştırmaya başladığımız Fatih oto lastik bölgenin en kapasiteli TBR grubu lastikçisi. Bölgede referansıda oldukça iyi .Continental ve Matador müşterileri mevcut. Yaınlamış olduğunuz kampanya bilgilerini Conti markasına ilgisini bildiğim için popüler ebatları ilettim. 385/65 THR5 10 adet Matador  315/80 HSR2 6 adet siparişi alındı 90 gün ile sevk edecğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('546523fb-44d6-5db1-aa57-98152bf5466f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'87f63dd0-0f29-589c-9ec4-645ac9f7e9f1'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-16','YUNUS','Se ba lastik ile geçen hafta yapılan ziyaretten sonra Mutaş madenin Beşaçam tesislerinden çıkarılan makinalara ait 16 adet yenilenme ihtiyacı olan lastik tespit etmiştik.İşin büyük ve rakiplerin  çok olacağı  için işi  ilk talebin kendisine gelmesine rağmen bize devretti. Bu gün Mutaş yetkilisi Yunus beye yenileme  teklifimizi 60 gün ödeme koşulu ile 6 adet 23.5R25  10 adet 26.5R25 için ilettim. Takip ediyorum..','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('985297e4-fa38-5f92-a5b9-6af6d68d83a3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DEREKIZIK KOOPERATİFİ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'409684a3-318e-5afc-85b1-22ade2754ed0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-17','YUSUF YOLDAŞ.','Derekızık kooperatif üyelerrine geçmiş dönemde 2 -4 Continental lastik satışlarım olmuştu . Başkan Kamil bey Continental fiyatlarının çok hızlı artmasından dolayı markadan vazgeçildiğini ilettiler. Kooperartif Bursa Erikli su dağıtımını yapıyor.  Eski yönetim gitmiş yeni yönetim Gemlk solasubaşı ile anlaşma yapmış. Ağırlıklı Goodyear ve Hankook tercih ediyorlar. Conti kampayasından 315/80 çeker 90 gün fiyatımız olan 26.900 TL için Goodyear  Muadilini aynı şartlarla 21.000  TL aldıklarını belirttiler.  Kooperatifin 151 üyesi bulunduğu fakat aracı olan üye sayısının 10 a düştüğünü iettiler. Erikli suyunu taşıdıkları illerden dönüşde işlerin bulunaması sebebi ile üyelerin büyük bir kısmının kendilerine ait araçları sattıklarını  10 üye haricinde kendilerinde 18 adet araç bulunduğunu belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('76fea2a0-1343-5407-88a8-7c8c46b4423a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURSA BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'508014a9-495c-58a1-b288-ab581752d478'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-17','ÜSTÜN TAYAR','Bursa betona sizden fiyat alarak iletiğim iş makinası lastik teklfini yakından takip etmek ve son durumu öğrenmek için yaptığım ziyarette teklifin henüz sonuçlanmadığı üst yönetime onaya gittiğini belirttiler. Aynı zamanda Memduh bey den aldığımız destekle talep ettiklei 4 adet TBR lastik teklifimiz iletildi.Bandag bayiliğini aldığımızı bildikleri için bandag ve Avon plus kıyaslaması için 315/80  13R22.5 ve  385/65 ebatları için her iki markadanda teklif talep ettiler. Son yenileme işlemini avon plus olarak  yaptırmışlar. Sizden özel fiyat alarak yenileme','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2cb0f002-82bd-51da-a9c9-e2d8c586e8e7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KAHVECİLER İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'04c03169-e698-5aef-b002-facbfeda8f33'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-17','MELİLŞAH KAHVECİ','Melikşah bey Bursa yıkım ve hafriyat işleri yapan firma . Eski dönemde tanışıklığım mevcuttu. 8 adet hafriyat kamyonu mevcut . İş makinalarının tamamı paletli . Kamyonlarında 315/80 ve 385/65 ebatlarını kullanmakta. Son yaptığı 8 adet alımda  Prelli yi tercih etmiişler. Lassa Bridgeston kullanımlarıda mevcut olduğunu ve alım anında bizlerden de fiyat alacakları nı ilettiler. Bursa da inşaat ve kentsel dönüşümün belediye karşıklılığı ile durulduğu ve uzun zaman dır işlerinn sıkıntılı olduğunu belirttiler..','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d3f1dd26-9fcd-5bca-a19f-8e9de02cf36e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYDINTAŞ VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a8e68155-73d4-589b-881b-1cd8e6b845fd'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-17','DAVUT YILDIZ','Aydıntaş vinç Satın alma yetkilisi Davut beyi ikinci kez ziyaret ettim. 2. ziyartle ilişki daha fazla gelişti. Karşılamalar dahi daha farklı olmaya başladı. Mevcut continental ve kamanya ve stoklarımzda olan  16.00 25 Maxam vinç lastiği bilgisi tekrar iletildi. Continental kampanyayı inceleyeceklerini kamyon lastiğinde stok yaptıklarını fakat Vinç lastiklerini yeni uygulamalarında stok tutmakdıklarıı ihtiyaç olduğunda ihtiyaç kadar aldıklarını ilettiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b5b017b4-faba-5cff-bf02-c18a1ea437ed','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZTİMUR İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'3db47870-a7c3-5432-8561-3dda9f4afbb0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-17','İBAHİM AKYOL','Öztimur inşaat Bursa da Simge ve Ergünler gii asfalt işleri yapan köklü bir firma . Bursa dışında iş almıyorlar. Ağırlıklı olarak belediyelere iş yapıyorlar. Bursa büyük şehir belediyedinde karışıklık bulunması nın işlerini ciddi oranda etkilediği karayollarından da eskisi gibi iş çıkmadığını kedilerinin yaptıklarını belirttiler. 24 adet kamyona sahip firma tüm araçlarını çekmiş beklemekte. sadece Bursa osmangazi belediyesinden küçük asfalt yama işleri çıktığını onunda sadece 2 kamyonlarını meşgul ettiğini belirttiler. Firma Bursa da Crown plaza otellleininde  sahibi olduğu şantiye giderleri için şirketin farklı kollarından finansman ile deteklendiğini belirttiler. Asfalt ve Agrega sektöründeki belirizliğin uzaması durumunda şirketin inşaat kısmında tedbir aalcakalarını ilettiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1c73daa3-de25-5480-8d4d-9d54cd8d7698','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MATEL A.Ş.' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'7bc3701c-1bdc-5463-b6eb-264c957c0e1f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-22','GÖKHAN ENGİN','Gökhan bey sermaik hammaddesi haırlayan işletmelerinde işlerinin geçmiş döneme göre sakinlediğini  Makinalarının çalışma saatlernede yansıdığını iletti. 4 adet L110 volo loderin bulunduğu işletmede yenilemeleri geçmiş dönemde biz yapıyorduk . Sonrasında Tatko dan hizmet almaya devam ettikleri ilettiler. Yenileme ihtiyacı oluştuğunda bizlerden de teklif tale edecekler . Yeni lastik alımıda yapan firma ya Yokomoha lastikleri konusunda bilgi verildi. Bridgetone veya Michelin alımı yapılan işletmede talep oluştuğunda Yokohomayıda alternatif olarak değerlendirecekler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('87e56fed-3fad-5d0f-9328-6275e915961d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARDEŞLER LASTİK' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'a7637ec7-b8be-59d8-a291-62869d6d9cbc'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-22','NESİM GKHAN','Bilecik merkezde bulunan Kardeşlerlastik kamyon ve otomobil ağırlıklı çalışıyorlar. Yol yardım araçları ile bölgeye hizmet veriyorlar. Yenlilemeyi uzun zamandır Dirpaya yaptırdıklarını fakat yaşanan sorunlar sebebi ile kaplama yaptırmadıklarını yeni veya tamir işini yapıyorlar.Belli dönemdiraz stok tuttuyorlar.  Acil ihtiyaçları olduğunda bölgeden temin ediyolar.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0816a8a4-6a4d-5529-abe3-0d16e9c94b5b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İŞPAR LASTİK' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'4ecadf53-56ca-5133-8858-a407878a6b9a'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-22','KAAN YÜKSEL','Bilecik merkez sanayide continental bayiliği bulunan firmanın Bozüyüdede yerleri mevcut .Yıllık 600 adet civarında Kamoyon lastiği ağırlıklı olarak binek sattıkları bilgisi alındı. Binek lastikde continental bayiliği olmasına karşın fiyatı uygun lastik satış adetlerinin daha fazla olduğunu bölgenin ilçe ve köylerine hizmet verdiklerini bu sayede adetlerini arttırdıklarını belirttiler . Kamyon lastik ihtiyaçlarında irtibatta olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a9089b31-8147-54f9-8b12-8bbc8032bd20','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ANKAS - AKMERTAŞ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'c253435d-3260-5735-80aa-25c7afdc8498'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-22','İBRAHİM BABAEKLİ','Bursa Kemalpaşa bölgesinde Eski müşterimden İbrahim Babekli  geçmiş dönemde satışını yaptığımız ve memnun oldukları Maxam 29.525 ebattan  2 adet teklif talep ettiler. Bursa Ocaklarında hafriyat temizliği yaptıklarını taşlarının bir proje için gündemde olduğunu ve anlaşılması durumunda Loderin 2 adet ön lastiğini yenilemeden üretime giremeyeceklerini belirttiler. Teklifimiz takip edilecek.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bca9b015-5fc8-599c-a11a-e880732a1db2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FEDERAL MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5aef9238-6308-5cb6-9856-94a5aacf7cc9'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-22','SELÇUK ÇOKAL','Ferdel mermer Ocak yetkilisi Selçuk bey 6 kişiye düşdükleri  Ocak da çalışan işçileri çıkadıklarını ve 1 operatör ve kendisinin ocakda kaldığını Occağın kapısının açık ama üreti durdurmuşlar. Bilecik Bölgesinde de Lastikçilerin işleri çok durgun , bölgenin lokomotifi Mermerin bitme noktasına gelmesi ile birlikte potansiyeli düşük olan bölge ye zaman ayırmak faydalı olmyacaktır.Böleden talep oluşmadan ziyaret planı yapmayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a8fd9f43-9c34-545d-a86f-7257a386554c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FATİH OTO LASTİK KASIM ÇANAK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e90b43f1-ba20-57f0-b62c-689d0102acae'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-23','KASIM ÇANAK','Kütahya merkezde Kamyon lastiği ağırlıklı çalışan Kasım bey e Continental kampanyadan 16 adet  satışımız olmuşu. 90 gün anlaşılan çek tahsilatı yapıldı. Stokalarını alım yapmadan bir süre eritmek istiyor. Sonraki alımı Kumho markadan 3315/70 ve dorse olarak yapmak istdiğini belirtti.Petlas ve Ling Longdan bir hayli yüklü alımlar yapmış. Bu iki marka haricindeki markaları 4-8-12 adetler şeklinde stoklarına aldıkalrını belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('99edd162-8702-5cbb-8790-125d19a0d3b5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SE-BA LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'618790e1-8a2b-5587-b15e-8d507ab26ddf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-23','SERKAN BAŞAR','Serkan bey Ünaldı maden için son alınan 4 adet 26.5R25 lastiklerin biraz geciktiğini Üretim bitince gönderilecek lastiklerin yerine alınması gereken lastiklerin durumunun iyi olmadığını ilettiler. Üretim den Emre Soğukoğlu ile yaptığım görüşmede geçen hafta arıza durumu olduğu için gecikmelerin olduğunu belirttiler.Onun haricinde 4 adet daha 26.5R25 Kütahya bölgesinde sökeceğini onlarıda Beşçam Ünaldı madenin şantiyesine bize kolaylık olması amaçlı bırakacağını iletti. SE BA lastik bölgeden topladığı tüm iş makina lastiklerini tek noktada toplayarak işin hızlanması amçlı bize destek veriyor.. Bu aralar biraz üretim ve sevkiyat hızımızın düşük olduğunu bu konuda hızın arttırlması talebi geldi.. İşin daha başlangıç olması ilk işlemlerin bayram ve arızlara denk gelmesinden kaynaklandığını , potansiyel arttıkça iyileştirmeleri devreye alacağımızı ilettim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c9277af9-e490-5306-a3aa-9af8f34c343b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAVA ORMAN ÜRÜNLERİ' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'d22522e4-8838-5e58-9f65-2eb6c566380b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-23','ONUR BEY','Tava Orman ürünlerine geçen hafta sizden özel iskonto alarak verdiğim 20 adet Dorse 10 adet çeker teklifimizin son durumunu öğrenmek için yaptığım ziyarette. Satın alma işlemini tamamladıklarını fiyat avantajı olması sebebi ile Hankook marka tercih etikerini ilettiler.Bs Treyler için 39 isonto Lassa için 35 iskonto vermiştik.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e3295785-a329-598a-885b-b48efa24b7d1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UĞUR MERMER' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'013bdee0-8031-5f6e-924a-2a65c8cedf6c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-23','İBRAHİM UĞUR','Uğur mermer Genel müdürü İbrahim bey Geçn hafta katıldıkları Afyon mermer fuarından tam beklentilerni alamasalarda çok da kötü geçmediğini belirtti. Fuarın org. Sağlayan firmaalar arasıda olması sebebi ile olumsuz konuşmak istediğini gözlemledim. Bölgede çalışan nadir mermer ocaklarından .Geçmiş dönemde makina sektöründe ticaretimiz olmuştu. Satın alma işlemlerini Afyon fabrikasında bulunan Ali bayram beyin yönettiğini kendisininde İş makinası ve kamyon ihtiyaçlarında bizlerden de fiyat alması için yönlendireceğini belirtti. Afyon ziyaretimde benimde uğrayarak tanışmamı istedi. Haftaya yapacağım Afyon programına dahil edildi. Afyon esnafının uzun yıllardır ticaret yapış şekli etrafdaki komşuları tarafından Kütahya ve Eskişehirden eleştirililir. Talep ettikleri vade ve indirimlerdeki aşırı iskontı ısrarlarından dolayı mesafeli duruşlar sergilenir. Uğur mermer gibi belli kalite firmalarda bulunduğu için onları içlerinden ayırarak Afyon bölgesinide tarayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ae33cd46-1528-585e-a587-0e7a11bad2d3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KURT NAK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'c70dc55d-28be-56a3-a2b2-616671c9aa97'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-23','MUHARREM KURT','Kurtnak firması Kütahya merkezli 40 adet aracı olan  Düzce camın nakliye işini yapan firma ile bir önceki ziyaretimizde tanışmıştık. İlk ziyaret sonrasında talep ettikleri teklif Firma sahibi Muharrem beye iletilmişti. Teklifi gördüklerini alım aşamasında bizleride arayacaklarını ilettiler. Firmanın yakından takibinin ve ziyaret sıklığının bu firmada olumlu sonuçlar vereceğinden eminim .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8dfa9c6d-d262-5d2c-8436-75320aa5e86e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'87f63dd0-0f29-589c-9ec4-645ac9f7e9f1'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-23',NULL,'Kütahya sanayisinde Mutaş madenin Ödeme sıkıntısı ile ilgili aldığım duyum üzerine Kemal beyi aradım . Durumu anlattım. Kemal bey gerekl, tedbirleri alacak .Son dönemdeki Küçük tamir işleminde  bizde  tahsilatı gecikmeli olarak almışız. Nakit akışlarının büyük kısmını sağlayan Kümaş taşerönlüğünün bitmesi ve satılığa çıkardıkları makinaların istedikleri fiyat ve hızda satışını olmaması ekonomik yapılarını etkilediğini  düşünüyorum. Buradaki talepleri sıkı tutmak faydalı olacaktır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('33c8123f-68cb-5dff-bd54-d60ffe29d11a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYKA MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'116c00e3-4b44-5df6-8a40-6e899448edbd'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-24','MEHMET BİLEN','Mehmet bey Kütahya tavşanlıda buunan Kömür madenlerini bayramdan sonra açtıklarını çok sipariş olmasda genelde her yıl yıl sonuna kadar olan çalışmayı Eylül sonu gibi bitirmeyi planlıyorlar. Benim ara verdiğim dönemde beni aradığını ve ulaşamadığını iletti. Tesisinde 3 adet loder bulunan firmanın  lastiklerini  2024 yılı sonlarında yenilemeye almıştım. Lastiklerin üzerinde yaprak şeklinde soyulma ve kalkmalar olduğunu ilettiler.  Konuyu iletmek için bana ulaşamadığı için deplarına kaldırmışlar ve bizlerden birileri geldiğinde gösteririz şeklinde düşünmüşler.Lastiklere ait görüntüleri aldım. Üretim ile konuyu görüşeceğim. Bölgede kömür üreticileri bir hayli potansiyel kaybetmi durumda . Firma sahibi Mehmet bilen ihtiyacı olan kamyon lastik ebatlarını iletti. Sons atışımızı 2024 yılında lassa olarak yapmıştık 13R22.5 ve 315/80 ebatları için maden lastiklerini Kumho hubtrac ve Sizden aldığım fiyat ile Lassa olarak ilettm. 12 adet 13R 8adet 315 /80 ihtiyaçları olacağını verdiğimiz fiyatları inceleyerek ve araştrırarak geri dönüş yapacağını iletti. Mehmet bey ile birlikte sahada kamyon ve İş makinası lastikleri gezerek durumlarını kontrol ettik. Bu sebeple günün ayrısını Ayka madende kullanmış olduk .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d8158e71-bf6e-56ea-a2c3-df99857f5d44','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HAZ BETON' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'09c3b851-4d67-5cf3-8634-b3b8b80231a7'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-24','RAMAZAN YENİTEPE','Kütahya Haz beton firmasında 15 adet mikser 10 adet damperli agraga kamyonu bulunduğu bilgisini aldım. Son iki lastik alımında Kelly markasını tercih etmişler. İlk alım da fiyat performansdan memnun kaldıkları için İkinci alımdada tercih etmiler. Kelly markasını İzmir merkezli bir firmadan almışlar. Kumhoyu daha önce kullandıklarını sorun olarak her hangi bir sorun hatırlamadıklarını ilettiler. Yapılacak lastik alımında bizlerden de teklif alınması yönünde anlaştk. Kamyon yenilemeyi Ovakent ile uzun bir süredir çalıştıklarını 4.200 + kdv yenilemefiyatlarının olduğunu belirttiler. Bizim yenileme kabiliyetmiz  konusunda bilgileri Ramazan beye ilettim.Şu an için memnuniyetsizlik bulunmaması sebebi ile yeni lastik konusunda irtibatta olamak istediklerni ilettir.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c923c803-1b4c-5d75-8d66-7327596b2756','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALKERSAN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'dd3e6d0a-6363-5a7b-acb5-9f503ab4b53b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-24','METİN TOPUZ','Kalkersan firması Kütahya Ahmetoğlu bölgesinde Beton santrali ve Kalker üretmin yapmaktalar Firma bünyesinde 6 mikser 3 tırları mevcut. Oluşumlarının hızla devam ettiğini siparişde bulunan araçlar olduğunu belirttiler. Kütahya mekezli fimanın bölgede olumlu bir referansı mevut. Yeni aldıkları araçlar prelli lastikler ile gelmiş. Metin beyle ihtiyaç olduğunda haberleşmek üzere  anlaştık. Kullandıkları 315/80  ve 385/65 lastik alımlarında alternatif markalı olarak teklif iletilmesini istediler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1c2780ec-6894-5898-bbed-1cf0bb9d92e6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKDENİZ MİNERALLERİ' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'21103c78-5ed7-5f53-8abb-f01160a93ed6'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-24','VEDAT BAYRAK','Akdeniz Minerallerinin Müdürü Vedat beyi eski dönemden de tanışıklığımız mevut. Vedat bey Bölge magnesit firmaları içerisinde potansiyelien çok düşen firma olduklarıı belirtti. Bunun Kalsine- sinter - fused çeşitleri olan magnesit madenin ocaklarda sadece sinter çeşidinin çıktığını . Bölgedeki diğer ocakalarda 3 çeşidininde çıktığı için daha geniş pazara hitap edebildiklerini elirttiler. Ziyaretlerimde onalarında potansiyenilinin azaldığı bildirmem üzerine kendilerindeki kaybın %80 oranlarına çıktığını rakip üreticilerde yarı yarıya olduğunu belirttiler.Vedat bey Akdeniz minerallerinin yakın dönemde %100 yunan sermayesine geçtiğini belirttiler. Bu sebele bu düşüşe rağmen çalışmaya devam etmelerinin sebebi nin yurtdışı gücü olduğunu belirttiler.Yerli sermaye ile kalsalardı yüksek ihtimal kapatılacaktı yorumu yapıldı. Bu yıl ilk defa taşerön firma çalıştırmadan kendi imkanları ile sezonu bitireceklerini bu sbeeple öz malları çalışacağı için lastik ihtiyaçlarının olabileceğini ilettiler. İhtiyaç olduğunda ilişkimiz icabı tedariğin bzizim tarafdan karılanacağına eminim','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4bb72801-6209-5412-ba77-8c6851f26c97','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SELKA BETON' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'0b4896da-4676-5a66-9692-e43d0e5d02f2'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-25','SERDAR KAYA','Serdar bey beton satışları miktar olarak kısmen beklendtilerini karşılasada rekabetten dolayı kazanç anlamında durumun iyi olmadığını belirtitiler. Araçlarının öenmli bir bölümünü yenilemeleri ve eskisi ne oranla stokla çalışmadıkları için lastik alım aralıklarının bu dönem uzadığını belirttiler . Yeni araçların altında Prelli marka gelmiş. Son zamandalarda ziyaret sıklığını arttırdığım Selka betonda eski tanışıklığımızında olması sebebi ie ilk alımda bizlerden de fiyat alma ve akla gelme durumunun sağlandığını düşünüyorum .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('33d27d16-641d-5704-8c3c-498f9e17c291','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ECAN NAKLİYAT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'a123325e-61e6-52f8-96aa-4b4060a57087'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-25','GÖKTUĞ CAN','Eskişehir Ecan nakliyat Eskişehir Köklüce makinanın ürünlerini Fransa ve Almanya ya taşıyor. İşlerinin %80 nini nu org. oluşturuyor. 45 adetlik tır filosu mevcut . Göktuğ bey firma sahibi Ekrem beyin oğlu bakım ve lastik konuları ile ilgileniyor. İlk ziyaretimiz sonrasında lastik alımı olmadığını yakın zamanda alım planladıklarını ilettiler. Alım aşamasında bizdelerden de muhakak tekif alacaklarını ilettiler. Alternatif markalı teklif almak istiyorlar. Geçmiş dönemde Bridgestone Continental ağırlıklı tercih yaptıklarını fakar son zamanda farklı markaları denediklerini en son yaptıkları alımı Ling long tecih ettiklerini belirttiler. Firmanın yurtdışı ağırlıklı işleri olması sebebi ile işlerinin beklentilerini karşıladığını belirttiler. Eskişehşir bölgesinde öncelikli kazanılması gereken firmlar arasındadır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ec2e05ee-602a-5a83-8689-f37c5acdf912','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜMÜŞLÜ LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'6ea39814-252c-52bc-8623-64687bd3bff5'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-25','ÜMİT GÜMÜŞLÜ','Gümüşlü lastik Org. Sanayi bölgesinde açtığı şubesini ziyaret ettim. Büyük araç org. Yakın olmak amaçlı bu maliyete giriştikleri fakat istedikleri bulamadıklarını yakın gelecekdede Çok istedikleri gibi olmayacağını belirttiler. Selka beton u örnek göstererek Uzun yıllardır işçilikli hizmert verdiklerini yolda kalan mikserlerine baktıklarını son dönemde yolda kalan tüm araçları için alt kalite yeni dahi lastik istemediklerini kendisindençıkma lastik bulmasını talep ettiklerini belirtti. Gümüşlü latik aynı zamanda Irakdan aracılar ile getrdiği Wellplus markasını Kdv dahil 8.000 tl ye getirdiğini 10.500 - 11.000 TL  bandında Eskişehir piyasasına sattığını belirtti. Artık 15.000 -16.000 TL bandındaki Ling Long ve benzeri lastiklerinde piyasada satışının zorlanmaya başladığını düşünüyor. Nakliyeciler en Wellplus markasının fiyat avantajından dolayı rağbet gördüğünü belirtiyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1b4b2813-34e5-5b62-875b-57f1b8f7ac48','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ZAGUTOĞLU İNŞAAT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8c67c0f8-d04c-5bd4-97bc-bfe953bdae47'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-25','BURAK ATICI','Burak bey Eskişehirde İnşaat ve Hafriyat alanında hizmet veiyorlar. Geçmiş dönemde Lassa Bridgestone grubu satışlarımız olmuştu. Firma bünyesinde 6 adet kamyon grubu 3 adet de lastik tekerlekli iş makiansı mevcut. Brisa grubu lastşklerinde fiyatlarının yüksek olduğunu düşünüyorlar.  Kumho ve Hubtrac markaların bilgileri ve fiyatları konusunda bilgileri ilettim. Geçmiş dönemde olduğu gibi stok alarak çalışmadıklarını  acil ihtiyaç ,soruni,  arıza olduğunda tedarik yoluna gittiklerini belirtiyorla. Geçmiş ilişkiden dolayı acil olmayan ihtiyaç oluşması durumunda irtibatta olacağız','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('03265c52-29ee-59b6-aebe-fe723188321b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATG LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ce6c8f09-e0a2-594e-917e-042be990ed69'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-25','MEMET GÜLLÜ','Atg lastik B2B portalından Teklif almasına üzerine yapılan ziyarette . Portala bakmadan önce aynı lastiği bana direk sormuştu ben Liste peşin fiyatından 15.000 TL olarak vermiştim .  315/80 D 21  Hubtrac maden ve  lastiğin portal da 14.500 TL olduğunu belirtti. Sebebini net bilmediğim konu için tahmini şu şekilde söyledim.  Şirketimizde portal yöneticilerinin zaman zaman kısa dönemler için stok durumuna göre fiyat düzenlemesi yaptığını , müşterininde tüm ürünler için portala bakmasının avantajlı satın almalar için  faydalı olacağını ilettim. Maden tipi için teklif verdiğini sonuçlanması durumunda portaldan sipariş girişi yapacağını belirtti. Stoklarımızda olan diğer güncel ürün grupları hakkında bilgileri ilettim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a499ff5e-6a3d-506e-aa17-a1d6a4eefc62','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UĞUR MERMER' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'23581018-82ec-5d40-89e6-e5c87d644ae1'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-26','ALİ BAYRAM','Afyon bölge ziyaretimin en önemli sebeplerinde birisi Uğur mermerdi Uğur mermer Gerçekten zor durumda olan mermer sektöründe işi oldukça iyi olan nadir firmalrdan bir tanesi. Ocak ziyaretimde yönledirilen Ali beyden randevu alarak Afyon programı yaptım. Firma bünyesinde 8 adet loder 3 adet kaya kamyonu 8 adette kamyon ve tırları mevcut. Bu ekipmanalr bu günlerde oldukça yoğun çalışmakta. Yoğunluğun en önemli sebebi Siyah tabir ettikleri özel bir taş ve bu taşın Amerikada oldukça önemli bir proje inşaatında kullanılıyor olması. Firma Sahibi ibrahim Uğur bey ile Makinacılık dönmeminden tanışıyoruz. Geçmiş ten ve sektörden bilgi alışverişi bir hayli zaman aldı. Ama lastik konusunda önümüzüde açmış oldu. Yeni ve yenileme konsunda Satın alma yetkilisi Yeğeni Ali bayram beye tüm ihtiyaçlarda bizden teklif alınması ve çalışılması konusunda bilgileri iletti. Afyonda Önemli+H4 müşteriler  den olan Uğur mermer irtibatını ve ilişkiyi sıkı tutacağım .En son 3 ay önce 29.5R25 Bridgestone olarak Orbitalden  aldıklarını İş makinasında Bridgestone tercih ettiklerini ilettiler. Yokohoma konusunda da bilgileri ilettim. İş makinesinde primium marka tercih ettiklerini Kamyon grubunda orta kalite alımı yaptıklerını belirttiler.Uğur mermer de bölgenin düzgün ticari yapıya sahip firmalarındandır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0789060e-4263-5153-8ded-d54e21e97ebd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YÜKSEL MERMER' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'c6a9f719-6de5-5050-9599-56b6779de966'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-26','YÜKSEL AŞKIN','Yüksel mermer Bilecikde Ocağı bulunan İsçehisar merkezli firma . Firma bilecik ocağında 2  adet loder 1 adet kaya kamyonu ve 2 adette tırları mevcut. Yüksel bey İşlerinin sakin olduğunu belirtiyor. Ocakalrında üretimin rütun olarak fabrika  besleyecek kadar çalışıyorlar.Eski dönemden de iyi diyaloğumuz olan firma ile ihitiyaç olması durumunda irtibatta olacağız. Afyon müşteri yapısında vade ve fiyat konusunda anlaşmakda geçmiş dönemdede en zorlandığımız müşteri gruplarındandı . Yüksel mermer gibi nadir firmalar o yapıdan uzak firmalar dı.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bf906241-8a78-531f-a60a-5cdd49b0caaa','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİNOPLU KARDEŞLER' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'c68db477-73b8-543d-b33a-87cbd1dc28e2'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-26','FİKRET ÇOBANGİL','Sinoplu kardeşler Afyon İsçehisarda fabrikası Eskişehir Sivrihisarda ocağı bulunan mermer işletmesi . Ocakalrında  işleri oldukça sakinleştirdikleri 3 kişi kalan ocakda stokdan sadece fabrikayı beslediklerini belirttiler.  2025 yılını arayacakalrını hiç düşünmediklerini fakat o yıla razı bir potansiyellerinin olduğunu belittiler. Firma Bünyesinde 3 loder 1 kaya kamyonu ve 4 adet kamyonları mevcut . 25.000 kişi nüfusu olan ilçede 650 mermer firma ve fabrikası mevcut. Her fabrikada 20 kişi çalışsa 13.000 kişi ye tekabul ediyor. Doğaltaşın yurtdışı satışının kesilmesi ve tekrar eski potansiyele ulaşması zor olduğu için belirtilen firma sayısının her geçen gün azalması da doğal olacağı düşünülüyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ed9de65b-3f3c-5ab6-9c66-75032a2f6bf3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÖKEN ROT BALANS' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'a63eb5a3-3d9c-5d17-baf8-0839ac84dedf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-26','CEYLAN KÖKEN','Ceylan köken Afyon sanayisinde Goodyear beyiliğ yapıyor. Bölgede Kamyon İş makinası hizmet   leri mevcut Afyon bölgesinde mermer sektörü ciddi anlamda kankaybetmesi sonucunda üreticiler, nakliyeciler ve bölge tedarikçilerini zincirleme olarak etkilemiş durumda. Ceylan beyde işlerin potansiyelinin ekonomik koşullar haricinde mermer sektörününde etkisinin olduğunu belirtiyor. Bölge Tarım hayvancılık ve Termal turizm gelirine kalmış durumda . Afyonda Doğaltaş madencliği ilin lokomotiv sektörü durumundaydı. Bölge Ankara ve güney bölgeyi bağlayan yoğun trafik  güzergahda bulunması yol üzerinde bulunması lastik sektörünüde beslemekte. Sanayisi Kütahya sanayisineden  daha büyük fakat Ticari lastik firmaları Kütahyada Kömür magnesit den dolayı daha fazla sayıda. Ceylan bey firmamızı tanıdığıı belirtti. Ürün ve hizmetlerimiz konusunda güncel bilgiler paylaşıldı.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f15390a2-edad-5d19-bc79-81b952cc5e98','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AFYON ROT BALANS' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'cb2bea0e-80d1-5076-8aa4-5581ce1d6b1c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-26','BEYTULLAH KÖKEN','Afyon rot balans firması Bölge petlas bayisi beytullah bey geçen yılki potansiyeli koruduklarını belirtiyor. Petlas markasının diğer markalara göre piyasada  daha kolay satılır duruma geldiğini belirtiyor. Ürünlerimiz içerisinde Kumho marka konusuna irtibatta olabileceğimizi Geçmiş dönmede bu markayı sattıklarını ve fiyat uygunluğu olmasında durumunda çalışabileceğimizi belittiler Diğer Yeni ve yenileme ürün grupları konusunda bilgileri iletildi.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('23784e07-bf77-5c40-941f-f91b5a24dc1a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇINARLAR MADEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'d047587d-44c2-505d-8dd7-6c2914ed0a74'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-01','MEHMET ÇIANR','Çınarlar maden bölgede bulunan Yurtbay Termal Söğüt sermaik Eczacıbaşı gibi firmalara sermakik ham maddesi sağlıyor Firma bünyesinde lastikli olarak 4 adet loder 10 adet kamyon mevcut. Bölgedeki seramik fabrikalarında işlerin sakinlemesi sebebi ile bu yılın ilk 6 ayında ciroların 1/3 oranında düştüğü ve doğru orantılı olarak ekibide küçültüklerini belirttilerç Geçmiş dnemde Brisa kamyon hafriyat  grubunda satılarımız olmuştu. İşlerin düşmsi ile birlikte stok olarak lastik almadıklarını stoklarda olanların dahi henüz bitmediğini belirttiler. Sanayi üretimi 2026 yılında %0,8 madencilik ve taşocakcılığı  %2,8 yaklaşık 3 kat oranıda daralmasının etkilerini tüm madencilik sektörü hissediyor.Toplu yeni lastik ihtiyaçlarının uzun bir süre olmayacağı görüşündelr , İş makinası Kamyon yenileme ihtiyaçlarında irtibatta olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('60c67d7a-7fa0-5544-886c-672bcdcad282','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÜPELİLER BETON' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'d54792c0-6f00-5174-9744-d9c52c5668b3'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-01','ERHAN NAİL KARAKAYA','Eskişehir Beton üretimi yapan firmanın Satın alma sorumlusu Erhan bey maliletlerden dolayı ucuz markalara yönelimin arttığını belirtiyor. Son aldıkları 2 adet 23.5R25 İş makinası lastiğinide Petlas PTX RD 31 modelini tercih etmişler.Petlas markası dışında satış yapan hiç bir firmadan teklif almamışlar .Onuda Eskişehir Petlas bayilerinin verdiği fiyatın daha altında Ankaradan aldıklarını ilettiler. Fiyat ve firma konusunda bilgi vermek istemedi.  Maliyetler ve Beton sektöründe Eskişehir de oluşan ciddi fiyat rekabettinden dolayı tüm satın alamların  onaylarlarınında şirket içerisinde çok detaylandırıldığını belirtiyor. Mikser ve Beton pompaları üzride yaptığım incelemede de kamyon grubunda da  Petlas ağrılığı mevcut.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('94aac79d-015d-53aa-846e-992f31026f28','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINAYLAR' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'86666a06-8401-523a-91e0-8f4af7e28851'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-01','VEDAT ARDAL','Eskişehir Gündüzler köyünde yapı kimyasalları üreten firma Yetkilisi Vedat bey geçmiş dönemde ticaretimiz olmuştıu. Frma bünyesinde 3 adet loder 6 adet 315/80  385/65 ebatlarını ağırklıklı kullanan araçları mevcut. Yaklaşık 8 çeşit yapı kimyasalı ürettiklerini ve yurtdışı talebide bulunduğu için işlerini nin iç piyasaya göre bir miktar daha iyi olduğunu belirttiler. Geçmiş dönemde satınalmalar şantiyeden yapılıyordu. Fakat Eskişehir org. san. bölgesine merkez bina yaptıklarını ve satın alamaların artık merkezden yapıldığı bilgisini aldım Osb ziyaret programına aldım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('228ca32f-c50d-5b46-a4cb-47528e414742','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİROLLAR MEREDES SERİVİSİ' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'aafb0c6a-8f10-5b29-957a-8e6bf8a059e8'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-01','ADNAN ÖZTÜRK','Eskişehir Birollar mersedes yetkilisi Adnan bey ile görüşmemizde ticari lastik lastiğe girmediklerini binek lastik de motor , model ve üretim yılına göre  Michelin, Continental, Bridgestone ve Goodyear olarak değişkenlik gösterdiğini belirttiler. Yurtiçi nakliye pazarı En ucuz kim nakliye fiyatı verilmesinden daha çok aracı kim teknolojiyi kullanarak boş döndürmüyor konusuna odaklanmış . Bu konuyu sağlıklı kurgulayan fiirmalar için fırsat dönemi olacağı düşünülüyor.  Ağır ticari araç pazarı 2026 yılının ilk çeğreğinde  %8 daralmış ikinci çeyrekle bu rakamın artacağı düşünülüyor. Mersedes bayi  olarak Binek grubunun satış ve servis rakamlarında sorun olmadığı sorunun ticari tarafta olduğu belirtiliyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9468325c-8eec-5aa8-8fc1-5ced8d7c4600','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAPI YAPI' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'e5fbd3af-ffab-5b46-b0b6-bc7022254836'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-01','VEYSEL BEY','Yapı Yapı firması Söğüt gübretaş madenciliğin taşerönlüğünü yapmakta. Geçmiş dönemde Yapı Yapı ya Yılmazlar lastik aracılığı ie yenileme hizmetini organize etmiştim. Güncel durumda firmanın lastik işlerini organize eden Veysel beyin irtibat bilgisine şantiyeden ulaştım. İsg denetimleri olduğu için tekra randuvulaşacağız. Potansiyeli oldukça yüksek müşteri ama Bu tür anlaşmaları eski bilgilerime  göre merkezlerinden yaptıklarını düşünüyorum. Şantiyeden başlayarak kademe kademe işimiz için doğru iletişim kanalına ulaşacağım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ca954858-e3d7-5093-b278-d69b5d764003','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKKUŞAĞI MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'d226a3a8-2749-5355-889b-5ee681213199'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-02','İSMAİL HAKKI ÖZTÜRK','Bu gün yapılan ziyaretimde işinin iyi olduğunu belirten tek firma konumunda Firma Kütahya beşçam mevkiinde bulunan ocağından Bölge TCDD tesisilerine ve Kalyonun Bursa da yürüttüğü Hızlı tren projesine bazalt temin ettiklerini belirttiler. Firmanın piyasada günlük  rekabete dayalı bir üretimi yok. Kalyon ve TCDD den ile yaptığı sözleşme gereği ödeme ve iş kapasitesi aylık olarak net bir şekilde çalışmaktalar. Fakat konu Bizim lastikle ilgili konuya geldiğinde işlerimiz iyi diye başlayan firma sahibi Petlas kullandıklarını Ankara Yaşar Otodan en son 100 adet aldıklarını 60 adet araçları için yaklaşık 200 adet lastik stoğu ile çalıştıklarını ilettiler. Petlas dan 315/70 ebatını 14.000 tl den aldıklarını Tüm petlas marka alımlarını 14.000 -15.000 TL arasında olduğunu belirtiyorlar. Petlas ın piyasaya ilk girdiğinde işleri sıkıntı olan olan , kalite sorun değil ucuz olsun şu günleri geçirelim diye düşünülen olgudan çıkarak işleri  potansiyel ve karlılık olarak  sorunsuz olan firmalarında tercihi olması dikkat çekmekte .Kamyon Yenilemeyi Bursa Doruklar kaplamaya yaptırdıklarını . Bursa Kalyona çalışan araçlardan sorun olduğunda Bursa bölgede tüm lastik sorunlarının çözülmesinede yardımcı oldukları için tercih ettiklerini belirttiler. .  Doruklar Bursa  ve bölgede Dirpanın tamamen önüne geçmiş durumda . Dirpa ile çalışan firmaların oldukça azaldığını gözlemliyorum. Önümizdeki hafta Dirpa dan alacağınız ziyaret de bu piyasa tahmini ile ilişkili bir durum olabileceğini düşünüyorum . .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c665ac10-461c-5ed2-9235-ff01fd9683b4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALKERSAN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'dd3e6d0a-6363-5a7b-acb5-9f503ab4b53b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-02','METİN TOPUZ','Kalkersan firmasında göreve başlayan Metin bey Mutaş madencilik den Kalkersana geçiş yapmış. Kalkersan bölgede Asfalt üretimi yapan tesisilere hammadde sağlamak ile birlikte hazır beton üretimi de yapmaktalar. Firma büyesinde tır, mikser ,Kamyon olarak 13 araç , Lastikli olarak 2 adet iş makinesi mevcut. Firma Kütahya bölgesinde bilinen bir firma. Metin bey ile Mutaş döneminden tanıışıklığımızın olması lastik ihtiyaölarında bizlerinde rekabet içerisinde olmasını sağlayacak.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a1575923-16ae-52f7-be64-9e81a2a16d5d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYKA MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'116c00e3-4b44-5df6-8a40-6e899448edbd'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-02','MEHMET BİLEN','Ayka madenciliğe geçen hafta 12 adet Hafriyat tipi Kumho ve Lassa Çeker teklifi iletmiştim. Teklifi henüz değerlendirmemişler. Ocağın üretime başlayalı 2 hafta olması Şeker fabrikalarından beklenen kömür ihalesi sonuçlarının beklendiğini oradan gelecek bilgiler. Bu yılki üretim kapasitelerini belirleyeceğini Tedariklerininde bu sonucun belirleyeceğini belirtiyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('43f35267-7eab-58aa-ac3d-bcf5f0d2a5e1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZASİL MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'35c8c374-965e-5db0-8972-2e7abc16767f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-02',NULL,'Kütahya Tunçbilek bölgesinin en büyük maden irmalarından olan Özasil maden şantiyesini kapatmış durumda. Şantiyede sadece güvenlik ekibi mevcut. Kömür sektörü her geçen yıl önemli ölçüde küçülüyor. Yaygınlaşan doğalgaz ve diğer enerji kaynakları kömürün pontansiyeline her geçen gün etki ediyor. Eski köklü firmalar Özasil , Kayasu, Özerdemler, Tarhan, Özdoğanlar, Özeser hepsi sektörden çıkmışlar. Yerlerine gelen Ege taş ,Bia maden gibi daha küçük ölçekli firmalar kalan potansiyeli yönetmeye çalışıyorlar.Onlarında bölgede tedairkçiler tarafından referansları çok parlak değil. Tunbilek maden bölgesine Ünaldı ,Yılmazlar, Ayka maden dışında Bölge ye ziyaret planlaya gerek olmadığı net olarak görülmüştür.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('411cc954-2fac-5581-97a5-52e0884ee9a1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e6c4c63a-1a2c-5a2e-9e1e-6399d789e3a0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-02','MEHMET ÜNALDI','Ünaldı Maden Techto firmasından adığı Kümaş magnezit işletmesi taşerönlüğünde sorun olduğu duyumu üzerine firmaya yapmış olduğum ziyarette ay başına tekabül etmesi üzerine Techtodan iyaptıkları istihkak üzeriede çalışıyorlardı. Bir sorun olduğuna dair bir zlenim almadım. Eski taşerön Mutaş maden Techto Kümaş taşerönlüğünden çıkmak istediği yönünde bilgiyi piyasayla paylaştığı bilgisi bölge tedarikçilerinden de duydum. Bizim işimiz gereği muhattabımız Ünaldı maden bölgede kaliteli ticari görünüme sahip. İşi alan ana firmalarında ki problemin olup olmadığını yakın zamanda öğrenmiş olurum .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('38f1a2f8-00c5-5cf0-a74d-fea364a2aa1a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FATİH OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'7fedcc35-c33f-5763-8a22-20b9e67a0a60'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2027-07-02','KASIM ÇANAK','Continental kampanyasında 16 adet satışımız olan Fatih oto lastik Kaım bey İşlerin hızlanmasını beklerken bu haftanın sakin geçtiğii iletti. Yol yardımlarla bir şeyler yaptıklarını belirtiyorlar.Son dönemde bölgede Lin long ve Petlas ı daha çok sattıkarını bu markalarında alımlarını yüksek adetlerde yapıyorlar ve stoklarda o şekilde tutuyorlarmış. Primeium grubunu yok dememek için 4-8 şeklined stokladıklarını belirtiyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dc803f1d-9717-5a6f-8d98-21ce8a4524d0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DURAK ŞAHİN LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'29d14c18-98b4-5a6e-ac3e-c6d4274834d8'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-30','VOLKAN AY','Eskişehirde lassa bridgestone ağırlıklı çalışan  Volkan bey Brisa ürünlerini uzun zamandır Günmarlas ile çalıştıklarını fakat son 6 aydır.Brisa ürünü satmakdıklarını belirtti. Piyasadan uygun şartlar ile temin ettikleri markaları peşin olarak uygun fiyattan alıp satmak şeklinde ilerliyor. Brisa grubunda Eskişehir bayisi Özkan otomotivin  bölgede Brisa grubu ürünleinde çok enterasan düşük fiyatlar verdiğini bunun sebebinin de ellerinde Tarihi geçmiş TBR grubu lastiğin arttığını düşünüyorlar. Özkan otomotiv Eskişehir merkeze uzak olan Teksan sanayii bölgesindeki yerleri  haricinde binek grubu hareketlendirmek için şehir merkezinde uygun yer baktığı ve bineğe yatırımı arttırma durumunda olduğu bilgisi alındı. Eskişehirde ellerinde yüksek stok bulunan Aksoy Oto - Yks -lastik - Demirgöz ve Brisa bayisi Özkan otomotiv in TBR grubunda fiyat rekabeti bir hayi artmış durumda. Durak şahin kendilerininde bu rekabetten çok etkileniğini ve hayatta kalmak için uygun lastik marka ve fiyatlara ulaşarak çarkı dönüdrmeye çalıştıklarını belirtiyor. Bu rekabet şehirde bir süre ticari grupda  sektörün karlılığını  etkileyeceğini düşünüyorum .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c089cf9e-0b13-5341-a941-a1f4e97bada1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OREKS MADEN' AND il IS NOT DISTINCT FROM 'ÇANAKKALE' LIMIT 1),'031427bc-c408-5b3d-9183-580159db8782'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-30','MAHİR KÖKSAL','Oreks maden Yenicede Çinko ve kurşun madeni üretimi yapmakta. Sektör diğer madenlere göre daha dengeli ve stabil üretimleri piyasaya bağlı küçüleye ihtiyaç duymadan ihracat üretimine devam ediyorlar. Mahir beye 8 adet 20.5R25 Bridgestone  İş makinası Lastiği ile birlikte ilettiğim 10 adet 385/65R22.5 310T treyler  lastik teklifinden 10 adet treyler lastiğinin bizde kaldığını .İş makinası lastiği için Ucuz marka olarak aldıklarını ilettiler. Bizde kalan lastiklerin siparişi girildi sevk işlemi yaptırılacak .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1192faeb-51da-5a7f-9d6d-be016ac258af','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ECAN NAKLİYAT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'a123325e-61e6-52f8-96aa-4b4060a57087'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-30','GÖKTUĞ CAN','ECan  nakliyatı son ziyartimde Göktuğ bey yapılacak kampanyaların iletilmesi talebi üzerine Continental ile paylaşılan listeden ilgili olan kalemler Göktuğ beye iletildi. Diğer çalıştıkları markalar ile araştırma ve mukayese yaparak dönüş yapacaklarını ilettiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a195411a-e20f-56d3-8b41-30b78aa74588','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NEMLİ TAŞIMACILIK' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'ff813488-fbd1-52a4-84b0-dfe90edd8552'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-30','LATİF BARİKA','Nemli taşımacılığın Eskişehir şantiyesinde bulunan L150H volvo loder üzerinde bulunan 4 adet lastiğin bandag olarak yenilenmeye alınması için ilettiğim teklif kabul edildi  Muğlada kirada bulunan diğer loder 2 hafta sonra şantiyeye geldiğinde  lastikleri yenilemeye alacağız. Nemliye bölge Brisa bayisi Özkan 90 adet Tbr Lassa Bridgestone lastiğin denenmesi için Brisa destekli bedelsiz olarak göndermiş. Yine çıkan lastikleri bandag olarak yenilenerek Bandag ın nemli sahasında çalışma performası ölçülerek mevcut rakibi petlasa göre farkı ölçülecekmiş. Nemli Petlas lastikleri direk petlasın kendisinde aldığını belirtimişti. Bizim Nemli ye bu dönem hizmetimiz  yeni ve yenileme iş maknası üzerinden ilerleyecek. İlk yenileme işimizin anlaşmasıda yapıldı. Bu Hizmetimiz sayesinde  Tbr grubundaki lastikler içinde gelişmeleri takip etmek için  yakın planda olmamızıda sağlayacaktır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('62825693-002d-5d7e-b951-4b51c4047c06','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURSA BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'508014a9-495c-58a1-b288-ab581752d478'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-30','FURKAN ATEŞ','Bursa Beton için geçen hafta verdiğim 3 adet 23.5 R25 yenieme teklifimiz için Atlıdan da fiyat aldıklarını Satın almada ilişkide bulunduğum Furkan beyden aldım. En son yaptırdıkları yenilemeyi geçen yıl sonu atlıya yaptırmışlar. Bilgi üzerine teklifimiz de günceleme yaparak yenileme işlemini aldık. Turgaın önümüzdeki hafta yapacağı rutta 2 adet yedek ile 3 adet 23.5 lastiği yenilemey alcağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5f62fd58-a964-56ff-ae9b-09124f94617a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ECRİN LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'3854e357-d91f-5ab7-b28a-3b8cc672ff83'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-06-30','MEHMET GÜLLÜ','Ecrin lastik Mehmet bey B2B sisiteminden 12 adet 315/80 maden tipi lastik girişi yapılmıştı. Peşin yapılan havale ödemesine istineden  lastikler bu gün tesli oldu. Mehmet bey Hubtrac markasını bir süredir farklı kanallardan tedarik ederek sattığını ve müşterilerininde memnun olduğunu fiyat performans ürünü olarak görüyor. Firmanın stok marka çeşitliliği çok fazla uygun olarak piyasdan bulduğunda sürekli peşin avantajı ile alarak alımda kazanma stratejinde . Yol yardım hizmeti oldukça yoğun olan firma genelde taktığı lastikleri satışını yapıyor . B2B sisitemimizi kullanmayı artık terübe ettiğini sık sık ihtiyaçlarda kıyaslama yamak ve alışveriş için kullnacağını belirtti. İlk işlmein gerçekleşeme sevk hızı ve tasilat süreç yönetimi firmamıza olan güveninide arttırdığını iletti.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2947a2c2-f8b2-5e44-8956-13bc49dca50f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OYAK BETON' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'74574880-0e4b-5a83-8dfc-51282f5f3aa5'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-06','METİN KAYTAN','Afyon Oyak beton Kademe sorumlusu Metin bey Afyonda bulunan Beton santrallerinde 6 adet mikser 2 adet pompa olduğunu iletti. Fakat bu tesiside yakın zamanda araç sayılarının artabileceğini ilettiler. Tüm yeni lastik alımlarının Ankara merkezlerinden yapıldığını Son alımlarının tamamının Petlas marka olarak gönderildiğini ilettiler.  Petlasın bölgede büyük firmalardaki potansiyel artışı çok dikkatimi çekiyor. Bölgemde toplantılarda gündemde olan Prelli markasının ağrrlığını gözlemlemiyorum . petlas öncelikli olmakla beraber Hankook da bölgede konuşulan ve sorulan grupda yer alıyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5f7934cc-2e45-54ca-b353-0b6f67ada818','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YÜKSEL MERMER' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'c6a9f719-6de5-5050-9599-56b6779de966'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-06','YÜKSEL AŞKIN','Yüksel mermer Bilecikde bulunan ocakalarını besleyecek kadar üretime açmışlar. Mermer sektöründe bej satışının çok rağbet görmediği için işlerinin % 30 kapasitede üretime devam ettikleri belirttiler. Fabrikalrında çalışan sayısınıda doğru orantılı olarak azaltmışlar. Mermer sektöründe firmaların yönetim tarzı günlük doğaçlama şekline dönmüş. Satışlarıda alımlarıda günlük planlar üzerinden ilerliyor. Firma sahipleri nin  herhangi bir strateji si mevcut değil .Bilecikde bulunan ocakalarında Loderin ön lastiklerinin bölgeye yapacağım ziyarette kontrol edilerek bilgilendirmem istendi. Programa aldım .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('861740af-4087-5cd8-bf69-a36a0e7de635','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARFEN' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'d51e9c98-0957-59ed-97ac-c45eb2cc36f7'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-06','AYHAN YAKUP','Karfen firması Afyon Eskişehir arasında ki yol işini almış. Yaklaşık 4 yıllık bir proje olduğunu belirttiler. Yenileme yi Trabzon Yılmazlar lastik ile çalıştıklarını Yeni lastik alımlarında en son İş makinası lastşklerşni Starmax olarak aldıklarını ve denediklerini belirttiler. Yılmazlar Lastiğin Trabzondan gelerek yenilenecek lastikleri Afyondan aldığını ve geri getirdiğini belirttiler. Şantiyede 37 adet kamyon 7 adet lastikli iş makinası bulunduğunu Kamyon grubundaki yeni lastikler için Şirket merkez satın almalarının İstanbulda olduğu ve Adil Önderin ilgilendiği öğrendim  İletişim bilgilerini aldım. Öncelikle mail ile KRB ninde ihtiyaç durumlarında teklif verilebilmesi için irtibata geçeceğim. İletişimin durumuna göre Uygun bir zamanda istanbul merkzli frma ziyaret planına ilave edilebilir diye düşünüyorum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f8edf24b-5b5a-5fe0-8ca0-eb95cc8dee1f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKTAŞ İNŞAAT' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'31f4bd4a-7cff-56b3-9e65-0563a45b554a'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-06','RAMAZAN YARGI','Maktaş firması Kırka Bor işlermesinin ana Taşerönü konumunda Diyarbakır merkezli firma dan bçlge tedarikçileri ticari yapısında  oldukça memnunlar. 2 yıllık taahhüt sürelerinin dolmasına 6 ay kalmış fakat yeni ihale içinde sıkı hazırlandıklarını belirttiler. Lastik atölyesinide gezme şansım oldu. Lastiklerin önemli bir kısmı Petlas marka. Bir mikarda Prelli onalarda yeni araçlala gelenlermiş. Son alımların Petlasdan  fabrikadan direk aldıkları bilgisini ilettiler.  Ben stokladıkları alanda 1.000 adet civarında sıfır petlas gözlemledim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5555b438-6a8b-5373-89b6-d8549cae1f5a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AFYON ROT BALANS' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'cb2bea0e-80d1-5076-8aa4-5581ce1d6b1c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-06','BEYTULLAH KÖKEN','Afyon rot balans firması Bölge petlas bayisi beytullah bey geçen yılki potansiyeli koruduklarını belirtiyor. Petlas markasının diğer markalara göre piyasada  daha kolay satılır duruma geldiğini belirtiyor. Firmaya yapmış olduğum 2. ziyarette Kumho marka ilk ziyarette ilgidar olduğu Kumho markası için stok planlamasında değerlendireceklerini belirttiler. Geçmiş dönemden Kumho markasını tanıdıklarını Kumho çalışılabileceğini düşünüyorum. Bölgenin Brisa bayisi Özkan otomotivden sonra gelen güçlü firmaları arasında . Ticaretin zyaretlerle gelişebileceğini düşünüyorum','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('61af2331-ffe3-505d-977b-2538b0621933','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UÇAR LASTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ec9eb7ab-b448-50aa-a4ee-1b3698d1471d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-07','ABDULLAH UÇAR','Uçar lastik İş makinası tarafına bakan Abdullah  bey en son aldırdığımız lastiklerde bulunan çiviler neticiesinde 3 adetini yenileme yapamamıştık. Hem gönlünü almak hemde son durumları öğrenmek için yaptığım ziyarette Bizden dönen lastikleri Ova kente gönderdiğini onlar yenilemeyi yaptığında fotoğraflarını benimle paylaştığını iletti. Bölgede iş makinası servis  hizmetleri olduğu için yenileme işleri oldukça fazla .Bizde yenilemek üzere sorunsuz lastik çıktığında vermesi için gerekli gönül alma sağlandı.  Bölgede Karadenzililer vinç ile çalıştıklarını öğrendiğim için elimizde olan Maxam vinç lastikleri bilgisinide paylaştım .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c14dc455-8c27-5fd9-a5bc-f26a4521d34e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FİRST LİNE LOJİSTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8183519e-dc13-5759-b4b8-33215a2fb9b2'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-07','ORHAN YÜCEDAĞ','First Line firması Mobilya sektörünün yoğun olduğu İnegölde konteyner nakliye hizmeti veriyor. Mobilya üreticilerinin ürünlerini İhracat için gemlik limanına taşıyorlar. Firma bünyesinde 10 adet dorse 7 adet çekicileri mevcut.Çekicilerde 315/ 70 ve dorsede 385/ 65 ebatını kullanıyorlar . Dorsede Yakın güzergahda çalıştıkları için Karkas olarak satılacak 385/65 ebatını alabileceklerini yenileme lastiklerden dorsede randuman alamadıklarını belirttiler.  Yeni veya uygun buldukları karkasları satın aldıklarını belirttiler. Firmanın kendi bünyesinde yol yardım aracı olduğu için ve sadece Gemlik çalıştıkları için sorunları hızlı çözebiliyorlar. Çekicilerde uygun olan her markayı  kullandıklarını belirttiler.htiyaç olduğunda haberleşeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('263f125b-3c2f-51c0-b2d7-7df1b20bb358','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GARANTİ İNŞAAT HAFRİYAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'40791f93-fb4f-55b7-a262-a5406ba4030f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-07','ORHAN TÜMTÜRK','Garanti inşaat hafriyat Yenişehir bölgesinde uzun yıllardır şehir içi hafriyat işleri yapıyırdu . Parça işlerde karlılığın çok azalması sebebi ile risk alarak Yenişehire yapılan  org. Sanayi dekapaj işini almışlar. Yaklaşık 3 yıllık bir iş olduğunu belirttiler..Makina parklarını genişletmişler. Ekskavatör  ağırlıklı makina parkları olsada 2 adet lastikli loderleri ve 5 adet kamyonları mevcut . Eski dönemden tanışıklığım olan firma nın potansiyelli ve ödeme sorunu olmayan işe sahip olması sebebi ile daha yakında takip edeceğim. Ürün ve hizmet bilgilendirmesini yaptım. İhtiyaçla da irtibatta olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4fc395f1-d79c-50bc-9110-133602bd7b07','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARADENİZLİLER VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8ac19e3d-2569-5129-8e22-f6ad6956202b'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-07','MESUT YILDIZ','Karadenizliler vinç İnegöl ve çevresinde hizmet vermekte . Firma bünyesinde 20 adet Vinçleri mevcut  . Lastik ihtiyaçlarını genelde İnegöl Uçar lastikle çalıştıklarını iletince sohbeti farklı yönettim. Uçar lastikle bizde çalıştığımız için çok fazla detaya girmedim. Uçar lastikde inegölde Continental bayiliği yapıyor. İş makinası yenileme ve Eftal in binek tarafında ticareti de mevcut . Ziyaret sonrasında uğrayacağım Uçar lastiğe Elimizde olan vinç lastikleri hakkında bilgi vermek için notu aldım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3b21357d-5935-5433-bae0-484136cbfe49','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='A BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'c8dededc-0604-59bc-9c9d-651eb8dd1d58'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-07','İSMAİL SERİNKAYA','Yenişehirde bulunan A beton firmasının Bursa merkezli AHS madenciliğe ait olduğu bilgisini aldım. Bursada Agrega firması olarak tanıyorum. Yenişehir ve Karacabeyde Konkardato ilan eden Teknik betondan her iki beton tesisinide almışlar. Yenişehir tesisinde yeni aldıkları 8 adet mikser 2 adet pompa ile çalışıyorlar. Yen gelen mikserlerin altında Prelli lastikler mevcut. Frima beton santrallerini alalı 1 yıl olmadığı  ve araçalrda yeni olduğu için henüz lastik ihtiyacı oluşmamış. Bursa merkezlerinden satın alma departmanlarından alımların yapıldığı bilgisini aldım. Bursa merkeze program yaptığımda uğrayacağım. Satın alma sorumlusnun bilgilerini aldım .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e13312b4-fdff-5783-841e-02df3c0b75cd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='V BETON AREGA' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'878b3366-7611-5629-b6fb-8590d40cf94d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-07','NAİM DEMİRBAĞ','V Beton Agrega firması Bölgede  beton üreten firmalara ham madde sağlıyor. Şantiyesinde 2 adet lastkli loder 6 adet kamyon 3 adet tırları mevcut . Bozüyükde geçen haftalarda Lassa dorse satışı yaptığımız Arı betonunda ortaklığı mevut. Şantiyr uzun yıllar adapazarı merkezli Kuzey beton tarafından işletşlmişti. Kuzey betondan agrega tesisi devir olarark alınmış. Naim bey İş makinası ve Kamyon lastik alım ve yenileme durumunda Bursa Eskişehirden fiyat aldıklarını belirtti. Arı betınla ticaret yapılmış olması V begraga ilede iletişimin hızlı ilerlemesini sağladı. Tüm lastik ihtiyaçlarında irtibatta olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1534e7d9-fe90-5b91-8db6-b65dfc5381ce','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e6c4c63a-1a2c-5a2e-9e1e-6399d789e3a0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-08','MURAT CEYLAN','Ünaldı madencilik Yetkilisi Murat Ceylan ile Ünaldı madenciliğe ilk yapılan 4 adet iş makinası yenilem işlemine ait 90 gün anlaşılan ödemenin gün öncesinde hazırlığını yapmak istedim. Murat Ceylan ÇekleriN Her ayın 25 inde hazırladıklarını belirttiler. 25 Temmuzda anlaşılan vadede çekimizin hazrı olacağını talep edersek direk merkezimize sevk edebileceklerini belirttiler. Merkez finans irtibat bilgilerini paylaştım. İş makinasında Yedek sıkıntısı bulunan firmaya elimizdeki Yokohoma lastikler hakkınada bilgi vererek en az 4 adet 26.5R25 ağırlığındaki ebat için bulundurmanın faydalı olacağını aksi taktirde yenileme süresinde karşılacakları başka problemlerin makinanın yatmasına sebebiyet vereceği izah edildi.  Ostim den bir firmadan Yeniye yakın 26.5r25 karkas bulduklarını , ekiplerinden bir kişiyi gönderek tepit sonrasında  lastikleri alabileceklerini belirttiler. Takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('667573b4-e3f2-54ee-8348-8acba75c583e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YILMAZLAR MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'1bb4e198-d106-5b8c-99fd-f840a1c80a9a'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-08','FATİH YILMAZ','Kemal in müşterisi Yılmazlar maden Kemali izinli olduğu için dönemde  aramış. Kemal bu hafta Kütahya programımda uğramamı rica etti. . Yılmazlar madencilik sahibi Fatih bey depolarında bulunan 1 adet tarafımızdan yenilenmiş stokalarında bulunan  26.5R25 lastiğe eş talep ediyor.Elimizde bulunan uygun karkasla  50 mm VSNT desen yenlenmiş 1 adet  radyal lastik talebi ile ilgili görslleri ve notları Kemale ilettim . Konu ile ilgienecek.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('991b594a-1e0c-54ac-ba8b-73dfdbecc906','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SE-BA LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'618790e1-8a2b-5587-b15e-8d507ab26ddf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-08','SERKAN BAŞER','Seba lastiğin de Tavşanlı kömür madene bağlı işlerinde bayram sonrasında sakinlik mevcut. Yenilemek için anlaştığı -frmalasın lastikleri beklettikleri belirtti. Biz önümüzdeki hafta Turaya bölge programı yapacağız. Ünaldı madenden 4 adet Seba lastikden 2 adet iş makiansı  yenilemeye alacağız. O tarihe kadar bekleyen lastiklerden haber gelmesi durumunda adet de artış olabilir. Fakat şu an müşterilerinin beklettiği iş makinası lastiğinin 10 adet olduğunu fakat müşterileridne artık eski hızda lastik karar vermediğini iletti.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5d87a19f-78db-5ae9-9aae-6a2d3a587f18','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYKA MADENCİLİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'d3730826-815b-5155-92d3-d947b12014a6'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-08','MEHMET BİLEN','Mehmet beyi son ziyaretimde ilettiğim Lassa ve Kumho teklif sonucu ile ilgili ziyaret ettim.Mehmet bey bu sezon ne kadar çalışacaklarını kestiremediklerini . Gelen talepler e göre ocağı çok fazla açık tutmayı gerektirecek kömür talebi olmadığını belirtti.  Üretim için ekibi topladığını şu an stok yaptıklarını satış olmassa belli bir stok dan sonra durma kararı verebileceklerini ilettiler. Araçların üzerinde lastiklerin durumunu  iyi olduğu almayı planladıkları lastikleri stoğa düşündüyor. Bu sebeple 1 yıl stokda lastik bekletmek istediği için alımı bekletiyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('741e2dac-7102-55d7-9a12-1c1cdd000243','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞİRİN NAKLİYAT' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'8136c305-0a8e-5cac-8f0b-a0839012b6bf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-08','MESUT KAYA','Şirin Nakliyat  sorumlusu Mesut bey   Kümaşın tüm nakliye işlerini yaptıklarını genelde  315/70 - 315/80   385/65 kullanıyorlar . Lastik yenileme işini Dirpa ile çalıştıklarını . Şu an dirpadan ayrılan SE BA lastik Serkan ile çalıştıklarını belirttiler.Son alımlarını Konyadan  Matador marka olarak aldıklarını fakat genelde Goodyear kullandıklarını belirttiler.  Takip edilmesi gerek bir firma olduğu için 2. ziyareti düzenledim . Bizimde çalıştığımız Se ba lastik Serkan da sonraki yeni TBR alımında bize destek verecek .  Se ba sadece yenileme TBR ve İş makinası ile ilgileniyor Yeni lastikde bölgede bize desteği zamanla artacak .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8078a593-85ca-5dc2-a1cd-a0f2c1bf2863','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CEBECİ İNŞAAT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'0c62bb78-893c-5563-ae9b-2a2cac36bf97'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-09','FARUK CEBECİ','Türk madin ile birlkte bölgeye de çalışmaya devam eden nadir firmalrdan Cebeci inşaat bölgede İnşaat ,Devlert ihale taahüt işleri ve taş ocakları mevcut. Faruk bey taş ocaklarında 12 adet kamyon 2 adet lastikli iş makinası olduğunu belirtti. İhale ile aldıkları projelerin devam ettiğini belli bir potansiyelde çalıştıklarını belirttiler. Lastik ebaları 315/70 ve 385 /65 ağırlıklı. Lastik alımlarını tek bir yerden yapmadıklarını ihtiyaç olduğunda fiyat toplayarak marka ,fiyat ve ödeme şartlarına göre değerlendirpi sonuca verdıklarını ilettiler. Sürekli talep ettikleri bir marka da mevcut değil. Firma sahibi Faruk beyin  hatırlı hemşerisi kanalı ile yapılan ziyaret oldukça olumlu geçti. Tüm iş makinası ve kamyon lastiği alımlarında bizlerden de fiyat alacaklarını ilettiler. Firmayı daha sıkı ve yakından takip edeceğim. İlk ziyarette tanıdık desteği aldık ama sonrası artık bizim kuracağımız ilişki ile ticaret olgunlaşacaktır.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aa71ba4a-e615-5f1f-8bb9-92ae1fced382','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TURK MADİN A.Ş.' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'9031fc67-fb87-50df-b2a3-062f6eea6fbc'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-09','FİKRET HAN TARHAN','Bölgenin potansiyelli çalışan fiğer bir firma Turk madin . Mihallıççık Kavak bölgesinde krom madeni çıkarıyorlar. İşleri oldukça iyi ihracaata çalışıyorlar. Tünel içerisinde kullanılan 8.25-R15 ebatlı lastikleri Michelin marka Gemlik Solaksubaşından , Kamyon ve iş makinası Yenilemeyi Eskişehir Ataser lastik ile, Kamyon Yeni lastiği Ankara kardeşler Ulaşımdan lassa tedarik sağladıklarını belirtiler. Firma bünyesinde lastikli olarak 10 adet kamyon 5 adet loder, 8 adet yer altı LHD makinaları mevcut .  Oldukça potansiyelli olan firmanın şantiye sorumlusu Fikret bey lastşk ihtiyaç durumunda teklifleri  topluyor. İstanbul satın alamaya iletiyor. Satın alma firmalar ile istişare ederek alımı gerçekleştirdiğini belirtiyor. İş makianalarının hepsi 23.5R25 kamyonlar  315 /80 kullanıyorlar. Lassa Kamyon lastiği ve  İş makinası yenileme konusundaki hizmetlerimizş konusunda bilgileri verdim. Bölgenin Cebeci ile birlikte takip edilmesi gereken firması. Firma lara ziayaretleri sıklaştıracağım','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9d35e77e-e1e9-5eca-9b1e-be23964fc485','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞAHMERSAN' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'daf6bbc5-7300-59e0-9db2-efbc6ef17a5c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-09','İBRAHİM ŞAHİN','Sivrihisar bölgesinde mermer ocağı bulunan şahmersana geçmiş dönemde 2 adet 29.5R25 Bridgetone satışımız olmuştu. Firmanın üretimi durma noktasına gelmiş . Stokalrında buluna hazır ürünlere talep olursa satıkkalrını yeni üretim yapmadıklarını belirttiler. Bu günlerde de Bura orhaneli Bölgesinde  üretilen Siyah tabir ettikleri taş dışında mermer sektörü durma noktasına gelmiş. O bölge bulunan Altınsoy mermer ve Özerler mermerle zaten firmamazın ticarti Kemal yönetiminde mevcut .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e05950a9-b0ad-5a6c-bdd1-876ce249bf65','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BULUT MERMER' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'405f0905-0c17-5739-91c8-20430273ff94'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-09','İSMAİL BULUT','Bulut mermer bölgede ocak faaliyetlerini tamamen durduran firamlar arasında . İsmail bey ile telefon ile konuştuk. Faaliyeti durdurdukalarını iç piyasa da bellir bir talep oluşmadan üretim planlamadıklarını , olan işinde karlılık sağlamaması sebebi ile böyle bir karar aldıklarını belirtiler. Ocakda bulunan iş makinalrını ve kamyonları fabrikaya çekmişler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('770300a6-6211-56e5-9ae9-4164bc018be7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TURAN BEKİŞOĞLU MERMER' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'5a2d5d52-9fc5-53fd-810a-58fa5fee34b4'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-09','MESUT KAYA','Turan bekişoğlu mermer faaliyetlerine Martura mermer olarak devam ediyor. Sivrihisar ve Denizlide mermer ocakları mevcut her iki ocakda düşük kapasitede çalıştığını belirttiler. Mermer sektöründe büyük firmaların tamamı durmaya yakın bir potansiylde çalışıyorlar. Bunu firmalar kapandı olarak değerlendirilmesinin önüne  amacı ile yaptıkları  çok net. Bazı firmalar durduktan sonra tekrar başlamanın çok zor olduğu şeklinde yorumluyor.Çinde inşaat yapılanmasına  hammadde sağlayan sektör temsilcileri,  azalmış  iç piyasaya dönünce ,ihtiyacın çok üzerinde bir tedarikçi topluluğu durumuna geldiler. Yakın gelecekte Mermer firmalarının bir çoğu farklı sektörlere geçmekte başka çareler kalmamış durumda.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e60666db-b03c-5fc5-afc2-a02c41a5fc39','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ARI BETON' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'f5bdd09c-9fdd-56b3-ab4e-ab0d52eae61f'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-13','VURAL SİPAHİOĞLU','Arı betona geçen ay Brisa grubunda ilk lastik satıımız olmuştu . Firma sahibi Vural bey 25 olan araç sayısını azaltma yönünde araştıma yaparken . Söğütte bulunan Gübretaş altın madeninn yeni yapılan tsisinin beton işini aldığını o işin kendisini en azından yıl sonuna kadar başa baş çıkaracağını belirtti. Başa baş çıkmaya sevindiği günleri yaşadıklaını beliettiler O iş başladığında lastik ihtiyacınında harekentleneceğini yine Lassa olarak alış verişimizin devam edeceğini belirtti.İlk satışıız tesadüfen ziyaret yaptığım anda lastik alımı konuşurken olması ve senin nasibinmiş şeklinde başlamıştı.  Bu tür yeni ticaret başlayan firmalara kısa sürede yapılan ziyaretler artık ihtiyaçlarda ilk akla gelenler olunmasınıda sağlamakta. Artık arı betonda bizden fiyat almadan lastik alımı yapılmaması konumuna gelmiş olduğumuzu düşünüyorum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5f0b3b46-c820-5bae-9ebd-014433abdea2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TÜRE VİNÇ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'3b80f7c1-adc5-5c3f-a7eb-7348bfdaaac9'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-13','VEYSEL TÜRE','Veysel bey  şartlar ne kadar kötü olursa olsun genelde pozitif düşünce tarzı ile davranışına alışkındık. Fakar bu ziyarete ilk defa negatif düşünceleri paylaştı. Vinç sektöründe çok olumsuz zaman gördüğünü fakat bu durumun çok farklı olduğunu yılbaşında bu yana hiç çalışma olmasaydı daha çok kazılnılırdı şeklide yorumu mevcut. Bölgede ekipmanı en geniş ve çok fazla iş koluna hizmet veren makinalara sahip olması sebebi ile potansiyeli her zaman yukardaydı  . Makina çalışma saatlerinden de potansiyelin e kadar düştüğünü çok iyi gözlemlediklerini belirttiler. Lastik ihtiyaçlarının da doğru orantılı olarak stok yapmadan ihtiyaç olduğunda iletişime geçebileceğimizi. Ondada genelde acil olduğundan dolayı yakın bölgede hizmet ile birlikte çözdüklerini belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f37d7e13-d431-552c-902c-2a9518acb150','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BOZÜYÜK BELEDİYESİ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'f8c73ff0-c66b-50ab-96b2-7d5d3637f0af'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-13','ERSEL PİŞKİNEL','Bozüyük belediyesi kadme satın alma konularından sorumlu Ersel bey le geçmiş dönemde çalıma fırsatımız olmuştu.  Düzgün vadesinde ödeme şekli olan ender belediyelerden . Halende de araı hazır olmayan alımalı yapmıyorlarmış. İlçe belediyesi olmasına rağmen tüm makina ve ekipamları belediye öz malı  kiralık kullanmıyorlar. Kamyon grubu lastikleri ihale ile aldıklarını. İş makinası yenileme ve yeni  lastiklerini doğrudan temin kriterleri için yapmaya çalıştıklarını ilettiler.İhtiyaç gündeme geldiğinde iletişimde oacağız.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cdbfcbee-9a39-57dc-9ccc-4cb01f977455','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAPI YAPI' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'e5fbd3af-ffab-5b46-b0b6-bc7022254836'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-13','VEYSEL ATLAR','Yapı  yapı makine ikmal sorumlusu Makine mühendisi Veysel bey  lastik alımlarını ve yenileme işlemlerinin İstanbul merkez satın almalarında bulunan Doruhan Saka bey tarafında yapıldığın belirttiler. Bu yıl başında yenileme konusunda Tatko ile sözleşme yapıldığı tüm yenileme işlerinini tatkonun yaptığını belirttiler . Her yıl sözleşme yenilendiğini eklendi. Yeni lastik alımı konusunda son alımı Hafriyat tipi Prelli aldıklarını Bir önce aldıkları Lassa ile şantiyede şu an test aşamasıdna olduklarını belirttier. Yeni lastik alımında tüm firmalardan fiyat alarak adetleri karşılayabilecek firmalara işi ihale ediyorlar . En son alımı Prellinden 13R22.5 ve 315/80 Saedece hafriyat çeker olarak 500 adet lastik alımı yaptıklarını belirttiler. Bir önceki alımı Trabzon Yılmazlardan yapılmış. 2022 yılında Yapı yapı firmasından Yılmazlar adına lastik alarak yenileme işlemini yapıyorduk. Faturayı Yılmazara kesiyoduk. O dönemki süreci ben yönetmiştim. Potansiyel büyük fakat bu dönem için yeni ve yenileme konusunda  bizler için çok uygun koşul tespit edemedim. Makina şefi ile tanışıklığımız başlaması en azında şantiye şartlarına da Prelli ve lassa karşılaştırmasının sonucu nu almak bizler için önemli olacaktır. Konuyu takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5b114c3e-dc12-5cb4-828c-d06bb3f9ecda','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DENİZ GRANİT' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'bb3545b0-5f64-5ed2-988a-5ce4495c80f6'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-13','ÖMER KELEŞ','Deniz granit firması Aze Mermer ve Göksutaş ortaklığıolan ve Söğüt dudaş köyünde  Mermer üretim yapan firma Yetkili Ömer bey Bu yıl gelr gider dengesini yönetmemediklerin bu durumnda onları her geçen gün zorladığını belirttiler. Az olan üretimlerinin ihraacat a artık hiç gitmediği ve sadece iç piyasa için fabrikayaı besleyecek kadar üretim yaptıklarını ilettiler. Son yapılan Afyon furarınada taş gönderdikleri fakat yurtdışı müşterisinin talebi oluşmadığını ilettiler. İç piyasa işlenmiş ürünleri için bşr projeleri olduğunu o tamamlandığında ocak üretimine ara verebilecekleri belirttiler. Mermer ocak bünyesinde 3 adet 29.5R25 lastikli loader 1 adet 26.5r25 kullanan kaya kamyonu mevcut .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f1cc7588-8275-599a-911d-6d95cbe75178','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ETİ MADEN İŞLERMELERİ' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'ae1d1e6d-9477-51ca-99ed-2a115131e954'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-14','RAMAZAN CANKAL','Kemal arızalı lastik olduğu ve bölgeye gidildiğinde kontrol edilmesi  benden dstek istmişti. Eti maden işletmeleri Emet bor tesisinde yenilenme sonrasında arıza meydana gelen 17.5r25 greyde lastiğinin tespiti yaptım. Üretim  ile yaptığım görüşme sonucunda lastiğin İSB ye alınarak kontrol ve tamir işlmemi yapacağız.  Aynı zamanda Eti maden kademe sorumlusu Ramazan bey  bu hafta yeni işmakinası alımı için merkezleri Ankaraya ihtiyaçları gönderdiklerini içerisinde 17.5R25- 20.5R25 - 440/80-28  - olan ihtiyaçları Birdgestone veya Michelin olarak alacakalarını belirttiler. Kemal e durumu ilettim. Bu hafta sonu veya haftaya ETİ maden satın alma portalından görüntüleneceğini ilettiler. .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ce246900-3b92-52aa-9c12-244d2c6a0ff0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'e6c4c63a-1a2c-5a2e-9e1e-6399d789e3a0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-14','MEHMET ÜNALDI','Ünaldı maden sahibi Mehmet bey ile yapılan görüşmede dün sizle istişare ederek oluşturduğumuz TBR ve İş makinası teklifimizi ziayretle izah etmek için istedim. Böyle olunca yapılacak alım ile ilgili farklı detaylar bilgilerde sahip oldum. Yaklaşık 150 adet Hafriyat tipi TBR ve 4 adet 26.5R25 iş makinasından oluşan teklif için Günmarlas dan - Bizden - Atlıdan Eskişehir Aksoydan fiyat istemişler. Teklifleri Atlı haricideki tüm firmalar iletmiş. Atlı yetkilisi Cuma gününe kadar alımı bitirme bütün lastikleri ben sana herkesin altında  fiyattan vereceğim şeklined bilgi vermiş . Bende Mehmet beye Atlı dan alıma karar veririseniz bizden de en son istişare etmeden alıma karar vermemesini rica ettim. Bu işi Günamrlas dan daha çok Atlı yönetecek gibi duruyor .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8f5b3099-3dd6-58b1-9ddb-a5ec1b5047d6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYKA MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'116c00e3-4b44-5df6-8a40-6e899448edbd'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-14','MEHMET BİLEN','Mehmet beye Hafriyat tipi Kumho ve Lassa teklifimiz önceki ziyarette iletilmişti. İş potansiyelinin düşük olmasında  dolayı alıma karar vermemişler. Stokalarında olmaması eski işler olmadığı için sıkıntı yaratmadığı. Lastikle ilgili yaşanan sıkıntılarda tamir veya ihtiyaç kadar tedarik yöntemini aciliyet olmadan yönetebildiklerni belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('13d94bbb-2bde-51b4-a53a-3d3934539b68','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İSA OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'677bd85a-de63-50ef-87f2-0f96d9e3a7eb'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-14','İSA ERDOĞAN','İsa oto lastik tavşanlı bölgesinde binekden iş makinasına kadar tüm gruplarda yol yardım hizmeti veriyor. TBR grubunda Ling Long ağırlıklı olduğunu TBR yenilemeyi Doruklar ile  İş makinası yenilemeyi Ova kent ile çalışıklarını ilettiler . Kömür ocakları bölgesinde iş makinası tamir konusunda oldukça etkinler. Yeni İş makinasına girmediklerini . O konuyu müşterilerilerinin kendisinin çözdüğünü belirttiler.KRB ürün ve hizmetlerimiz konusununda bilgiler iletildi. ihtiyaç oluştuğunda haberleşeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('59523024-b346-506b-8e75-e65a5d027d74','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SE-BA LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'618790e1-8a2b-5587-b15e-8d507ab26ddf'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-14','SERKAN BAŞER','Seba lastik Serkan dan destek alarak aciliyeti bulunan Ünaldı madenin 4 lastik sökülme ve İSB ye ulaştırma programını yaptık. Aynı zamanda Ünaldı madene verdiğimiz İş makinası yeni lastik alımı ile ilgili Ünaldı üzerinde etkisi olan Serkan dan Yokohoma Tercihi ile ilgili destek alacağız. Serkan lastikleri perşembe günü kendisi İSB tesisine getirerek hem tesisi gezmek hemde TBR yenileme konusunda  Doruklarla ilişkisnin bozulması sebebi ile TBR yenileme üretimini görmek istdedi. Kütahya bölgesinde yüksek  adetler de TBR yenileme potansiyeli mevcut.   Perşembe günü benimde kendisine eşlik etmemi istedi. Bir değişiklik olmassa bende  Perşembe günü İSB de olmayı planlıyorum .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('066beb05-8f0f-588b-9e37-d9895e37f6d6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EGE TAŞ KÖMÜR' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'8dfb3b86-d902-52fe-b1f9-31263b72c65d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-14','MESUT SARIOĞLU','Ege taş kömür firmasına geçmiş dönemde Brisa grubu satışımız olmuştu. Firmanın tunçbilek santiyesinde faalitleri devam ediyor. Satın alma yetkilisi Mesut bey ile geçmi dönemden tanışıklığımız mevcuttu. TBR lastik alımı konusunda tekrar çalışmaya başlanması için tedarikçi kaydımız yenilendi. Bir süre çalışma olmadığı için tedarikçi kaydımızı kapatmışlar . Firma bünyesinde 17 adet kamyon 2 adet lastikli loder mevcut . Genelde lastik tercihlerini orta kalite lastiklerden yana yapıyorlar. Kumho hakkında verdiğim bilgiler neticesinde ilk ihtiyaçda teklifi Kumho olarak deneyebileceklerini belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('687b05a0-644e-5bd2-b65b-3be46342726d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÖSENLER LOJİSTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'10bd9111-286f-519a-be88-5d3afe0b73a7'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-16','MERT AKTAŞ','İnegöl kösenler lojistik firması Mobiya sektörüne lojistik hizmet veriyo. Yurtdışına mobilya lojistiği yapıyorlar. Firma bünyesinde 14 adet Tır mevcut . Bu sebeple tonaj olmadığı için 315/60 315/70 dorsedede 385/55 ebatlarını kullanıyorlar. İki yıl önce Bridgestone ve Continental kullanırken bu gün maliyetlerden dolayı en son alımı Ling long ve petlas  olarak yapmışlar. Ebatları uygun olan Hubtrac ve Kumho ürüler hakkında bilgileri aktardım.  Mobilya üreticilerinin ürtiminin azalması sebebi ile son 2 yıl yıldır İnegöl de sevkiyataları çok önemli ölçüde düşüş olmuş. Mobilya sektörü gelinen son bir yılda artık  firma sahiplerinin birikimleri ile işletmelerin açık kaldığı her sektörde olduğu gibi mobilya sektöründede karlılığın çok azaldığını belirttiler. Mobiya sektöründe  yaşanan sıkıntıların ciddi boyutlara gelmesi soncunda Cumhurbaşkanlığına firma tesmsilcilerin ziyareti olmuş . İnegöl mobilya sektörü ve ona hizmet eden tüm lojistik firmaları karlılık , kazanç düşünmeden maliyetleri karşılayacak çareler üretmeye çalışıyorlar. Yeni tanışılan firma ile lastik ihtiyaçları konsunda iletişimde olacağız','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('622f423f-3f21-50df-bc5c-c89d07f935bf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SER-EN LJİSTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'97a7cdfe-792a-53b3-99d6-3c488458c63d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-16','EMRE BULUT','Seren lojistik firmasında 10 adet tır mevcut onlarda mobilya sektörüne hizmet veriyorlar  Mobilya ya ek olarak Fresh uludağ gazozunada çalıştıkları için işlerini belli bir dengede tutmaya gayret ediyorlar. Firmanın kullandığı ebatlar 385/55 ve 315/60 Sere lojistik firmasınında tonajlı işi yok.  Ürün hizmet ve markalarımız konusunda bilgilei verdim. Mobiya sektörünin çekerde 60 yanak dorsede 55- 60 yanak yoğunluğunun çok fazla . Kışın hava şartları uygun olduğu için  yenilenemiş lastik kullanıyorlar . Yazın yeni lastik kullanımına geçiyorlar.  İlçe ziyaretlerinde  daha samimi ve gerçekçi ziyaretler oluyor. Ziyart sonrası yapmış olduğum whatsapp teklif ve talep edilen bilgiler sonrasıda firma temsilcilerinşn ilgili olduğunu gözlemliyorum. Birde piyasa şartları desteklemeye başlarsa daha keyifli işler ortaya çıkacar diye düşünüyorum. Bu gün yaptığımız samimi ve iz bırakan ziyaretler piyasalar açıldığında iyi bir potansiyele dönüecek inşallah','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('300454ca-8953-557c-b2e8-c7ae8c45c5e8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SERHAT LOJİSTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'66023a01-764c-581f-ae37-a2bfb5d6eaf7'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-16','MURAT KARATAŞ','Serhat lojistik inegöl mobiya lojistik  sektöründe aracı en fazla olan firma durumunda . Sahibi Murat bey ile yapılan görüşmede Yurtiçi Mobilya lojistik hizmeti verdikleri yurtdışı lojistik işine hiç girmediklerini belirtti. 24 adet araçları mevcut . Bu dönemde ağırlı olarak  Doğuya hizmet veriyorlar. Yie ebatlar aynı 315/60 -315/70 ve 385/55 ve 385/65 . Firma ile sohbet oldukça verimli geçti. Bu gün inegöl  ziyartimizde enerjinin en çok uyumlu olduğu ziyaret oldu.Firma işlerinin çok iyi olmasada bölgenin eski firması olması vesilesi  ile belli bir potansiyelde sürekli işlerinin olduğunu belirttiler. Yenileme lastik kullandıklarını uzun bir süredir Ovakent ile çaıştıklarını belirttiler. Şimdilik yeni lastik ile ticaretin başlanması yeterli olaktır. Kampanyalı ürünler olduğunda kullandıkları ebatlar için paylaşmamı talep ettiler.özellikle Kumho marka üzerinde soruları yanıtladım. Ucuz lastiklerde sorun yaşadıklarını Üst grubun çok pahalı olduğu için maliyetlerini çok yükselttiğini orta grubun onlar için uygun olacağını belirttiler. Yılbaşında aldıkları 315/60 Leao Multi road modelide kayma problemi yaşadıklarını bir sefer yapan araçdan gelir gelmez lastikleri söktüklerini 12 adet aldığı lastiklerin kullanmadıklarını iade ettiklerini belirttiler. İnegöl ziyaretimizde sürekli uğramanın faydalıolacağı frmalar arasına notumu aldım. Yeni tanışılmasına rağmen birsüredir tanışıklık varmış gibi uzun süreli bir ziyaret oldu.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('db82ee39-749c-5000-a902-91b3c3fc6b15','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YÜCEDAĞ HAFRİYAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'617b0976-25be-5128-9020-1dc6e42716c5'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-16','osman yücedağ','Yücedağ hafriyat sahibi Osman Yücedağ hafriyat sektöründe inegölde hizmet veriyorlar. 3 adet lastikli loder 5 adet kamyonları mevcut. 315/80 ve 13R22.5 ebat kullanıyorlar. En son yaptıkları alımı Starax olarak tercih etmişler. Geçmiş dönemde Lassa kullanıcısı oldularını  Son yıllarda lastik fiyataları arttığı için maliyetlerini dengeleyebilmek adına istemeselerde mecburiyetten tercih ettiklerini belirttiler.İnegölde yapılması planlanan 2. osb nin haberini beklediklerini fakat 1 yıkdır başlanamdığını o proje başladığında inegöl inşaat hafriyat sektörüne katkısnın çok olacağını belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('71c1dca0-6eaa-5325-a172-3d5ec372c21c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MERT HAFRİYAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'59eec46f-7eb6-5f20-a6bb-66c2f0c97b3c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-16','NİHAT MERT','Mert hafriyat Eski dönem müşterilerinden .Ekipman olarak Ünegölün en büyük hafriyatçısı konumundalar .Şu an işleri iyi olmasada Yücedağın belirttiği osb inşaatının sonbaharda başlayacağı bilgisini aldığını orada taşerön olarak görev alacağını belirtti. Nihat beye güvendiğim için  ziyarete çıkmadan internetten araştırdığım firmalar içinreferans aldım. Ziyaret planına aldığım iki firmayı Nihat beyin uyarısı ile listeden çıkarttım. İnegölde Mobiya sektörü ağır hasarlı, inşaat sektörüde şu an için iç açıcı olmaması sebebi ile etkilenen firma sayısı bir hayli artacak gibi görünüyor. Mermer sektörünün yaşadığı sorunun bir benzerini bu gün İnegöl mobilya sektörü yaşıyor. Bir haber kanalında Mobilya sektöründe ağırlığın tekstilde olduğu gibi Mısıra kaydığı yönünde haber okumuştum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('33f436b6-20a7-514c-a4ca-6a72bc6c88cd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UÇAR LASTİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ec9eb7ab-b448-50aa-a4ee-1b3698d1471d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-16','BİROL UÇAR','Uçar lastik birol beye binek satışımız mevcut. İş makinası yenileme hizmetide veriyoruz. Bölgenin Continental bayisi olan Birol bey e geçmiş dönemde Brisa ürünü satışlarımız oluyrdu. Brisa bayillik haberi sonrasında bizden Brisa ürünü talep etmişti. Fakat toptana satışımız olmadığı için verememiştik. TBR grubunda da  Continental bayiliği olduğu için Kumho verebileceğimizi iletmiştim. Kumhonun bölgelerinde satılmayacağını belirtti. TBR ticareti şu dönem olmayacaktır. Çok adetli bir ticaret geçmiş dönemdede olmamıştı. 4-8 şeklinde olmuştu o adetlerde şehir dışı nakliye maiyetlerleri ile fiyatlar tutmayacak.. Ama daha önce bahsettğimiz gibi sektörler içerisinde işi iyi olan firmalar var . İnegöl 1. osb de bulunan Starwood firması sunta üretiyor ve tüm dünyaya satıyor. Kapasite artışı sebebi ile Starwood son dönemde işe yeni 100 kişi almış . Starwood firmasında 3 adet loder ve çok sayıda forklift mevcut. Loderlerin tüm lastik işlerini bizim çalıştığımız Uçar lastik hizmet veriyor. Forklift lastiklerinede bursadan anlaşmalı 24 saat kesintisiz hizmet veren Garanti forklift hizmet veriyor. Firmada 3 vardiye 24 saat üretim mevcut .Sunta nakliyesinide dış firmalar tarafında n yapılmakta.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1d1dd2c7-7b32-5ca1-ab80-3c5b3a50eeca','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EYLAS' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'5f3d55ec-effa-595c-bcde-0265ec0e97de'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-20','LEVENT SIRTALAN','Eskişehir Continental bayisi Eylas lastiğe stoklarımızda bulunan 315/80 ve 385/65 Kumhoaları teklif ettim. Continenental ve matador ın yanına alternatif lastik maraı araştırıyorlar. Kumho nun kalite olarak sıkıntı yaşatmayacağını bildiklerini eski dönemde sattıklarını belirttiler. Ziyaretlerimde Eski lastikçiler in Kumho markasını iyi biidiklerini ve güvendiklerini gözlemliyorum . Kumho sviyesindeki lastiklerden popüler ebtalar için ödeme koşullarına göre fiyat ve stok bilgilerini paylaştım. Değerlendirmelerini bekleyeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2bc80f06-4194-5c8c-9b23-7756c3720df2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÜPELİLER HAZRI BETON' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'42d0423c-33b0-569b-89f2-cdc39052c649'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-20','ERHAN NAİL KARAKAKAYA','Küpeliler beton satın alma yetkilisi Erhan bey son görüşmemizden sonra lastik alımı planlamadıkalarını alım olması durumunda bizlerden de fiyat alınması konusunun üzerinde bir daha geçmiş olduk. Son yaptıkları alımı Eskişehir Petlas bayisi Demirgözden yaptıkları bilgisi mevcuttu. Aynı zamanda alpu yolunda bulunan beton tesisleri Demirgöz lastik ile yanyana olması sebebi ile yol yardım hizmetide aldıklarını belirttiler. Bölgemdeki  beton firmalarnın da nakliye ve madencilik sektörü gibi  piyasa koşulları nın zorlaşması ve artan rekabetten dolayı alt markalara eğilimin arttığını gözlemliyorum.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0c517835-74e2-599f-abaa-741bfe38134a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜMÜŞLÜ LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'6ea39814-252c-52bc-8623-64687bd3bff5'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-20','ÜMİT GÜMÜŞLÜ','Gümüşlü lastik Ümit in Eskişehirde iş makinası dahil  4 adet yol yardım aracı mevcut.Bölgede  Yol yardım hizmetinde oldukça etkin . Yol yardımın 6 ay önccesine kadar yeni lastik satışlarını çok desteklediğini fakat son dönemde müşterilerin yenilenmiş veya çıkma sorduklarını belirttiler .Stoklarınıda bu talebe göre düzenleye başladığını belirtti. Eskişehir OSB bölgesine TBR lastik müşterilerine daha yakın olmak için açtığı şubede beklediği potansiyelin den çok uzak olduklarını belirttiler. Stoklarımızda bulunan Kumho ,Conti ve Hubtrac lastiklerin bilgilerini ilettim.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('af4396c2-045e-5e11-b60f-495fa0259452','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZKAN OTOMOTİV' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'5d823470-b267-5290-b2e8-1c416ec75a83'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-20','İBRAHİM SARITEPE','Eskişehir Brisa bayisi Özkan otomotiv Eskişehir de bulunan dükkanından yer sahibi nin ticaret yapma isteği üzerinde boşaltacaklarını ve yer baktıkları bilgisini aldım .MüşteRi ziyareti ile yaptıkları ticari satışı azalttıklarını bilgisini önceki ziyaretimde belirtmişlerdi. Vade ve ödeme problemi olmayan bir kaç filo ile çalışmaya devam ettiklerini belirtmişlerdi. Bu gün içinde binek ağırlıklı yapıları mevcut. Bu sebeple ticari tarafta Eskişehir de rekabet Aksoy - YK S - And Ünal - Demirgöz  arasında yaşanmakta.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('003a4442-78a4-51a7-bfd2-b55679e8bafa','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATG LASTİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'ce6c8f09-e0a2-594e-917e-042be990ed69'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-20','MEHMET GÜLLÜ','ATG lastiğin sahibi Mehmet Güllüye B2B sisiteminde sipariş girerek 12 adet Hubtrac TBR lastiği satışımız olmuştu .Yine geçen hafta sonun B2b sisiteminde teklif oluşturmuştu .10 adet Kumho 385/65 XA11   Peşin fiyatına Kredi kart taksit fiyatı talebi olmuştu. Bende tam istediği olmasada ikisi arasıdna bir fiyat teklifini iletmiştim. Sonuçlandırmak için yaptığım ziyarette bu hafta ay sonu kart hesap kesim tarihinden sonra  yapmayı planladığını belirtti. Alımı stoğa yapacağı için acale etmiyor. Takip edeceğim. Mehmet bey B2B sisitemimizi oldukça etkin kullanıyor.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6631bf1e-5e81-5360-a0da-5f70b3b1c933','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZESER İNŞAAT' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'9ca1cc5a-7fc3-55d7-9f0c-627343140151'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-21','CİHAN ŞAHİN','Özeser inşaat Kütahya Tunçbilek şantiyesini ziyare ettim.  Kömür dekapaj ve üretimi yapıyorlar. Cihan bey Tunçbilek şantiyesinin satın alma işlerinden sorumlu .Özeser inşaatın yol köprü baraj gibi projeleride geçmiş de yaptığını biliyordum. Şu an sadece yol işi ve Kütahyada yaptıkları kömür üretimi mevcutmuş. Kömür talebindeki azalma üretimlerini etkilemiş. 300 kişi çalışandan 100 kişi çalışana inmişler. Cihan bey işletmede 40 adet kamyon 6 adet lastikli iş makinası olduğunu belirtti. İş makinası yenileme işini antalya Uyaroğlu ile çalıştıklarını belirttiler Yeni kamyon lastiğinde uygunluk durumuna göre 13 R ebatınad Lassa ve petlas dışına çıkmadıklarını belirttiler. Çalıştıkları saha da en fazla bu iki markanın maden tipinden verim almışlar. Geçen ay 100 adet lassa aldıkalarını yine önümüzdeki ay alım yapacakalrını belirttiler. Eski alım şekline göre işin azalması ile lastik alımlarını da azalttıkklarını belirttiler. 80 adet 13R22.5 600D teklif talep ettiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('877287e0-28f1-5239-841e-aa3a94561449','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EGETAŞ KÖMÜR' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'f831a358-cd10-510c-a994-0cba5c3faed5'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-21','MESUT SAĞIROĞLU','Egetaş kömür Tunç bilek bölgesinde Özeser gibi kömür üretimi yapmaktalar. Geçmiş dönem de lastik satışım olmuştu. Sonraki alımlarıson dönemde  Atlı dan yapmışlar . Atlı Bursa - Kütahya - Bilecik Bölgesinede bilhassa maden grubu müşterilerde iş makinası yeni ve yenileme Kamyon grubunda yeni lastikde bizimde bölge daraltmamızdan faydalanarak arttırmış   .Ege taş kömür firması da azalan piyasa ile doğru orantılı olarak küçülmeye gitmiş . Firma nın talep  40 adet 385/65R22.5 310T ve Kumho XA11 modeli teklifi alternatifli olarak iletildi. Egetaş kömür e teklifi ilettikden sonra firmanın son durumunu gözlemlemek için ziyaret ettim. Firma satın alma yetklisi son dönemde ödemelerde biraz zorlandıklarını anlaşılan vadeden 20- 30 gün sarkmalar yaşansada tüm tedarikçilerin ödemelerinin yapıldığını açıkça belirttiler.  Teklifimize onay verilme durumu olursa bu konuda istişare etmeden siparişi girişi yapmayacağım','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ff092339-4b8d-5739-9ec9-94acda1dc931','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TARHAN İNŞAAT' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'a9cea3e7-32b7-5930-bcb8-222300b60fda'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-21','ALİ  BEY','Tarhan madencilik yetkilisi Ali bey Tunç bilek bölgesinde küçük çaplı bir çalışmalarının olduğunu 3 saha dekapaj işi için teklif verdiklerini anlaşma durumu olursa kapasitelerine uygun işlere başlayacaklarını ilettiler. Kömür ocakları bölgesinde  Özasil - Kayasu Tarhan gibi firmaların ekipmanlanı meşgul edecek potansiyelde ömür işinin bulunmaması sebebi ile bölgeden çekiliyorlar. Yerlerine isimleri yeni duyulan daha küçük çaplı firmalar gelmekte. Bu sebeple Tunçbilecek kömür ocakları bölgesinden az bilenen fimalardan gelecek talepleri daha yakından   ziyaretlerle takip etmek gerekecek. Kömür tecrübesi az olan firmaların bölgede ne kadar sağlıklı ve uzun ömürlü olacakları belirsizliği mevcut.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('261475c4-e2f3-5555-8a65-19354d6c4cbe','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İSA OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'677bd85a-de63-50ef-87f2-0f96d9e3a7eb'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-21','İSA ERDOĞAN','İsa oto lastik Tunçbilek Bölgesinde  TBR  ve iş makinası tamir yenileme yeni hizmet veriyor. İsa usta son dönemde Ling long ve Petlasın  bölgesinde etkinliğini arttırdığını kendisininde bu markalar üzerinde ağrlığı olduğunu belirtti. Kömür bölgesinde işlerin sıkıntılı seyretmesinin müşteri gruplarındanda marka tercihlerinide etkilediğini ilettiler. Ürün ve hizmetlerimiz konusunda bilgiler verildi. tbr yenilemede  Bölgeye düzenli rutu olan Özman (Lastik burada) ile çalıştıkalarını İş makinası yenilemede Ova kent ile çalıştıklarını ilettiler. Atlı bölgede son kullanıcıları hedeflemiş Toptan , lastikçi müşterilerde yeni ve yenileme de ismi geçmemekte.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('84a12eb1-fa90-5a5e-b261-7b1597f05064','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FATİH OTO LASTİK' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'7fedcc35-c33f-5763-8a22-20b9e67a0a60'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-21','KASIM ÇANAK','Kasım beye geçen ay kampanyadan  Continental ve Matador satışımız olmuştu. Bölgede TBR etkinliği bir hayli yüksek.  Mevcut kampanya lar hakkında fiyat ve stok bilgilerni ilettim. Continental 385/65 Hafriyat lastiği ihtiyacı olduğunu iletti. Stoklarımızdan bulunmadığı için ihtiyacı karşılanamadı . Petlas Hankook Continental ve ling long dışında fazla marka çeşitliliği yapmak istemiyor Bu sebeple Kumho konusunda çok bir ilerleme sağlayamadık.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e4d8df4e-d36f-59a4-befd-419a67e8a7be','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALSANCAK BETON' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'5c215893-43e6-5ac4-b666-b43f4dc13d4d'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-22','MUSA ALSANCAK','Alsancak beton Gedizde bulunan iki beton üretici firmasından eski ve köklü olan tesis. Santrallerinde 5 adet mikser 1 adet pompa mevut . 315 /70 ve 385/65 ebat ağırlığı mevcut . En son alımlarında fiyat avantajından dolayı Petlas tercih etmişler. Geçen yıl günlük 200- 250 m3 beton satılı yaparkenbu yılda günde 50-60 m3 lere düştüğünü belirttiler. Ürün ve hizmetlerimiz konusunda bilgileri aktardım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('adae6dc9-f04d-55a3-8ebf-9fa7c5d09f99','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GEDİZ BETON' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'9d8de94a-d643-5509-8d54-39de98e196c0'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-22','İBRAHİM BARIŞ','Gediz beton yılbaşında tesisi Emet betondan yılbaşında devir almışlar. Firma gediz de emlak işi yaptıklarını  alternatif bir iş olması açısında girdiklerini fakat çok pişman olduklarını belitrttiler Tesisi alma aşamasında aldıkları beton satış rakamları ile şu an çok fark olduğu nu belirttiler. Firma da 6 adet mikser 4 adet pompa mevcut. 3 ay önce tüm araçaların altında lastikleri Lassa olarak 70 adet İzmir den  aldıklarını belirttiler. Lassa bayiliğimiz konusunda verilen bilgiler neticesin de irtibat bilgilerimizi telefon ve muhasebe lerine kayıt ettirdiler. Tesisi aldıklarından bu güne Gediz dışında  ziyaret eden ilk lastik firması olduğumuz için . Yeni alacakları tüm lastiklerde bizimle irtibata geçeceklerini belirttiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a2aa7943-a23f-515a-9a9a-c521b803a4e2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKKİRSAN KİREÇ' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'ba135090-892c-54ca-9129-0fefd65a7d36'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-22','GÜVENLİK','Gökler Kireç sanayi Gediz de sönmüş kireç üretemi yapmaktaydı. Kireç konusunda istenilen potansyeli elde edemeyince ve ocaklarında çökme olunca yine  ocak sahalarında bulunan Agrega üretimine başlamışlardı. Bilgileri şantiyede yetkili bulunmaması sebebi ile Güvenlikden aldım. Fakat pazarı dar olan bölgelerinde agrege üretiminide durudurmuş durumdalar.. Bölgede bulunan Gediz ve Alsancak betonunda kendilerine ait agraga ocakları olması sebebi ile bölgede  pazar oluşturamamışlar  Firma bünyesinde Kamyon ve lastikli loder ekipmanları vardı fakat önemli bir kısmını satmışlar. Gökler Kireç sanayi ile aynı bölgede bulunan KİAŞ (Kömür İşletmeleri A.Ş. ye çalışan maden ocaklarının da kapandığı sadece Kiaş tavşanlı ,Tunçbilek bölgesindeki ocakları kullandığı bilgisini aldım.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1f7e9fb0-c2d8-587b-8010-462468da39ad','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLTEKİN NAKLİYAT' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'848bd7bc-284c-549d-9b66-9862adb03865'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-22','KADİR GÜLTEKİN','Kütahya OSB de bulunan Naklyeciler sitesinin tek büyük firması Gültekin Nakliyatın Sahibi Kadir Gültekin ile görüşüldü.Firma bünyesinde 2 çekici 8 kayon bulunduğu Latik markası olarak son iki yıldır. Hankook tercih ettiklerini ebatlarının 315/7022.5 ve 285/70R19.5 ağırlıklı olduğunu Kütahya da Fatih Oto lastik Kasım Çanak ile çalıştıkları bilgisi alındı.Kütahya merkezde bulunan Fatih oto lastiğe bizimde ticaretimiz başladı. Fatih oto lastik Kütahya bölgesinde Hankook markasını öne çıkarıyor. Bölgede Fatih oto lastiğin önerdiği lastik markası bölgede kabul görüyor.Hankook lastikleri ağırlıkla Eskişehir Aksoy otodan tedarik ediyor .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1326d9a1-47b6-5f7b-9fc2-544f080662f9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','61142a4f-0b15-47e0-a6af-575d0bf7aea3'::uuid,'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-23','MUSTAFA GÖKLER','Gökler ler lastik Mustaga bey ile geçmiş dönemde 17.5 jant Hafifi ticari ebatları için ticaretimiz olmuştu. Bölgde bu ebatı kullanan tarım ile ilgili araç sayısı bir hayli fazla 17.5 jant lastik satışıdandada bu yıl azalma olmasada yine bir miktar satışı olduğunu belirtti. Stoklarımzıda bulunan 17.5 Petlas ve Kumho fiyatları paylaşıldı .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aa0642f3-9b1a-564c-8922-213e00d70777','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYDINTAŞ VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a8e68155-73d4-589b-881b-1cd8e6b845fd'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-23','DAVUT YILDIZ','Aydıntaş Satın alma yetkilisi Davut bey ziyaret esnasında ihtiyaçları olan  4 adet 20.5R25 İş makinası lastiği sordu. Yokohoma ve Bridgestone aLternatifli olarak fiyat verildi. Teklifi takip edeceğim. Ayrıca 16.00r25 Vinç lastik fiyat ve stok bilgilerimiz iletildi. 20.5R25 teklifimiz ile ilgili bu hafta sonuna kadar durumun netleşeceği bilgisi veridiler.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('05f36bd1-fb52-5bf3-838d-5c59a98bcf48','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖRGÜN KALSTİT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'76db9eb8-824b-5d67-ae44-5a2bcdae7c7c'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-23','HAYATİ ÖRGÜN','Örgün kalsit bölgesinin eski kalsit üreticilerinden . Çok geniş sektörlerde kullanıldığı için işleri belir bir standartta. Her firmsadaa bu günün kronik sorunu  karlılık ve nakit akışındasıkıntılar mevcut .  Firma bünyesinde 12 adet tır lastikli olarak  3 adet loader mevcut . Lastik marka tercihini bölgede etkin olan solaksubaşından Goodyear olarak almışlar . İş makinaları yenilenmiş.23.5R25 ve 26.5R25 ebat kullanıyorlar. Kamyon grubunda 315/70 385/65 ebat kullanmaktalar . Ürün ve hizmetlerimiz konusunda bilgiler iletildi. Geçmiş dönemden de tanışıklığımız bulunan Hayati bey ihtiyaçlarda bizden de alternatif teklif alacağını belirtti.','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8060bcfc-72cc-53b4-872b-60cb97f1c606','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZÜ AYDIN VİNÇ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4f8ca525-7554-52ec-a23b-a1bc827c2634'::uuid),'5421b8b6-8292-47e8-b52a-94e3afed8f67','Murat Yener','TICARI','TAMAMLANDI','2026-07-23','FEVZİ KILINÇ','Özüaydın Liman ağırlıklı hizmetler veriyor. Fevzi bey e kullandıkları bildiğim stoklarımızzdan bulunan  245/70 R 17.5 Kumho marka lastikleri önerdim.Kumho fiyatı paylaşıldı. Aynı zamanda ihtiyaç durumunda Lassa ve Bridgestone olarakda fiyat ve stok bilgisi verilebileceğini ilettim. İhtiyaç durumunda akla geleceğimizden eminim .','{}'::jsonb,'EXCEL_MIGRASYON','5421b8b6-8292-47e8-b52a-94e3afed8f67') ON CONFLICT (id) DO NOTHING;
